long long g_thrAddMain = 0, g_thrAddOff = 0, g_thrRemMain = 0, g_thrRemOff = 0;
long long g_thrQtyMain = 0, g_thrQtyOff = 0, g_thrSplitMain = 0, g_thrSplitOff = 0;
// How much traffic each gate removed, so a zero in `sent` can be told apart from a zero in `seen`.
