long long g_lateConfirmSellItemChanged = 0;
long long g_revertRelocated = 0, g_revertRecreated = 0, g_reqConfirmNoTaker = 0, g_reqConfirmFailed = 0;
long long g_reqConfirmSendFailed = 0;
