long long g_bagRung = 0, g_bagUnparented = 0, g_bagSent = 0, g_bagApplied = 0, g_bagGhostReq = 0;
long long g_bagApplyNoPath = 0, g_bagReqNoPath = 0, g_bagReqRelocated = 0, g_bagPathMiss = 0, g_parityBagRows = 0, g_bagReqShadowed = 0;   /* cell1: reqShadowed */
