    const int nc = ItLootOwnChars((b.posOk != 0) ? b.pos : 0, cand, cuid, 4);
    for (int k = 0; k < nc; ++k)
    {
        float fp[3];
        if (ItBoxPosPod((void*)cand[k], fp) == 0) continue;
        const int d = ItBoxBackDrop(b.obj, fp, 0);
        if (d == 0) continue;
        if (d < 0)
        {
            ItBoxBackEnd(d, b.id, b.baseSid, b.boxKey, why);
            return 1;
        }
        ++g_box211f2[5]; ++g_showGive[7];
        if (ItBox211Say() != 0)
            DebugLog("[ITEMS] T-164 211 give " + N((long long)b.id) + " (" + std::string(b.baseSid) + ", our box '" + std::string(b.boxKey) + "'): "
                     + std::string(why) + " - DROPPED AT OUR OWN CHARACTER'S FEET (uid " + N((long long)cuid[k]) + ") through the ground"
                     " road. Counted itemBoxTaker boxBackToFeet, showGive droppedFull.");
        return 1;
    }
    return 0;
