/* ---- the engine calls (each one call behind one __try; no C++ object in the frame, C2712) ---- */
/* 1 locked, 0 not, -1 the question could not be asked */
int ShopItemLockedPod(void* item)
{
    if (g_base == 0 || kItemLockedCheckRva == 0 || !ItPlaus(item)) return -1;
    __try
    {
        const char* vt = *(const char* const*)item;
        ShopVoidGetFn f = *(ShopVoidGetFn*)(vt + kVtItemLockRoot);
        if (!ItPlaus((const void*)f)) return -1;
        void* x = f(item);
        return (((ShopItemLockedFn)(g_base + kItemLockedCheckRva))(x) != 0) ? 1 : 0;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
/* 1 in range, 0 out of range, -1 not asked. notMoney 0: a money trade (0x713150 passes 0 when isTradingForMoney answered yes). */
int ShopRangePod(void* gui, void* sendingTo)
{
    if (g_base == 0 || kTradeRangeCheckRva == 0 || !ItPlaus(gui) || !ItPlaus(sendingTo)) return -1;
    __try
    {
        const char* vt = *(const char* const*)sendingTo;
        ShopVoidGetFn f = *(ShopVoidGetFn*)(vt + kVtGuiRangeOther);
        if (!ItPlaus((const void*)f)) return -1;
        void* other = f(sendingTo);
        return (((ShopTradeRangeFn)(g_base + kTradeRangeCheckRva))(gui, other, 0) != 0) ? 1 : 0;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
