/* ---- T-1 B5 (design Q2): THE STOCK A SHOP REQUEST NAMES, on the game that holds it ----
   Home (kStockHome): the trader's home building's pieces in chain order - keys = the piece keys, invs = each piece's inventory (0 when
   it did not read). Caravan (kStockCaravan): the packs the keeper's squad members wear (in backpack_attach - fold 1 F3), in squad-member order (0x951BA0 takes from the
   first holder too) - keys = "wearerUid:section:x,y" (names for the log and the confirm, never box keys), invs = each pack's inventory,
   wearer = its wearer's uid (0 none). The holder's buy, sale and undo walk invs in order; the pack moves they make are this game's own
   (the wearers are run here) and publish through the drain as the wearers' pack moves. */
struct ShopStock
{
    int kind; void* home; void* keeper;
    std::vector<void*> pieces; std::vector<std::string> keys; std::vector<void*> invs; std::vector<unsigned int> wearer;
    int wMine, wOther, wUnknown;   /* caravan: packs worn by a member this game runs / the other game runs / with no uid */
    int lead;                      /* caravan (fold 1 F2): the squad's formal leader - 1 this game runs it, 2 the other game, 0 no uid / not read */
    int uidSeen;                   /* caravan (fold 1 F1): the leader or a worn pack's wearer carries a uid, or the squad is wider than the view */
    ShopStock() : kind(coopshop::kStockHome), home(0), keeper(0), wMine(0), wOther(0), wUnknown(0), lead(0), uidSeen(0) {}
};
/* The packs the keeper's squad wears: the squad's member list (coop::ReadSquadAt on SquadActivePlatoonOf - the verified plain reads,
   T-1 B1) and each member's WORN packs (TlPacksOf: a top-level item with its own inventory, the project's pack-wearer rule; fold 1 F3:
   only one in section backpack_attach - TlPacksOf's `where` is "section:x,y" - the pack 0x952980 mirrors into the trade window
   (containers, Read), so the stock never takes from or files into a container in a member's general grid). No pointer from a pack
   back to its wearer is read (owed read R1, settled this way by the manager 2026-10-02). A squad wider than the view counts as an
   unknown wearer. fold 1: s->lead (F2, the formal leader's game) and s->uidSeen (F1). 1 = the squad read. MAIN THREAD. */
int ShopCaravanStock(void* keeper, ShopStock* s)
{
    s->kind = coopshop::kStockCaravan; s->keeper = keeper;
    void* const ap = ItObj(keeper) ? coop::SquadActivePlatoonOf((::Character*)keeper) : 0;
    coop::SquadView sv;
    if (ap == 0 || coop::ReadSquadAt(ap, &sv) != 1) return 0;
    if (sv.count > sv.stored) { ++s->wUnknown; s->uidSeen = 1; }
    const unsigned int lu = ItObj(sv.leader) ? FindSpawnedUid(sv.leader) : 0u;
    s->lead = (lu == 0) ? 0 : (net::IsUidMine(lu) ? 1 : 2);
    if (lu != 0) s->uidSeen = 1;
    const std::string wornAt("backpack_attach:");
    for (int k = 0; k < sv.stored; ++k)
    {
        ::Character* c = sv.members[k];
        if (!ItObj(c)) continue;
        std::vector<void*> packs; std::vector<std::string> where;
        TlPacksOf(ItInventoryOf(c), &packs, &where);
        std::vector<size_t> worn;
        for (size_t q = 0; q < packs.size() && q < where.size(); ++q)
            if (where[q].compare(0, wornAt.size(), wornAt) == 0) worn.push_back(q);
        const unsigned int u = worn.empty() ? 0u : FindSpawnedUid(c);
        if (u != 0) s->uidSeen = 1;
        for (size_t wq = 0; wq < worn.size(); ++wq)
        {
            const size_t q = worn[wq];
            void* pinv = 0;
            if (ItBagInvPod(packs[q], &pinv) == 0 || pinv == 0) continue;
            s->pieces.push_back(packs[q]); s->invs.push_back(pinv); s->wearer.push_back(u);
            s->keys.push_back(N((long long)u) + ":" + where[q]);
            if (u == 0) ++s->wUnknown; else if (net::IsUidMine(u)) ++s->wMine; else ++s->wOther;
        }
    }
    return 1;
}
/* coopshop::CaravanHolder over a whole caravan's packs (the holder's own check, its undo's and packfill's). A request only ever arrives
   in a session, so linked is 1 here (fold 1 F1's no-session rule is the gate's); the formal leader counts (F2). */
int ShopCaravanHolderOf(const ShopStock& s, unsigned int keeperUid)
{
    return coopshop::CaravanHolder(1, keeperUid != 0 ? 1 : 0, (keeperUid != 0 && net::IsUidMine(keeperUid)) ? 1 : 0, s.lead, (int)s.invs.size(),
                                   s.wMine, s.wOther, s.wUnknown, s.uidSeen);
}
/* The stock a request (or an applied record) names, resolved on this game. 1 = it resolved (home: the home's box; caravan: the keeper's
   squad and at least one pack). *held 1 = this game holds it (home: the area rule, as before; caravan: CaravanHolder 1 - the keeper's
   uid is this game's, every pack is worn by a member this game runs, and so is the formal leader - fold 1 F2). *keeperOk 1 = the keeper uid is that stock's trader here with
   a readable squad pot and not a player (ItKeeperPurseWhy) - a caravan's keeper must still have no home (one with a home is kVKeeper). */
int ShopStockResolve(int kind, const std::string& homeKey, unsigned int keeperUid, ShopStock* s, int* held, int* keeperOk)
{
    *held = 0; *keeperOk = 0;
    void* keeper = (keeperUid != 0) ? (void*)FindSpawned(keeperUid) : 0;
    if (keeper != 0 && !ItObj(keeper)) keeper = 0;
    s->keeper = keeper;
    if (kind == coopshop::kStockCaravan)
    {
        if (keeper == 0 || ShopCaravanStock(keeper, s) == 0 || s->invs.empty()) return 0;
        *held = (ShopCaravanHolderOf(*s, keeperUid) == 1) ? 1 : 0;
        *keeperOk = (ItHomeBuildingPod(keeper) == 0 && ItKeeperPurseWhy(keeper) == 0) ? 1 : 0;
        return 1;
    }
    s->kind = coopshop::kStockHome;
    s->home = ItBoxResolve(homeKey.c_str());
    if (s->home == 0) return 0;
    float hp[3] = { 0.0f, 0.0f, 0.0f };
    *held = (ItBoxPosPod(s->home, hp) != 0 && ItAreaVerdictAt(hp, 0) == kBoxMine) ? 1 : 0;
    *keeperOk = (keeper != 0 && ItHomeBuildingPod(keeper) == s->home && ItKeeperPurseWhy(keeper) == 0) ? 1 : 0;
    ItHomePieces(s->home, &s->pieces, &s->keys);
    for (size_t pi = 0; pi < s->pieces.size(); ++pi) s->invs.push_back((void*)ItBoxInventory(s->pieces[pi]));
    return 1;
}
/* The keeper's new cats go out at once: a home's through its piece (KeeperPublishCounter), a caravan's through the squad's own
   announcement (SquadCatsAnnounceNow - the counter publish needs a piece; a squad not yet announced with its money is left to the
   1-Hz pass). */
void ShopPotPublish(const ShopStock& s, size_t i)
{
    if (s.kind == coopshop::kStockCaravan) { if (s.keeper != 0) SquadCatsAnnounceNow(s.keeper); return; }
    if (i < s.pieces.size()) KeeperPublishCounter(s.pieces[i]);
}
std::string ShopStockWords(int kind, const std::string& homeKey, unsigned int keeperUid)
{
    return (kind == coopshop::kStockCaravan) ? "caravan=" + N((long long)keeperUid) : "home=" + homeKey;
}
/* The stacks of exactly `want` across the stock's inventories, in their order (0x951BA0's first-holder rule: a home's pieces in chain
   order, a caravan's packs in squad-member order - T-1 B5). MED 4: a stack of another
   maker / material / grade of the same record is not the item that was priced, and is not taken. fold 2 (LOW 9): with wantOwner (a
   sale's undo) the stolen / owner mark must match too - units of another mark are not the units that were sold (undoOwnerSkip). */
void ShopCollectStacks(const std::vector<void*>& stockInvs, const coopshop::Desc& want, std::vector<void*>* items, std::vector<void*>* invs,
                       std::vector<int>* qty, std::vector<int>* pieceOf, const coopmark::OwnerId* wantOwner = 0)
{
    for (size_t pi = 0; pi < stockInvs.size(); ++pi)
    {
        ::Inventory* inv = (::Inventory*)stockInvs[pi];
        if (!ItObj(inv)) continue;
        const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
        if (secs.size() > 64) continue;
        for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
        {
            ::InventorySection* sec = it->second;
            if (!ItObj(sec)) continue;
            const Ogre::vector< ::InventorySection::SectionItem>::type& si = sec->items;
            if (si.size() > 4096) continue;
            for (size_t k = 0; k < si.size(); ++k)
            {
                void* item = (void*)si[k].item;
                char cs[kSidCap]; cs[0] = 0; int iq = 0;
                if (!ItObj(item) || ItBaseSidPod(item, cs, kSidCap) == 0 || want.baseSid != cs || ItIntPod(item, kItemQuantity, &iq) == 0 || iq <= 0) continue;
                ItEntry fe; ItClear(&fe);
                if (ItReadFields(item, &fe) != 1 || coopshop::SameDesc(want, ShopDescOfEntry(fe)) == 0) continue;
                if (wantOwner != 0)
                {
                    coopmark::OwnerId o;
                    ItOwnerTranslate(fe.ownerRaw, fe.ownerHave, &o, 0);   /* book 0: a comparison, not a send */
                    if (!coopmark::OwnerEqual(o, *wantOwner)) { ++g_shopUndoOwnerSkip; continue; }
                }
                items->push_back(item); invs->push_back((void*)inv); qty->push_back(iq); pieceOf->push_back((int)pi);
            }
        }
    }
}
/* fold 2 (MED 1): THE ENGINE'S STACK LIMIT of `item` in section `sec`, read field by field (no engine call) - FUN_14075D550's rule,
   coopshop::StackMax: the record type (GameData +0x50), the record's intFields "stackable" (GameData +0x178), and the section's
   0x745B70 fields (+0x98 no-stack, +0x88 minimum, +0x8C float multiplier). -1 = a field did not read. */
int ShopDataInt(void* gd, const char* key)
{
    const ::GameData* g = (const ::GameData*)gd;
    GameHashMap<std::string, int>::type::const_iterator v = g->intFields.find(std::string(key));
    return (v == g->intFields.end()) ? 0 : v->second;
}
/* T-450 fold 1 (review 1): 1 = every field read and *mx is the engine's limit (it may be 0 or less: a truncated product); 0 = a
   field did not read (*mx = -1). Only this answer tells a FAILED read from a computed limit of -1. */
int ShopStackMaxRead(void* item, void* sec, int* mx)
{
    void* gd = 0; int type = 0, noStack = 0, secMin = 0; float mult = 0.0f;
    *mx = -1;
    if (ItPtrPod(item, kObjData, &gd) == 0 || !ItObj(gd) || ItIntPod(gd, 0x50, &type) == 0) return 0;
    if (ItIntPod(sec, 0x98, &noStack) == 0 || ItIntPod(sec, 0x88, &secMin) == 0 || ItFloatPod(sec, 0x8C, &mult) == 0) return 0;
    *mx = coopshop::StackMax(type, ShopDataInt(gd, "stackable"), noStack, secMin, mult);
    return 1;
}
int ShopStackMax(void* item, void* sec)
{
    int mx = -1;
    return (ShopStackMaxRead(item, sec, &mx) != 0) ? mx : -1;
}
/* T-450: how many placements of `item` the section gives one after another, none overlapping (coopshop::CountPlacements over
   ItCellAccepts - ItFirstFreeSlot's own test, in its order), stopping at `want` and at the section's item-count cap (T-450 fold 1,
   review 2: the engine's 0x719B80 before every placement scan, the first included (decomp_74bd70:114) - section +0xA8 above 0 and the item list's size at or above it = full;
   coopshop::CountPlacementsCapped). Nothing is placed and no engine add is called.
   -1 = the section's or the item's geometry, the cap or the item list did not read (or read implausibly), or the test faulted (the
   caller counts no room). */
static int ItCountPlacementsPod(::InventorySection* sec, void* item, int want)
{
    __try
    {
        int cw = 0, chh = 0, iw = 0, ih = 0, cap = 0;
        if (ItIntPod(sec, kSecContentW, &cw) == 0 || ItIntPod(sec, kSecContentH, &chh) == 0) return -1;
        if (cw <= 0 || chh <= 0 || (long long)cw * (long long)chh > 4096) return -1;
        if (ItIntPod(item, kItemWidth, &iw) == 0 || ItIntPod(item, kItemHeight, &ih) == 0) return -1;
        if (ItIntPod(sec, 0xA8, &cap) == 0 || cap > 0x100000) return -1;   /* 0 or less = no cap, as the engine reads it */
        const size_t have = sec->items.size();
        if (have > 4096) return -1;
        ItCellCtx ctx;
        ctx.sec = sec;
        ctx.item = (::Item*)item;
        return coopshop::CountPlacementsCapped(cw, chh, iw, ih, &ItCellRefusedAt, &ctx, want, cap, (int)have);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
/* HIGH 1 / T-450: THE BUYER'S ROOM FOR ALL n UNITS, asked of the shop's display copy WITHOUT adding it (coopshop::BuyFit). 1 = the
   sections read. Every section of the buyer's inventory - the sections Inventory::addItem (through ItAddAnywhereCount at the settle)
   offers the item to - adds to:
   *cellRoom: its free placements of the item (ItCountPlacementsPod - the engine's own cell test, placements that do not overlap) times
   the item's stack limit in that section (ShopStackMax): a stack above the limit takes SEVERAL cells (T812: 27 units passed on one
   free cell and the pack took 8);
   *stackRoom: fold 2 (MED 1, T-236 (1)) / T-450: what EVERY stack of exactly that item can still take under the engine's own limit
   (ShopStackMax of that stack in its section - 0x75D6E0's clamp), summed: a FULL matching stack is room 0, and a one-unit stack of a
   stackable record has room.
   An unreadable section, cell grid, item-count cap or limit counts as no room there (*unread = 1): the money is never taken for
   what may not fit. T-450 fold 1 (review 1): a limit that READ as 0 or 1 is ONE unit per cell (the engine's, decomp_74bd70:129-145)
   and is not unread - only a failed read is. */
int ShopBuyerRoom(::Inventory* inv, void* item, const coopshop::Desc& want, int n, int* cellRoom, int* stackRoom, int* unread)
{
    *cellRoom = 0; *stackRoom = 0; *unread = 0;
    if (!ItObj(inv) || !ItObj(item)) { *unread = 1; return 0; }
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) { *unread = 1; return 0; }
    const int need = (n > 0) ? n : 1;
    for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
    {
        ::InventorySection* sec = it->second;
        if (!ItObj(sec)) { *unread = 1; continue; }
        int cmx = -1;
        if (ShopStackMaxRead(item, (void*)sec, &cmx) == 0) *unread = 1;   /* T-450 fold 1: only a FAILED read is unread */
        else
        {
            const int per = coopshop::CellUnits(cmx);   /* T-450: the units one placed cell holds - one at a limit of 1 or less */
            const int cells = ItCountPlacementsPod(sec, item, (int)(((long long)need + per - 1) / per));   /* never more cells than n needs */
            if (cells < 0) *unread = 1;
            else *cellRoom = coopshop::RoomAdd(*cellRoom, coopshop::CellRoom(cells, per));
        }
        const Ogre::vector< ::InventorySection::SectionItem>::type& si = sec->items;
        if (si.size() > 4096) { *unread = 1; continue; }
        for (size_t k = 0; k < si.size(); ++k)
        {
            void* mine = (void*)si[k].item;
            char cs[kSidCap]; cs[0] = 0; int iq = 0;
            if (!ItObj(mine) || ItBaseSidPod(mine, cs, kSidCap) == 0 || want.baseSid != cs || ItIntPod(mine, kItemQuantity, &iq) == 0) continue;
            ItEntry fe; ItClear(&fe);
            if (ItReadFields(mine, &fe) != 1 || coopshop::SameDesc(want, ShopDescOfEntry(fe)) == 0) continue;
            int mx = -1;
            if (ShopStackMaxRead(mine, (void*)sec, &mx) == 0) { *unread = 1; continue; }   /* a FAILED read: no room on this stack */
            if (mx > 0)   /* T-450 fold 1: a limit read as 0 or less takes no merge (room 0) and is not unread */
                *stackRoom = coopshop::RoomAdd(*stackRoom, coopshop::StackRoom(mx, iq));   /* fold 2 (MED 1) / T-450: every matching stack's room, summed */
        }
    }
    return 1;
}
/* T-1 B5 TEST-ONLY (packbuytest `fit`, T817 T450b - no lever reached a whole stack that FITS the buyer): THE STACK BOUGHT is the
   first stacked (quantity 2+) non-money record in the trader's grid tSec whose WHOLE quantity n passes the shop's own room test for
   the buyer (ShopBuyerRoom + coopshop::BuyFit for all n units - the T-450 ask) AND that stacks in the buyer's section that would take
   it (its stack limit there above 1; that section = the buyer's general grid when the item has a free placement there, else the
   first other section with one, else the general grid). Preferred: n within that limit (one stack) and the buyer holding no item
   of that record yet (so a later `sell all sid=lastbuy` finds the bought stack, not an older item - T812's general:main singles);
   else the first that passes (oneStack= / held= say which). 1 = picked (*item, *x, *y, *qty; *line = the choice and why);
   0 = none (*line = the refusal with the closest candidates). Reads only. */
/* T-1 B5 TEST-ONLY T819 (nofit, T817 T450a took the first stacked record and it FIT): with nofit the stack bought is the FIRST stacked
   non-money record (sid= when given) whose WHOLE quantity n does NOT pass the buyer's room test (the room read, cells + stacks < n) -
   `nofit -> ...`; none = refused with the closest (the stacks that fit by the least margin). */
int ShopPbFitPick(::Inventory* buyerInv, ::InventorySection* tSec, const std::string& sidWant, ::Item** item, int* x, int* y, int* qty,
                  std::string* line, int nofit)
{
    *item = 0; *x = -1; *y = -1; *qty = 0; line->clear();
    if (!ItObj(buyerInv) || !ItObj(tSec))
    { *line = "fit: no stacked record fits the buyer's room (the buyer's inventory or the trader's grid did not read)"; return 0; }
    const ItSecMap& secs = *(const ItSecMap*)((char*)buyerInv + 0x28);
    if (secs.size() > 64) { *line = "fit: no stacked record fits the buyer's room (the buyer's sections did not read)"; return 0; }
    std::string gName;
    ::InventorySection* gSec = ItGeneralSection(buyerInv, &gName);
    const Ogre::vector< ::InventorySection::SectionItem>::type& ps = tSec->items;
    long long seen = 0, stacked = 0, bySid = 0, noRoom = 0, noStack = 0, unread = 0, fitOk = 0;   /* fitOk: nofit's stacks that fit */
    ::Item* fbItem = 0; int fbX = -1, fbY = -1, fbQ = 0; std::string fbWhy;
    std::vector<std::pair<long long, std::string> > close;
    for (size_t k = 0; k < ps.size() && k < 4096; ++k)
    {
        ::Item* c = ps[k].item;
        if (!ItObj(c)) continue;
        ++seen;
        int fn = 0, q = 0;
        if (ItIntPod(c, kItemFunction, &fn) == 0 || fn == kItemFunctionMoney || ItIntPod(c, kItemQuantity, &q) == 0 || q < 2) continue;
        ++stacked;
        char cs[kSidCap]; cs[0] = 0;
        ItBaseSidPod(c, cs, kSidCap);
        if (!sidWant.empty() && sidWant != cs) { ++bySid; continue; }
        ItEntry fe; ItClear(&fe);
        if (ItReadFields(c, &fe) != 1) { ++unread; continue; }
        int cells = 0, room = 0, un = 0;
        const int rd = ShopBuyerRoom(buyerInv, (void*)c, ShopDescOfEntry(fe), q, &cells, &room, &un);
        ::InventorySection* take = 0; std::string takeName;
        long long held = 0;   /* the buyer's items of this record, every section (top level) */
        if (gSec != 0 && ItCountPlacementsPod(gSec, (void*)c, 1) > 0) { take = gSec; takeName = gName; }
        for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
        {
            ::InventorySection* sec = it->second;
            char nm[kSecCap]; nm[0] = 0;
            if (!ItObj(sec) || ItStrPod(&it->first, nm, kSecCap) == 0) continue;
            if (take == 0 && sec != gSec && ItCountPlacementsPod(sec, (void*)c, 1) > 0) { take = sec; takeName = std::string(nm); }
            const Ogre::vector< ::InventorySection::SectionItem>::type& si = sec->items;
            for (size_t k2 = 0; k2 < si.size() && k2 < 4096; ++k2)
            {
                char hs[kSidCap]; hs[0] = 0;
                if (ItObj(si[k2].item) && ItBaseSidPod(si[k2].item, hs, kSidCap) != 0 && std::string(hs) == cs) ++held;
            }
        }
        if (take == 0 && gSec != 0) { take = gSec; takeName = gName + "(noFreeCell)"; }
        int lim = -1;
        const int limRead = (take != 0) ? ShopStackMaxRead((void*)c, (void*)take, &lim) : 0;
        const int fits = (coopshop::BuyFit(rd, cells, room, q) == coopshop::kFitSend) ? 1 : 0;
        const std::string desc = std::string("sid=") + cs + " qty=" + N((long long)q) + " cells=" + N((long long)cells) + " stacks=" + N((long long)room)
                               + " limit=" + (limRead != 0 ? N((long long)lim) : std::string("?")) + " in=" + (take != 0 ? takeName : std::string("none"))
                               + " held=" + N(held) + " at=" + N((long long)ps[k].x) + "," + N((long long)ps[k].y) + (un != 0 ? std::string(" unread=1") : std::string());
        if (nofit != 0)   /* T-1 B5 TEST-ONLY T819: the first whose whole quantity does NOT fit (room read, cells + stacks < n) */
        {
            const long long have = (long long)coopshop::RoomAdd(cells, room);
            if (fits == 0 && rd != 0 && un == 0)
            {
                *item = c; *x = (int)ps[k].x; *y = (int)ps[k].y; *qty = q;
                *line = "nofit -> " + desc + " need=" + N((long long)q) + " room=" + N(have) + " (the first stacked record whose whole quantity"
                        " does NOT pass the buyer's room test (T-450): cells + stacks < n)";
                return 1;
            }
            if (fits != 0) { ++fitOk; close.push_back(std::make_pair(have - (long long)q, desc + " (fits all " + N((long long)q) + ")")); }
            else { ++unread; close.push_back(std::make_pair(0LL, desc + " (room unread)")); }
            continue;
        }
        if (fits == 0)
        {
            ++noRoom;
            close.push_back(std::make_pair((long long)q - (long long)coopshop::RoomAdd(cells, room), desc + " (no room for all " + N((long long)q) + ")"));
            continue;
        }
        if (limRead == 0 || lim <= 1) { ++noStack; close.push_back(std::make_pair(0LL, desc + " (fits, does not stack there)")); continue; }
        if (q <= lim && held == 0)
        {
            *item = c; *x = (int)ps[k].x; *y = (int)ps[k].y; *qty = q;
            *line = "fit -> " + desc + " oneStack=1 (the first stacked record whose whole quantity passes the buyer's room test (T-450),"
                  " stacks there within its limit, and of which the buyer holds nothing yet)";
            return 1;
        }
        if (fbItem == 0) { fbItem = c; fbX = (int)ps[k].x; fbY = (int)ps[k].y; fbQ = q; fbWhy = desc + " oneStack=" + N((long long)(q <= lim ? 1 : 0)); }
    }
    if (fbItem != 0)
    {
        *item = fbItem; *x = fbX; *y = fbY; *qty = fbQ;
        *line = "fit -> " + fbWhy + " (the first stacked record whose whole quantity passes the buyer's room test (T-450) and stacks there;"
                " no such record is both within its limit and new to the buyer)";
        return 1;
    }
    std::sort(close.begin(), close.end());
    std::string nearList;   /* not `near`: windef.h defines near as an empty macro */
    for (size_t i = 0; i < close.size() && i < 4; ++i) nearList += std::string(i == 0 ? "" : "; ") + close[i].second;
    *line = (nofit != 0 ? "nofit: no stacked record overflows the buyer's room (fitOk=" + N(fitOk) + " items="
                        : std::string("fit: no stacked record fits the buyer's room and stacks there (items=")) + N(seen) + " stacked=" + N(stacked) + " bySid=" + N(bySid)
          + " noRoom=" + N(noRoom) + " noStack=" + N(noStack) + " unread=" + N(unread) + " sid=" + (sidWant.empty() ? std::string("any") : sidWant)
          + ") closest: " + (nearList.empty() ? std::string("none") : nearList);
    return 0;
}
/* MED 6 / 7: THE TRADE WINDOW'S STAND-IN IS REBUILT ONLY WITH AN EMPTY CURSOR - the parity swap's own rule (ItParityCursorBusy): an
   item on the cursor may be one of this window's, and a rebuild under it can destroy it. Busy = remembered, done from the tick once
   the cursor is empty and the same stand-in is still on screen. */
int ShopFacadeShown(void* facade)
{
    if (facade == 0 || facade != ItShopFacadeInventory()) return 0;
    void* gui = 0;
    return (ItInventoryGuiPod(facade, &gui) != 0 && gui != 0 && ItSameWindow(gui, facade) != 0) ? 1 : 0;
}
void ShopRebuildOrDefer(void* facade)
{
    if (facade == 0) return;
    if (ItParityCursorBusy() != 0) { ++g_shopRebuildDeferred; g_shopRebuildDefer = facade; return; }
    if (g_shopRebuildDefer == facade) g_shopRebuildDefer = 0;
    ItShopFacadeRebuild(facade);
}
/* MED 7: THE HOLDER'S OWN OPEN SHOP WINDOW after it took / filed units: the stand-in showing any inventory of the stock it wrote is
   rebuilt (T-1 B5: looked up by inventory, so a caravan's packs too - ItOpenShopFacadeFor walks the stand-in's map by inventory). */
void ShopHolderRefresh(const ShopStock& s, const std::vector<std::string>& touched)
{
    for (size_t pi = 0; pi < s.invs.size() && pi < s.keys.size(); ++pi)
    {
        if (std::find(touched.begin(), touched.end(), s.keys[pi]) == touched.end()) continue;
        void* facade = ItOpenShopFacadeFor((::Inventory*)s.invs[pi]);
        if (facade == 0) continue;
        ++g_shopHoldRefresh;
        ShopRebuildOrDefer(facade);
        return;   /* one stand-in: one rebuild re-mirrors every piece */
    }
}

/* T-1 B5 fold 2 (T811 L8 - a refused trade's undo put the unit into ANOTHER wearer's empty pack): the order a buy undo files the units
   back in - the piece they were taken from (srcKey, the s.keys form: a caravan's `uid:section:x,y`, a home's piece key) FIRST, then the
   rest in the stock's own order. *srcAt = its index (s.keys.size() when srcKey is empty or no longer one of the stock's pieces). */
std::vector<size_t> ShopUndoOrder(const ShopStock& s, const std::string& srcKey, size_t* srcAt)
{
    const size_t lim = (s.invs.size() < s.keys.size()) ? s.invs.size() : s.keys.size();
    size_t at = s.keys.size();
    for (size_t i = 0; i < lim && !srcKey.empty(); ++i) if (s.keys[i] == srcKey) { at = i; break; }
    std::vector<size_t> o;
    if (at < lim) o.push_back(at);
    for (size_t i = 0; i < lim; ++i) if (i != at) o.push_back(i);
    if (srcAt != 0) *srcAt = at;
    return o;
}
/* T-1 B5 fold 2: where a buy undo's units went, for its log - `source` (only the piece they were taken from took them; counted
   shopUndo2 undoBackSource) or `other:<key>[+<key>...]` (every piece that took units, in order; counted undoBackOther). Called once
   per filing; `none` (not counted) when no piece took any. */
std::string ShopUndoBackWords(const std::vector<std::string>& took, const std::string& srcKey)
{
    if (took.empty()) return "none";
    if (!srcKey.empty() && took.size() == 1 && took[0] == srcKey) { ++g_shopUndoBackSource; return "source"; }
    ++g_shopUndoBackOther;
    std::string w = "other:";
    for (size_t i = 0; i < took.size(); ++i) w += (i == 0 ? std::string() : std::string("+")) + took[i];
    return w;
}
/* fold 2 (LOW 8): file `item` in the stock (0x951B10's rule, as a sale files) - only while this game holds that stock (T-1 B5: a home
   by the area rule, a caravan's packs by CaravanHolder - ShopStockResolve). T-1 B5 fold 2: the piece the bought units were taken from
   (srcKey) is offered first, then the rest in the stock's order (ShopUndoOrder); *backOut = ShopUndoBackWords' answer (counted) once
   filed. 1 filed (*keyOut = the piece / pack that took the last units), 0 not now (kept), -1 the add faulted. */
int ShopFileInStock(int kind, const std::string& homeKey, unsigned int keeperUid, void* item, std::string* keyOut,
                    const std::string& srcKey = std::string(), std::string* backOut = 0)
{
    ShopStock s;
    int held = 0, keeperOk = 0;
    if (ShopStockResolve(kind, homeKey, keeperUid, &s, &held, &keeperOk) == 0 || held == 0) return 0;
    std::vector<std::string> t;   /* T-447 leftover 1: every piece that took units - one may absorb part of the stack and refuse the rest */
    const std::vector<size_t> order = ShopUndoOrder(s, srcKey, 0);   /* T-1 B5 fold 2: the source piece first */
    for (size_t oi = 0; oi < order.size(); ++oi)
    {
        const size_t pi = order[oi];
        ::Inventory* inv = (::Inventory*)s.invs[pi];
        if (inv == 0) continue;
        int took = 0;
        const int a = ItAddAnywhereCount(inv, item, &took);
        if (a == -2) break;   /* T-447 review 6: the quantity could not be read - nothing tried; kept, asked again next second */
        if (a == 1 || took > 0) t.push_back(s.keys[pi]);
        if (a == 1)
        {
            if (keyOut != 0) *keyOut = s.keys[pi];
            if (backOut != 0) *backOut = ShopUndoBackWords(t, srcKey);
            ShopHolderRefresh(s, t);
            return 1;
        }
        if (a < 0) { if (!t.empty()) ShopHolderRefresh(s, t); return -1; }
    }
    if (!t.empty()) ShopHolderRefresh(s, t);   /* the units a piece absorbed are shown; the object keeps only the rest */
    return 0;
}
std::string ShopPendWords(const ShopPend& p)
{
    return std::string(p.dir == 0 ? "BUY" : "SELL") + " id=" + N((long long)p.id) + " item=" + std::string(p.sid) + " n=" + N((long long)p.n)
           + " unit=" + N((long long)p.unitPrice) + " price=" + N((long long)p.price) + " " + ShopStockWords(p.stock, std::string(p.homeKey), p.keeperUid);
}
/* The window re-mirrors its pieces (only when the open trade window is still this shop's), and every piece the holder wrote is
   asked again (ItParityAskOne), so the non-holder's stock is the holder's answer. */
void ShopRefreshWindow(const ShopPend& p, const std::vector<std::string>* pieces)
{
    void* side = 0;
    if (ItTradeWindowSide(&side) == 1 && side != 0 && (side == p.shopTrader || side == p.keeper))
    {
        void* nowInv = 0;
        if (ItPtrPod(p.shopTrader, kShopTraderInv, &nowInv) != 0 && nowInv == p.shopInv) ShopRebuildOrDefer(p.shopInv);   /* MED 6: not under a cursor item */
    }
    /* T-1 B5: a caravan's touched names are its packs, not box keys - nothing to ask; its window follows the holder's published pack
       moves as they land (ShopCaravanMoveApplied) */
    if (pieces != 0 && p.stock != coopshop::kStockCaravan) for (size_t i = 0; i < pieces->size(); ++i) ItParityAskOne((*pieces)[i]);
}
/* THE REQUESTER'S SETTLEMENT (coopshop::Settle). ok 1 = the holder applied it; cf the holder's answer (0 on a lapse / send failure). */
/* fold 2 (LOW 11): returns 1 when a give-back (the buy's refund / the sale's escrow back) FAILED - the lapse keeps that, and the
   escrow pointer is then left in the row (not cleared) so a late ok can still settle it. */
int ShopSettle(ShopPend* p, int ok, const ItemConfirmMsg* cf, const char* why, int lapsed = 0)   /* T-447 fold 2: lapsed 1 = the 10 s lapse, whose row is kept (g_shopLapsedRow) */
{
    const int act = coopshop::Settle(p->dir, ok, p->held);
    ::Character* mine = FindSpawned(p->mineUid);
    if (!ItObj(mine)) mine = 0;
    std::string did;
    int gbf = 0;   /* fold 2 (LOW 11): 1 = the give-back failed */
    if ((act & coopshop::kActCreate) != 0 && cf != 0)
    {
        /* the holder's own numbers settle it: a different price than reserved is squared with the purse (counted - never expected) */
        if (cf->shop.price != p->price && mine != 0) { ItPursePay(mine, cf->shop.price - p->price); ++g_shopCfMismatch; }
        ItemMoveMsg mm;
        mm.baseSid = cf->baseSid; mm.companySid = cf->companySid; mm.materialSid = cf->materialSid; mm.colorSid = cf->colorSid;
        mm.quality = cf->quality; mm.charges = cf->charges; mm.functionKind = cf->functionKind; mm.level = cf->level; mm.unique = cf->unique;
        mm.quantity = (cf->shop.n > 0) ? cf->shop.n : p->n; mm.owner = cf->owner;
        g_shopLastBuySid = mm.baseSid;   /* T-1 B5 fold 1 TEST-ONLY (packbuytest sid=lastbuy): the asker settled this buy */
        g_shopLastBuyDesc = mm; g_shopLastBuyHaveDesc = 1;   /* T-1 B5 fold 2 TEST-ONLY: its full description (packfill template=created) */
        ::Item* it = ItCreateItem(mine, mm, 1);   /* fold: created even with the character away - it is kept for the pack below */
        ::Inventory* inv = (mine != 0) ? ItInventoryOf(mine) : 0;
        int buyUnits = 0;   /* T-447 leftover 1: the units the pack took, also when it refused the rest (the kept object holds only the rest) */
        const int added = (it != 0 && inv != 0) ? ItAddAnywhereCount(inv, (void*)it, &buyUnits) : 0;
        if (added == 1) did += " created n=" + N((long long)mm.quantity);
        else if (it == 0)
        {
            ++g_shopCreateFailed;
            ErrorLog("[SHOP] confirm " + ShopPendWords(*p) + ": the bought item could NOT be built from the holder's description"
                     " - the holder removed it and was paid. Counted shopCf createFailed.");
        }
        else if (added == -1)   /* T-447 review 6 / T-450: -2 (the quantity unreadable, nothing tried) goes below like a refusal -
                                   to the buyer's feet first, KEPT only when the ground does not take it */
        {
            ++g_shopAddFault;   /* the add faulted part-way: the object's state is unknown - neither destroyed nor re-added */
            ErrorLog("[SHOP] confirm " + ShopPendWords(*p) + ": the pack's add FAULTED - the bought item is left as it is. Counted shopKept addFault.");
        }
        else
        {
            /* HIGH 1 fold / T-450: the pack did not take (the rest of) it. The room test counts room for ALL n units, so a remainder
               here means one of: the inventory changed between the test and the confirm; the test over-counted (a check the engine's
               add makes that the count does not model); a merge onto a matching stack took less than the count's stack room; or (-2)
               the quantity did not read. The remainder goes AT THE BUYER'S FEET through the engine's own drop (T-447's
               rule for a sale's escrow remainder: ItShowDropAtFeetPod, the ground road announces it); only when the ground does not take
               it either is it KEPT, never destroyed - it goes into the pack as soon as it fits, and the engine's own "No room"
               (result 2) says why it is not there yet */
            const std::string partWords = (buyUnits > 0 ? "the rest of the bought stack (it took " + N((long long)buyUnits) + " of " + N((long long)mm.quantity) + " units)"
                                                        : std::string("the bought item"));
            const std::string whatWords = (added == -2) ? ("the quantity of " + partWords + " could not be read (nothing was added)")
                                                        : ("the pack did not take " + partWords);   /* review 3 */
            const int fd = (inv != 0) ? ItShowDropAtFeetPod((void*)inv, (void*)it) : 0;   /* 1 dropped, 0 not (or no character here), -1 faulted */
            if (fd == 1)
            {
                ++g_shopBoughtFeet;
                did += " boughtFeet n=" + N((long long)(mm.quantity - buyUnits)) + (buyUnits > 0 ? " placed=" + N((long long)buyUnits) : std::string());
                DebugLog("[SHOP] confirm " + ShopPendWords(*p) + ": " + whatWords
                         + " - dropped at the buyer's feet. Counted shopFold2 boughtFeet.");
            }
            else if (fd < 0)
            {   /* the drop FAULTED - where the object is now is unknown, so it is never touched again (not kept, not retried, not destroyed) */
                ++g_shopBoughtFeetFault;
                did += " boughtFeetFault";
                ErrorLog("[SHOP] confirm " + ShopPendWords(*p) + ": " + whatWords + " and the engine's drop at the"
                         " buyer's feet FAULTED - it is left where that left it and never touched again. Counted shopFold2 boughtFeetFault.");
            }
            else
            {
                ShopKept k; k.mineUid = p->mineUid; k.item = (void*)it; k.lastTry = ::GetTickCount(); k.id = p->id;
                g_shopKept.push_back(k);
                ++g_shopKeptForPack;
                ShopShowResultPod(coopshop::kTrNoRoom);
                did += " keptForPack n=" + N((long long)(mm.quantity - buyUnits)) + (buyUnits > 0 ? " placed=" + N((long long)buyUnits) : std::string());
                DebugLog("[SHOP] confirm " + ShopPendWords(*p) + ": " + whatWords
                         + (inv != 0 ? std::string(" and the ground did not take it") : std::string(" and the buyer is not here to drop it"))
                         + " - it is KEPT (not destroyed) and"
                         " goes into the pack as soon as it fits (kept=" + N((long long)g_shopKept.size()) + ")");
            }
        }
    }
    if ((act & coopshop::kActRefund) != 0)
    {
        if (mine != 0 && ItPursePay(mine, -p->price) == 1) { ++g_shopRefunded; did += " refunded=" + N((long long)p->price); }
        else { ++g_shopRefundFailed; gbf = 1; ErrorLog("[SHOP] " + ShopPendWords(*p) + ": the reservation could NOT be given back (" + std::string(why) + ")"); }
    }
    if ((act & coopshop::kActCredit) != 0 && cf != 0)
    {
        if (mine != 0 && ItPursePay(mine, -cf->shop.price) == 1) did += " credited=" + N((long long)cf->shop.price);
        else ErrorLog("[SHOP] " + ShopPendWords(*p) + ": the sale's price could NOT be credited");
        /* T-447 review 4: a full sale must carry the asked price, a PARTIAL one the unit price times its units, and never more units
           than asked - a mismatch is counted and settled on the holder's numbers, never refused (coopshop::SellerConfirmOk says why) */
        if (coopshop::SellerConfirmOk(p->n, p->unitPrice, p->price, cf->shop.n, cf->shop.price) == 0) ++g_shopCfMismatch;
    }
    int soldBack = 0;   /* T-447 leftover 1: a PARTIAL sale - the holder's pieces had room for cf->shop.n units only */
    if ((act & coopshop::kActDestroyEscrow) != 0 && p->escrow != 0)
    {
        int eq = 0;
        const int readOk = (cf != 0 && ItIntPod(p->escrow, kItemQuantity, &eq) != 0) ? 1 : 0;
        const int rest = (readOk != 0) ? coopshop::SellerRest(eq, cf->shop.n) : 0;
        const int wrote = (rest > 0) ? ItWriteIntPod(p->escrow, kItemQuantity, rest) : 0;
        if (rest > 0 && wrote != 0)
        {   /* the escrow keeps only the units the shop did not take (the engine sets +0x12C the same way when it splits a stack) */
            soldBack = 1;
            ++g_shopSoldPartial;
            did += " partialSold=" + N((long long)cf->shop.n) + " back=" + N((long long)rest);
        }
        else
        {
            if (cf != 0 && (readOk == 0 || rest > 0))
            {   /* T-447 fold 2 (3): the quantity could not be read (or the rest not written) - the escrow is destroyed whole, as before partial
                   sales; when the holder sold only part, the unsold units in it are LOST. Said and counted. */
                ++g_shopEscrowQtyFault;
                ErrorLog("[SHOP] " + ShopPendWords(*p) + ": the escrow's quantity could not be " + std::string(readOk == 0 ? "read" : "written")
                         + " - it is destroyed whole as the sold item's escrow (sold=" + N((long long)cf->shop.n) + "); any unsold units in it are"
                         " LOST. Counted shopPartial qtyFault.");
            }
            ItDestroyPod(p->escrow, "coop T-164 B4-4: a sold item's escrow, filed by the stock holder"); p->escrow = 0; did += " escrowDestroyed";
        }
    }
    if (((act & coopshop::kActReturnEscrow) != 0 || soldBack != 0) && p->escrow != 0)
    {
        ::Inventory* inv = (mine != 0) ? ItInventoryOf(mine) : 0;
        int backU = 0;   /* T-447 review 1/2: the units the pack took - it may take part of the stack and refuse the rest */
        const int ab = (inv != 0) ? ItAddAnywhereCount(inv, p->escrow, &backU) : 0;
        int fd = 0;      /* the engine's drop at the seller's feet (CapPutBack's order): 1 dropped, 0 not (or no character here), -1 faulted */
        if (ab != 1 && ab != -1 && inv != 0) fd = ItShowDropAtFeetPod((void*)inv, p->escrow);
        if (ab == 1) { ++g_shopEscrowBack; did += " escrowBack"; p->escrow = 0; }
        else if (fd == 1)
        {   /* no room in the pack for (the rest of) it: dropped at the seller's feet - the give-back is complete, so a late ok becomes a revoke */
            ++g_shopEscrowFeet;
            did += " escrowFeet" + (backU > 0 ? " packed=" + N((long long)backU) : std::string());
            p->escrow = 0;
        }
        else if (fd < 0)
        {   /* T-447 fold 2 (2): the drop FAULTED - where the object is now is unknown, so it is never touched again (not kept, not retried,
               not destroyed, not named in the row); gbf stays 0, so a late ok becomes a revoke */
            ++g_shopEscrowLost; ++g_shopEscrowDropFault;
            ErrorLog("[SHOP] " + ShopPendWords(*p) + ": the engine's drop of the escrowed item at the seller's feet FAULTED (" + std::string(why)
                     + ") - it is left where that left it and never touched again. Counted shopCf escrowLost, shopPartial dropFault.");
            p->escrow = 0;
        }
        else if (ab != -1 && (backU > 0 || lapsed == 0))
        {   /* T-447 fold 2 (1): neither the pack nor the ground took (the rest of) it - it goes on the bought items' retry (g_shopKept: into
               this character's pack once a second, kept until it fits), never left in no inventory. Every path but the lapse's with nothing
               back lands here (an in-time partial sale or refusal, a late settle, a send failure, a lapse with part back); gbf stays 0, so
               a late ok becomes a revoke - never a settle that pays for units already back in the pack. */
            ShopKept k; k.mineUid = p->mineUid; k.item = p->escrow; k.lastTry = ::GetTickCount(); k.id = p->id;
            g_shopKept.push_back(k);
            ++g_shopEscrowKept;
            if (backU > 0) ++g_shopEscrowShort;
            did += " escrowKept" + (backU > 0 ? " packed=" + N((long long)backU) : std::string());
            DebugLog("[SHOP] " + ShopPendWords(*p) + ": " + (backU > 0 ? "the pack took " + N((long long)backU) + " of the escrowed units and"
                     " neither the pack nor the ground took the rest" : std::string("neither the pack nor the ground took the escrowed item"))
                     + " (" + std::string(why) + ") - it is KEPT and goes into the pack as soon as it fits (kept=" + N((long long)g_shopKept.size())
                     + "). Counted shopPartial escrowKept" + (backU > 0 ? std::string(", escrowShort.") : std::string(".")));
            p->escrow = 0;
        }
        else
        {   /* the LAPSE with nothing back (fold 2 LOW 11): the escrow stays named in the KEPT LAPSED ROW (g_shopLapsedRow) and a late ok
               settles the sale with it. A faulted add (ab -1) on any path lands here too and is never retried; off the lapse path the row
               is freed below and nothing names the object again. */
            ++g_shopEscrowLost;
            gbf = 1;
            ErrorLog("[SHOP] " + ShopPendWords(*p) + ": the escrowed item could NOT be put back in the pack (" + std::string(why)
                     + ") - it is kept alive in no inventory" + (ab == -1 ? std::string(" (the add FAULTED: never retried)") : std::string())
                     + ". Counted shopCf escrowLost.");
        }
    }
    ShopRefreshWindow(*p, (cf != 0) ? &cf->shop.pieces : 0);
    DebugLog("[SHOP] " + std::string(ok != 0 ? "confirm ok " : "confirm refused ") + ShopPendWords(*p)
             + (cf != 0 ? " verdict=" + N((long long)cf->shop.verdict) + " show=" + N((long long)cf->shop.show) + " pieces=" + N((long long)cf->shop.pieces.size()) : std::string())
             + " settled:" + (did.empty() ? std::string(" nothing") : did) + " (" + std::string(why) + ")");
    p->used = 0;
    return gbf;
}
/* MAIN THREAD, from ItPendExpire every tick: the frame count (the dedupe) and the 10 s lapse = a refusal. */
void ShopPendExpire()
{
    ++g_shopFrame;
    PtWindowTick();   /* T-619: a copy trader's price town */
    PtHostSendTick();   /* T-619: the price source's town tables to every other game */
    const unsigned int now = ::GetTickCount();
    /* MED 6 / 7 fold: a rebuild that waited for the cursor - done once it is empty and the same stand-in is still on screen */
    if (g_shopRebuildDefer != 0 && ItParityCursorBusy() == 0)
    {
        void* f = g_shopRebuildDefer;
        g_shopRebuildDefer = 0;
        if (ShopFacadeShown(f) != 0) { ++g_shopRebuildLate; ItShopFacadeRebuild(f); } else ++g_shopRebuildDropped;
    }
    /* HIGH 1 fold: the kept buys into the pack, once a second each */
    for (size_t i = 0; i < g_shopKept.size() && StoreTearingDown() == 0; )
    {
        ShopKept& k = g_shopKept[i];
        if ((unsigned int)(now - k.lastTry) < 1000u) { ++i; continue; }
        k.lastTry = now;
        ::Character* c = FindSpawned(k.mineUid);
        ::Inventory* inv = (c != 0 && ItObj(c)) ? ItInventoryOf(c) : 0;
        const int added = (inv != 0) ? ItAddAnywherePod(0, inv, k.item) : 0;
        if (added == 1)
        {
            ++g_shopKeptIntoPack;
            DebugLog("[SHOP] kept buy of request " + N((long long)k.id) + ": the pack took it now");
            g_shopKept.erase(g_shopKept.begin() + (std::ptrdiff_t)i);
            continue;
        }
        if (added < 0)
        {
            ++g_shopAddFault;
            ErrorLog("[SHOP] kept buy of request " + N((long long)k.id) + ": the pack's add FAULTED - no longer retried. Counted shopKept addFault.");
            g_shopKept.erase(g_shopKept.begin() + (std::ptrdiff_t)i);
            continue;
        }
        ++i;
    }
    /* fold 2 (MED 2): the holder's applied records have NO time expiry - each stays until the requester's ack (ShopRevokeApplied).
       fold 2 (LOW 8): a buy undo's kept units are filed into the shop, once a second each */
    for (size_t i = 0; i < g_shopUndoKept.size() && StoreTearingDown() == 0; )
    {
        ShopUndoKept& k = g_shopUndoKept[i];
        if ((unsigned int)(now - k.lastTry) < 1000u) { ++i; continue; }
        k.lastTry = now;
        std::string key, back;
        const int f = ShopFileInStock(k.stock, k.homeKey, k.keeperUid, k.item, &key, k.srcKey, &back);   /* T-1 B5 fold 2: the source piece first */
        if (f == 1)
        {
            ++g_shopUndoKeptFiled;
            DebugLog("[SHOP] holder undo of request " + N((long long)k.id) + ": the kept units were filed in " + key
                     + " src=" + (k.srcKey.empty() ? std::string("none") : k.srcKey) + " back=" + back);
            g_shopUndoKept.erase(g_shopUndoKept.begin() + (std::ptrdiff_t)i);
            continue;
        }
        if (f < 0)
        {
            ++g_shopAddFault;
            ErrorLog("[SHOP] holder undo of request " + N((long long)k.id) + ": the piece's add FAULTED - no longer retried. Counted shopKept addFault.");
            g_shopUndoKept.erase(g_shopUndoKept.begin() + (std::ptrdiff_t)i);
            continue;
        }
        ++i;
    }
    for (int i = 0; i < kShopPendCap; ++i)
    {
        ShopPend* p = &g_shopPend[i];
        if (p->used == 0 || (unsigned int)(now - p->sentAt) < kPendTimeoutMs) continue;
        ++g_shopCfLapsed;
        const int slot = g_shopLapsedAt & 15;
        g_shopLapsedIds[slot] = p->id; ++g_shopLapsedAt;
        DebugLog("[SHOP] lapsed " + ShopPendWords(*p) + " - no answer in 10 s: settled as a refusal");
        /* fold 2 (LOW 11): the row is kept as settled, with whether its give-back failed - a late ok then SETTLES it, not a revoke */
        g_shopLapsedGiveBackFailed[slot] = ShopSettle(p, 0, 0, "lapsed", 1);
        g_shopLapsedRow[slot] = *p;
    }
}
/* fold 2 (MED 2): THE SHOP ACK - the requester settled the holder's ok (in time, or a late ok after a failed give-back), so the holder
   may drop its applied record. MSG_ITEM_REVOKE with the shop tail kind 1. An unsent ack leaves the record held (counted ackUnsent). */
void ShopSendAck(unsigned int id)
{
    if (net::SendShopTail(id, ShopEpoch(), coopshop::kTailAck)) ++g_shopAckSent;
    else
    {
        ++g_shopAckUnsent;
        ErrorLog("[SHOP] the ack of shop request " + N((long long)id) + " could NOT be sent - the holder keeps its record. Counted shopRec ackUnsent.");
    }
}
/* MAIN THREAD, from ApplyItemConfirm first: 1 = the answer was to a shop request of ours (settled or late), 0 = not ours. */
int ShopPendConfirm(const ItemConfirmMsg& cf)
{
    ShopPend* p = 0;
    for (int i = 0; i < kShopPendCap && p == 0; ++i) if (g_shopPend[i].used != 0 && g_shopPend[i].id == cf.id) p = &g_shopPend[i];
    if (p == 0)
    {
        for (int i = 0; i < 16; ++i)
            if (g_shopLapsedIds[i] == cf.id && cf.id != 0)
            {
                ++g_shopCfLate;
                g_shopLapsedIds[i] = 0;   /* answered once: a repeat of the answer sends nothing more */
                const int late = coopshop::LateAnswer(1, cf.ok, cf.shop.has, cf.shop.verdict, g_shopLapsedGiveBackFailed[i]);
                g_shopLapsedGiveBackFailed[i] = 0;
                if (late == coopshop::kLateSettle)
                {
                    /* fold 2 (LOW 11): the lapse's give-back FAILED (the reservation / the escrow is still out), so the late ok SETTLES
                       the trade - the item is created (buy) / the price credited and the escrow dropped (sale) - and is acked */
                    ++g_shopLateSettled;
                    ShopPend row = g_shopLapsedRow[i];
                    row.used = 1;
                    ShopSettle(&row, 1, &cf, "a late ok after the lapse's give-back failed: settled as the trade");
                    ShopSendAck(cf.id);
                }
                else if (late == coopshop::kLateRevoke)
                {
                    /* HIGH 2 fold: this game already gave the reservation / escrow back, the holder applied both of its halves - the
                       holder is asked to undo them (ShopRevokeApplied), so the trade happened on neither game. fold 2: the revoke
                       carries the shop tail (kind 0, this process's epoch) - the holder's record key */
                    if (net::SendShopTail(cf.id, ShopEpoch(), coopshop::kTailRevoke))
                    {
                        ++g_shopLateRevokeSent;
                        DebugLog("[SHOP] a LATE ok answer to lapsed shop request " + N((long long)cf.id) + " (the holder applied it after this game"
                                 " had settled it as a refusal) - a revoke was sent: the holder undoes its own halves");
                    }
                    else
                    {
                        ++g_shopLateRevokeUnsent;
                        ErrorLog("[SHOP] a LATE ok answer to lapsed shop request " + N((long long)cf.id) + ": the revoke could NOT be sent - the two"
                                 " games are one trade apart. Counted shopLate revokeUnsent.");
                    }
                }
                return 1;
            }
        return 0;
    }
    const int ok = (cf.ok != 0 && cf.shop.has != 0 && cf.shop.verdict == coopshop::kVOk) ? 1 : 0;
    if (ok != 0) ++g_shopCfOk; else ++g_shopCfRefused;
    ShopSettle(p, ok, &cf, ok != 0 ? "the holder applied it" : "the holder refused it");
    if (ok != 0) ShopSendAck(cf.id);   /* fold 2 (MED 2): the holder keeps its applied record until this ack */
    if (ok == 0 && cf.shop.show != 0) ShopShowResultPod(cf.shop.show);   /* the engine's own text only */
    return 1;
}

/* THE HELD-HERE PROOF (B4-1 kept): the shadow price this road would have carried, against the charge the engine really made. */
void ShopShadowNote(int shadow, int measured, int charge, int result)
{
    if (measured == 0) { ++g_shopShadowUnmeasured; return; }
    if (charge == shadow) { ++g_shopShadowMatch; return; }
    ++g_shopShadowMismatch;
    if (g_shopShadowMismatch <= 50)
        DebugLog("[SHOP] shadow MISMATCH: this game holds the shop, the engine charged " + N((long long)charge) + " and the intercept's price"
                 " would have been " + N((long long)shadow) + " (result " + N((long long)result) + ") - the shadow-price leg (LEFTOVER: slot 0x288 x n vs 0x290, buy-back flip)");
}

/* THE GATE (design 'Gate'): the stand-in's ShopTrader -> keeper -> home -> key -> holder by the B4-3 home rule; T-1 B5: a keeper with
   no home whose stand-in is backed by packs is a CARAVAN, held by the game that runs its squad (ShopCaravanGate). MAIN THREAD. */
const int kShopCarCap = 16;   /* T-1 B5: the packs behind one stand-in that are read (more = unknown wearers: refused) */
struct ShopGateRes { void* keeper; void* home; int keyOk; int holder; int gate; char hk[kBoxKeyCap]; int caravan, carPacks, carMine, carOther, carUnknown, carLead, carLinked, carNoUid; };
/* T-1 B5 (design Q1, manager decision 2): THE CARAVAN BRANCH. Each pack behind the window (ItFacadePackInvs - the stand-in's own map,
   POD) is matched BY INVENTORY against the packs the keeper's squad members wear (ShopCaravanStock - the member list; no pointer from a
   pack back to its wearer), and its wearer's uid says which game runs it; a pack whose wearer is not found counts as unknown. holder =
   coopshop::CaravanHolder (fold 1: the formal leader counts as a member - F2; no session, or nothing adopted, is held here - the engine's
   own trade, as before B5 - F1): mixed or unknown is refused at the gate (nothing moves). MAIN THREAD. */
void ShopCaravanGate(void* st, ShopGateRes* g)
{
    void* fv = 0;
    if (st == 0 || ItPtrPod(st, kShopTraderInv, &fv) == 0 || !ItObj(fv)) return;
    void* back[kShopCarCap];
    const int nb = ItFacadePackInvs(fv, back, kShopCarCap);
    if (nb <= 0) return;
    g->caravan = 1; g->carPacks = nb;
    if (nb > kShopCarCap) g->carUnknown += nb - kShopCarCap;
    ShopStock s;
    const int sq = ShopCaravanStock(g->keeper, &s);
    for (int i = 0; i < nb && i < kShopCarCap; ++i)
    {
        const std::vector<void*>::iterator w = std::find(s.invs.begin(), s.invs.end(), back[i]);
        const unsigned int u = (w != s.invs.end()) ? s.wearer[(size_t)(w - s.invs.begin())] : 0u;
        if (u == 0) ++g->carUnknown; else if (net::IsUidMine(u)) ++g->carMine; else ++g->carOther;
    }
    const unsigned int ku = FindSpawnedUid(g->keeper);
    g->carLead = s.lead;
    g->carLinked = coop::PlayersPresent() ? 1 : 0;   /* another player here: the old link, or the roster's IN_WORLD */
    const int wearerUid = (sq == 0 || s.uidSeen != 0) ? 1 : 0;   /* a squad that did not read cannot be shown to carry no uid */
    g->carNoUid = (ku == 0 && s.lead == 0 && wearerUid == 0 && g->carMine == 0 && g->carOther == 0) ? 1 : 0;
    g->holder = coopshop::CaravanHolder(g->carLinked, ku != 0 ? 1 : 0, (ku != 0 && net::IsUidMine(ku)) ? 1 : 0, s.lead, nb, g->carMine,
                                        g->carOther, g->carUnknown, wearerUid);
}
std::string ShopCaravanGateWords(const ShopGateRes& g)
{
    return "caravan packs=" + N((long long)g.carPacks) + " wearers mine/other/unknown=" + N((long long)g.carMine) + "/" + N((long long)g.carOther)
           + "/" + N((long long)g.carUnknown) + " leader=" + (g.carLead == 1 ? "me" : (g.carLead == 2 ? "peer" : "none"))
           + (g.carLinked == 0 ? " noSession" : "") + (g.carNoUid != 0 ? " nothingAdopted" : "");
}
void ShopGateOf(void* st, ShopGateRes* g)
{
    g->keeper = (st != 0) ? ItShopFacadeTrader(st) : 0;
    g->home = (g->keeper != 0) ? ItHomeBuildingPod(g->keeper) : 0;
    g->hk[0] = 0;
    float hp[3] = { 0.0f, 0.0f, 0.0f };
    g->keyOk = (g->home != 0 && ItBoxKeyBuild(g->home, g->hk, kBoxKeyCap, 0, 3) != 0 && g->hk[0] != 0 && ItBoxPosPod(g->home, hp) != 0) ? 1 : 0;
    g->holder = 0;
    if (g->keyOk != 0) { const int v = ItAreaVerdictAt(hp, 0); g->holder = (v == kBoxMine) ? 1 : ((v == kBoxHeld) ? 2 : 0); }
    g->caravan = 0; g->carPacks = 0; g->carMine = 0; g->carOther = 0; g->carUnknown = 0; g->carLead = 0; g->carLinked = 0; g->carNoUid = 0;
    if (g->keeper != 0 && g->home == 0) ShopCaravanGate(st, g);   /* T-1 B5 */
    g->gate = coopshop::Gate((st != 0) ? 1 : 0, (g->home != 0) ? 1 : 0, g->keyOk, g->holder, g->caravan);
}
/* THE REQUESTER'S SEND, shared by the right-click (I1) and the drag (I3): from the pending row to MSG_ITEM_REQUEST. BUY (owner 184 a):
   the room test, the price reserved, the units out of the stand-in only; SALE (owner 185): the units into escrow. `item` is the
   object in `srcInv` (the stand-in on a buy, the pack on a sale) holding `q` units, `n` of which move. Returns the TradeResult to
   answer; *mark = 1 sent, 2 the engine's "You can't afford that." was shown, 0 neither (refused here, nothing moved). */
struct ShopSendArgs
{
    int dir, sound, q, n, entry, unit, price;
    void* soundGui; void* srcInv; void* item; void* mine; void* st; void* shopInv; void* keeper;
    unsigned int mineUid, keeperUid;
    const char* hk; const char* sid;
    int caravan;   /* T-1 B5: the stock is a caravan's packs (hk is empty; the request is addressed by the keeper's uid) */
};
int ShopSendTrade(const ShopSendArgs& a, int* mark)
{
    *mark = 0;
    ShopPend* p = 0;
    for (int i = 0; i < kShopPendCap && p == 0; ++i) if (g_shopPend[i].used == 0) p = &g_shopPend[i];
    if (p == 0) { ++g_shopIcTableFull; return coopshop::kTrQuiet; }
    ItemRequestMsg rq;
    std::memset(p, 0, sizeof(ShopPend));
    p->dir = a.dir; p->n = a.n; p->unitPrice = a.unit; p->price = a.price; p->mineUid = a.mineUid;
    p->shopTrader = a.st; p->shopInv = a.shopInv; p->keeper = a.keeper;
    p->keeperUid = a.keeperUid; p->stock = (a.caravan != 0) ? coopshop::kStockCaravan : coopshop::kStockHome;   /* T-1 B5 */
    std::memcpy(p->sid, a.sid, kSidCap); std::memcpy(p->homeKey, a.hk, kBoxKeyCap);
    if (a.dir == 0)
    {
        /* MED 4 fold: the clicked variant's full description rides the buy (the same fields the sale sends); the holder takes only
           stacks that match it exactly */
        ItEntry be; ItClear(&be);
        if (ItReadFields(a.item, &be) != 1) { ++g_shopIcUnreadable; return coopshop::kTrQuiet; }
        /* HIGH 1 fold / T-450: THE ROOM TEST FOR ALL n UNITS, before anything moves - 0x713150 answers result 2 when no add into the
           buyer's inventory took it; asked here of the display copy without adding it (coopshop::BuyFit: the free placements x the
           stack limit, plus every matching stack's room, must take ALL n). The right-click (I1) and the drag (I3) both ask it here. */
        int fitCells = 0, fitRoom = 0, fitUnread = 0;
        const int fitRead = ShopBuyerRoom(ItInventoryOf((::Character*)a.mine), a.item, ShopDescOfEntry(be), a.n, &fitCells, &fitRoom, &fitUnread);
        if (fitUnread != 0) ++g_shopFitUnread;
        if (coopshop::BuyFit(fitRead, fitCells, fitRoom, a.n) == coopshop::kFitNoRoom)
        {
            ++g_shopFitNoRoom;
            if (fitRoom > 0) ++g_shopFitStackShort;   /* fold 2: matching stacks had room, but not (with the cells) for all n */
            if (fitCells > 0) ++g_shopFitCellShort;   /* T-450: free cells had room, but not (with the stacks) for all n - T812's case */
            DebugLog("[SHOP] intercept BUY refused here: no room in the buyer's inventory for " + std::string(a.sid) + " n=" + N((long long)a.n)
                     + " (room cells=" + N((long long)fitCells) + " stacks=" + N((long long)fitRoom)
                     + (fitRead == 0 ? std::string(" inventory unreadable") : (fitUnread != 0 ? std::string(" partly unreadable") : std::string()))
                     + ") (result 2) - nothing moved, nothing sent");
            return coopshop::kTrNoRoom;
        }
        /* BUY (owner 184 a): the money leaves at the click - a reservation the holder's refusal or the timeout gives back */
        const int res = coopshop::Reserve(ItPursePay(a.mine, a.price));
        if (res == coopshop::kResShort)
        {
            ++g_shopIcShort;
            ShopShowResultPod(coopshop::kTrCantAfford);
            *mark = 2;
            return coopshop::kTrQuiet;
        }
        if (res != coopshop::kResOk) { ++g_shopIcUnreadable; return coopshop::kTrQuiet; }
        p->held = 1;
        if (a.sound != 0) ShopSoundPod(a.soundGui, "Sell_Item", a.item);   /* the original's money-trade sound */
        ShopStandInTakePod(a.srcInv, a.item, (a.n >= a.q) ? -1 : a.n);   /* the window only; `item` is not used after this */
        rq.dir = 0; rq.trade = 1; rq.baseSid = a.sid;
        rq.companySid = be.companySid; rq.materialSid = be.materialSid; rq.colorSid = be.colorSid;   /* MED 4 fold (protocol 93) */
        rq.quality = be.quality; rq.charges = be.charges; rq.functionKind = be.functionKind; rq.level = be.level; rq.unique = be.unique;
    }
    else
    {
        /* SALE (owner 185): the units leave the pack at the click, into escrow - the item's full description rides the request */
        ItEntry fe; ItClear(&fe);
        std::vector<coopbag::BagRow> rows; int bagWhy = 0;
        const int bag = ItBagRowsOf(a.item, &rows, &bagWhy);
        if (ItReadFields(a.item, &fe) != 1) { ++g_shopIcUnreadable; return coopshop::kTrQuiet; }
        if (bag < 0 || (bag == 1 && !rows.empty()))
        {
            ++g_shopIcBagRefused;
            DebugLog("[SHOP] intercept REFUSED here: a sale of a pack with something in it (LEFTOVER: the shop road carries no pack rows) - nothing moved");
            return coopshop::kTrQuiet;
        }
        rq.dir = 1; rq.trade = 2;
        rq.baseSid = fe.baseSid; rq.companySid = fe.companySid; rq.materialSid = fe.materialSid; rq.colorSid = fe.colorSid;
        rq.quality = fe.quality; rq.charges = fe.charges; rq.functionKind = fe.functionKind; rq.level = fe.level; rq.unique = fe.unique;
        ItOwnerTranslate(fe.ownerRaw, fe.ownerHave, &rq.owner);   /* the stolen mark travels with it (inv6) */
        if (a.sound != 0) ShopSoundPod(a.soundGui, "Sell_Item", a.item);
        void* esc = ShopRemovePod(a.srcInv, a.item, (a.n >= a.q) ? -1 : a.n);   /* NOT behind the guard: the pack's removal is published */
        if (esc == 0) { ++g_shopIcUnreadable; return coopshop::kTrQuiet; }
        p->escrow = esc; p->held = 1;
    }
    p->id = g_reqNextId++;
    if (g_reqNextId == 0) g_reqNextId = 1;
    p->sentAt = ::GetTickCount();
    p->used = 1;
    /* T-1 B5: a caravan's request goes to the game that runs its keeper (the character road, M7b slice 2 - SendItemRequest's owner
       uid), not to a home key's holder; its shop block names the stock kind and no home */
    rq.id = p->id; rq.ownerUid = (a.caravan != 0) ? a.keeperUid : 0; rq.ownerBoxKey = (a.caravan != 0) ? "" : a.hk;
    rq.quantity = a.n; rq.takerUid = a.mineUid; rq.price = a.price;
    rq.shop.has = 1; rq.shop.keeperUid = a.keeperUid; rq.shop.homeKey = (a.caravan != 0) ? "" : a.hk; rq.shop.sid = a.sid; rq.shop.n = a.n;
    rq.shop.unitPrice = a.unit; rq.shop.entry = a.entry; rq.shop.stock = p->stock;
    PtRequesterLegs(a.item, &rq.shop.cult, &rq.shop.local);   /* T-619: the two legs this price used, for the holder's check */
    rq.shop.epoch = ShopEpoch();   /* fold 2 (item 12): the holder keys its record on {peer, epoch, id} - ids restart with this process */
    if (a.dir == 0) ++g_shopIcBuy; else ++g_shopIcSell;
    if (a.caravan != 0) ++g_shopCarSent;   /* T-1 B5 */
    DebugLog("[SHOP] intercept " + ShopPendWords(*p) + " keeper=" + N((long long)a.keeperUid) + " entry=" + N((long long)rq.shop.entry)
             + " - the engine's trade did not run; " + std::string(a.dir == 0 ? "the price is reserved and the units left the window only"
             : "the units are in escrow") + "; asked of the stock holder");
    const int sent = net::SendItemRequest(rq) ? 1 : 0;
    if (sent == 0) { ++g_shopIcSendFailed; ShopSettle(p, 0, 0, "the request could not be sent"); }
    else *mark = 1;
    return coopshop::kTrQuiet;
}

/* I1 - THE RIGHT-CLICK INTERCEPT. MAIN THREAD (rclickTradeThr, Confirmed). 1 = handled here (*ret written, the original must not
   run); 0 = run the original (*shadowOut = the price this road would carry, signed like the charge, when the shop is held here). */
int ShopInterceptRClick(void* gui, int* ret, const void* sectionStr, int x, int y, void* sendingTo, char first, int* shadowOut)
{
    *shadowOut = kShopNoShadow;
    if (ret == 0 || ItOnMainThread() == 0 || g_chargeDepth != 0) return 0;
    void* srcInv = 0; void* dstInv = 0;
    if (ItGuiInventoryCall(gui, &srcInv) == 0 || ItGuiInventoryCall(sendingTo, &dstInv) == 0) return 0;
    int dir = 0;
    void* st = ShopTraderOfInv(srcInv);
    void* shopInv = srcInv;
    if (st == 0) { st = ShopTraderOfInv(dstInv); shopInv = dstInv; dir = 1; }
    /* fold 2 (LOW 10): the engine's second-window retry (0x713E50) of a click this game already SENT - or answered with the
       cannot-afford notice - is refused here WHATEVER the second window is: a non-shop second window would otherwise take the
       return below, run the original and move the rest of the stack (a sale's retry into a second pack / box) */
    if (g_shopLastClick.frame == g_shopFrame && g_shopLastClick.window == (unsigned long long)(uintptr_t)gui)
    {
        void* it0 = 0; char sn0[kSecCap];
        ShopItemAt(srcInv, sectionStr, x, y, &it0, sn0);
        const coopshop::ClickKey k0 = { (unsigned long long)(uintptr_t)gui, coopshop::SecHash(sn0), x, y, g_shopFrame };
        if (coopshop::SameClick(k0, g_shopLastClick) != 0)
        {
            ++g_shopIcDedupe;
            if (st == 0) ++g_shopRetryAnyWindow;
            *ret = coopshop::kTrQuiet;
            return 1;
        }
    }
    if (st == 0) return 0;
    ShopGateRes sg;
    ShopGateOf(st, &sg);
    void* const keeper = sg.keeper;
    const char* const hk = sg.hk;
    const int holder = sg.holder;
    int gate = sg.gate;
    if (gate == coopshop::kGateOriginal) return 0;   /* no stock behind the window (no home, no packs): the engine's own road */
    void* item = 0;
    char secName[kSecCap];
    const int haveItem = ShopItemAt(srcInv, sectionStr, x, y, &item, secName);
    int q = 0, fn = 0;
    const int qtyRead = (haveItem != 0 && ItIntPod(item, kItemQuantity, &q) != 0 && q > 0) ? 1 : 0;
    const int allFlag = ShopAllFlagPod();
    const int n = coopshop::Units(q, allFlag);
    int unit = -1;
    const int priced = (qtyRead != 0 && n > 0 && ShopUnitPricePod(item, (dir == 1) ? 1 : 0, q, &unit) != 0 && unit >= 0) ? 1 : 0;
    const int price = (priced != 0) ? coopshop::TotalPrice(unit, n) : -1;
    if (gate == coopshop::kGateHeldHere)
    {
        ++g_shopIcHeldHere;
        if (sg.caravan != 0) ++g_shopCarHeldHere;   /* T-1 B5: this game runs the caravan - the engine's own trade, published by the drain */
        if (price >= 0) *shadowOut = (dir == 0) ? price : -price;
        return 0;
    }
    /* from here nothing of the original runs: the answer is ours */
    coopshop::ClickKey ck = { (unsigned long long)(uintptr_t)gui, coopshop::SecHash(secName), x, y, g_shopFrame };
    if (coopshop::SameClick(ck, g_shopLastClick) != 0) { ++g_shopIcDedupe; *ret = coopshop::kTrQuiet; return 1; }
    /* MED 8 fold: the key is remembered only once a request is SENT (below, coopshop::KeyAfter) - a refusal here marks nothing, so the
       engine's second-window retry of a click this window refused is a real trade call */
    if (gate == coopshop::kGateIntercept && ItRefuseHere(tradecharge::kGateNoHolder, 1) != 0) gate = coopshop::kGateRefuse;   /* TEST-ONLY lever */
    if (gate == coopshop::kGateRefuse)
    {
        ++g_shopIcRefusedGate;
        if (sg.caravan != 0) ++g_shopCarRefusedGate;   /* T-1 B5: a pack worn by a member the keeper's game does not run, or no uid */
        DebugLog("[SHOP] intercept REFUSED here: the shop's holder is not known (" + (sg.caravan != 0 ? ShopCaravanGateWords(sg)
                 : "home=" + std::string(hk[0] != 0 ? hk : "(no key)")) + " holder=" + N((long long)holder) + ") - nothing ran, nothing moved, nothing sent");
        *ret = coopshop::kTrQuiet;
        return 1;
    }
    if (haveItem == 0) { ++g_shopIcUnreadable; *ret = coopshop::kTrQuiet; return 1; }
    const int locked = (ShopItemLockedPod(item) == 1) ? 1 : 0;
    const int range = ShopRangePod(gui, sendingTo);
    const int pre = coopshop::PreCheck(locked, (range == 1) ? 1 : 0, (ItIntPod(item, kItemFunction, &fn) != 0 && fn == kItemFuncMoney) ? 1 : 0, qtyRead);
    if (pre != 0)
    {
        ++g_shopIcPre;
        if (pre == coopshop::kTrOutOfRange && first != 0) ShopSoundPod(gui, "gui_notrade", item);   /* the original's own sound */
        *ret = pre;
        return 1;
    }
    unsigned int mineUid = 0;
    void* mine = ItChargeMineOfGui((dir == 0) ? sendingTo : gui, &mineUid);
    const unsigned int keeperUid = (keeper != 0) ? FindSpawnedUid(keeper) : 0;
    char sid[kSidCap]; sid[0] = 0;
    ItBaseSidPod(item, sid, kSidCap);
    if (mine == 0 || keeperUid == 0 || sid[0] == 0 || price < 0)
    {
        ++g_shopIcUnreadable;
        DebugLog("[SHOP] intercept REFUSED here: " + std::string(mine == 0 ? "no character of ours on the other side" : (keeperUid == 0 ? "the keeper carries no uid"
                 : (sid[0] == 0 ? "the item's record did not read" : "the price did not read"))) + " - nothing moved, nothing sent");
        *ret = coopshop::kTrQuiet;
        return 1;
    }
    ShopSendArgs sa;
    sa.dir = dir; sa.sound = (first != 0) ? 1 : 0; sa.q = q; sa.n = n;
    sa.entry = (allFlag != 0 && n > 1) ? coopshop::kEntryAll : coopshop::kEntryOne;
    sa.unit = unit; sa.price = price;
    sa.soundGui = gui; sa.srcInv = srcInv; sa.item = item; sa.mine = mine; sa.st = st; sa.shopInv = shopInv; sa.keeper = keeper;
    sa.mineUid = mineUid; sa.keeperUid = keeperUid; sa.hk = hk; sa.sid = sid; sa.caravan = sg.caravan;   /* T-1 B5 */
    int mark = 0;
    *ret = ShopSendTrade(sa, &mark);
    /* MED 8 fold: the key is remembered only once a request is SENT; fold 2 (LOW 10): or the cannot-afford notice was shown, so the
       engine's second-window retry of it is the quiet dedupe - shown once */
    if (mark != 0) g_shopLastClick = coopshop::KeyAfter(g_shopLastClick, ck, 1);
    /* no message; ends RClickAutoTradeAll's shift loop. It does NOT end 0x713E50's second-window retry (decomp_713e50 :176-190): that
       retry reaches the hook as the same click - into a shop window it is the dedupe above, into ANY other window it is the early
       check before the non-shop return (fold 2, LOW 10). */
    return 1;
}

/* ================= T-164 part 2 (design I2-I4): THE DRAG =================
   Pick-up 0x712DD0 takes the item out of the source window at once; drop 0x714990 settles the trade. From a shop the other game holds
   the pick-up runs under ShopTraderInventory::Updating (I2) so the cursor carries a COPY and no piece is touched; the drop (I3) routes
   it (coopshop::DropRoute): on a window of ours it is a BUY - the copy goes back under the guard and the request is sent as the
   right-click's (ShopSendTrade, entry kEntryDrag); back on its own shop the original runs under the guard; anywhere else it goes back
   under the guard. An item of ours dropped on a shop the other game holds is a SALE: it goes back to the pack and the sale is sent.
   Every other return of a copy (escape, a window closed while carrying, a release over the world) ends in the put-back 0x70CC90,
   which the fold hooks (H2): into a shop not held here it runs under the guard. */
long long g_shopDragPickGuarded = 0, g_shopDragPickRefused = 0, g_shopDragBuy = 0, g_shopDragSell = 0, g_shopDragSameShop = 0;
long long g_shopDragReturned = 0, g_shopDragReturnPlain = 0, g_shopDragRefusedGate = 0, g_shopDragUnread = 0, g_shopDragNotSent = 0;
long long g_shopDragOffThread = 0, g_shopGuardNested = 0, g_shopGuardLost = 0, g_shopGuardNoRow = 0;
long long g_shopDragAdopted = 0, g_shopPutBackGuarded = 0, g_shopPutBackOffThread = 0, g_shopDragAffordUnread = 0;   /* T-164 part 2 fold */
long long g_shopGiveRefused = 0, g_shopGiveOffThread = 0;   /* T-164 part 2 fold 2 (HIGH) */
int g_shopGuardDepth = 0;
const size_t kMouseInvSrcWin = 0x68;   /* MouseInventory: the window the cursor item came from (decomp_70d000 / decomp_714990 :69) */
const size_t kVtItemAfford = 0x298;    /* Item slot: how many of this stack `money` buys (decomp_714990 :458) */
typedef int (*ShopItemAffordFn)(void* item, int money, char flag);
/* The shop copy on the cursor: picked from `shopInv` (ShopTrader `st`) under the guard. Compared, never dereferenced. */
struct ShopDragCopy { void* item; void* st; void* shopInv; };
ShopDragCopy g_shopDrag = { 0, 0, 0 };

/* THE GUARD (design I2 and 'Risks'): Updating set to 1 for ONE engine call and restored to what it was, and the applying-thread mark
   set so the item hooks ring nothing for the stand-in's display change (as ShopStandInTakePod). Nesting (a guarded drop that returns
   through the guarded 0x70D000) is counted `nested`; a flag found cleared on the way out (0x951A00 ran inside and reset it, so the
   callbacks after it were NOT guarded) is counted `lost`. 1 entered, 0 no Updating row. */
struct ShopGuardSave { unsigned char upd; LONG apply; };
int ShopGuardEnter(ShopGuardSave* sv)
{
    sv->upd = 0; sv->apply = 0;
    if (g_base == 0 || kShopFacadeUpdatingRva == 0) { ++g_shopGuardNoRow; return 0; }
    volatile unsigned char* upd = (volatile unsigned char*)(g_base + kShopFacadeUpdatingRva);
    __try { sv->upd = *upd; *upd = 1; }
    __except (EXCEPTION_EXECUTE_HANDLER) { ++g_shopGuardNoRow; return 0; }
    sv->apply = ::InterlockedExchange(&g_itApplyingThread, (LONG)::GetCurrentThreadId());
    if (g_shopGuardDepth > 0) ++g_shopGuardNested;
    ++g_shopGuardDepth;
    return 1;
}
void ShopGuardLeave(const ShopGuardSave* sv)
{
    if (g_shopGuardDepth > 0) --g_shopGuardDepth;
    volatile unsigned char* upd = (volatile unsigned char*)(g_base + kShopFacadeUpdatingRva);
    __try { if (*upd != 1) ++g_shopGuardLost; *upd = sv->upd; }
    __except (EXCEPTION_EXECUTE_HANDLER) {}
    ::InterlockedExchange(&g_itApplyingThread, sv->apply);
}
char ShopGuardedPickup(void* gui, void* sectionStr)
{
    ShopGuardSave sv;
    const int in = ShopGuardEnter(&sv);
    char r = 0;
    __try { r = orig_guiPickup(gui, sectionStr); }
    __finally { if (in != 0) ShopGuardLeave(&sv); }
    return r;
}
MouseReturnFn ShopReturnFn()
{
    return (g_base != 0 && kMouseReturnItemRva != 0) ? (MouseReturnFn)(g_base + kMouseReturnItemRva) : 0;
}
/* The cursor item back to its window: guarded (a shop copy) or plain (an item of ours). 1 called, 0 no function. */
int ShopReturnPod(void* mouse, int guarded)
{
    MouseReturnFn fn = ShopReturnFn();
    if (fn == 0 || mouse == 0) return 0;
    ShopGuardSave sv;
    const int in = (guarded != 0) ? ShopGuardEnter(&sv) : 0;
    __try { fn(mouse); }
    __finally { if (in != 0) ShopGuardLeave(&sv); }
    return 1;
}
void* ShopMousePod()
{
    if (g_base == 0 || kMouseInvPtrRva == 0) return 0;
    __try { void* m = *(void* const*)(g_base + kMouseInvPtrRva); return ItPlaus(m) ? m : 0; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
/* Item slot 0x298: how many units of `item` `money` affords. side: the SOURCE window record's +10 flag, which 0x714990 passes
   (decomp_714990 :447-449; ShopWinRecFlagPod). 1 = asked. */
int ShopAffordPod(void* item, int money, int side, int* out)
{
    *out = -1;
    if (!ItPlaus(item)) return 0;
    __try
    {
        const char* vt = *(const char* const*)item;
        ShopItemAffordFn fn = *(ShopItemAffordFn*)(vt + kVtItemAfford);
        if (!ItPlaus((const void*)fn)) return 0;
        *out = fn(item, money, (char)side);
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { *out = -1; return 0; }
}
/* T-164 part 2 fold (L2): the window record the engine keeps per InventoryGUI - a std::map at DAT_142131b90 whose operator[] is
   0x6F4D90, which INSERTS a missing key; so it is walked here read-only, as that function's own lower-bound loop (decomp_6f4d90): the
   head at map +8, a node's left / parent / right at +0 / +8 / +0x10, its key at +0x18, the record at +0x20, the nil flag at +0x51.
   *out = the record's byte at `off`; 1 = found. MAIN THREAD (the GUI's map). */
const size_t kWinRecSide = 10;   /* the side flag: 0x714990 passes the source's to slot 0x298 (:449) and its answer + 3 (:472) */
int ShopWinRecFlagPod(void* gui, size_t off, int* out)
{
    *out = -1;
    if (g_base == 0 || kInvGuiRecordMapRva == 0 || gui == 0) return 0;
    __try
    {
        const char* const head = *(const char* const*)((const char*)(g_base + kInvGuiRecordMapRva) + 8);
        if (!ItPlaus(head)) return 0;
        const unsigned long long key = (unsigned long long)(uintptr_t)gui;
        const char* best = head;
        const char* node = *(const char* const*)(head + 8);
        int steps = 0;
        while (ItPlaus(node) && *(node + 0x51) == 0)
        {
            if (++steps > 64) return 0;
            if (*(const unsigned long long*)(node + 0x18) < key) node = *(const char* const*)(node + 0x10);
            else { best = node; node = *(const char* const*)node; }
        }
        if (best == head || key < *(const unsigned long long*)(best + 0x18)) return 0;
        *out = (int)*(const unsigned char*)(best + 0x20 + off);
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { *out = -1; return 0; }
}
/* T-164 part 2 fold (M2): a window's money as 0x714990 reads the DESTINATION's (:447-448, :468): the window's +0x50 object, slot 0x1B8.
   On a sale the drop window is the shop's - the shop's money. 1 = read. */
typedef int (*ShopIntGetFn)(void* self);
const size_t kGuiMoneyOwner = 0x50;
const size_t kVtMoney = 0x1B8;
int ShopGuiMoneyPod(void* gui, int* out)
{
    *out = -1;
    if (!ItPlaus(gui)) return 0;
    __try
    {
        void* const o = *(void* const*)((const char*)gui + kGuiMoneyOwner);
        if (!ItPlaus(o)) return 0;
        const char* vt = *(const char* const*)o;
        ShopIntGetFn f = *(ShopIntGetFn*)(vt + kVtMoney);
        if (!ItPlaus((const void*)f)) return 0;
        *out = f(o);
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { *out = -1; return 0; }
}
/* A by-value std::string argument the callee owns (MSVC x64: the caller passes its copy's address; the callee destroys it) - left as
   the original's own exits leave it (decomp_714990 :672-679, decomp_712dd0 :37-42: the buffer freed, the string empty). Same CRT. */
void ShopFreeByValueStr(void* str)
{
    if (str == 0) return;
    std::string empty;
    ((std::string*)str)->swap(empty);
}
/* The section of `inv` the engine's section string names (getSection 0x747070, read through the section map). */
void* ShopSectionNamed(void* inv, const void* sectionStr, char* secName)
{
    secName[0] = 0;
    if (!ItObj(inv) || sectionStr == 0 || ItStrPod(sectionStr, secName, kSecCap) == 0 || secName[0] == 0) return 0;
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) return 0;
    for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
    {
        char nm[kSecCap]; nm[0] = 0;
        if (ItStrPod(&it->first, nm, kSecCap) == 0 || std::strcmp(nm, secName) != 0) continue;
        return ItObj(it->second) ? (void*)it->second : 0;
    }
    return 0;
}
/* After a put-back the object may have merged into a stack: the stack of exactly `want` (and, on a sale, the same owner mark) with at
   least n units - `prefer` (the object that went back) when it is still there. */
void* ShopFindStack(void* inv, const coopshop::Desc& want, int n, void* prefer, const coopmark::OwnerId* wantOwner, int* qOut)
{
    *qOut = 0;
    if (!ItObj(inv)) return 0;
    void* best = 0; int bestQ = 0;
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) return 0;
    for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
    {
        ::InventorySection* sec = it->second;
        if (!ItObj(sec)) continue;
        const Ogre::vector< ::InventorySection::SectionItem>::type& si = sec->items;
        if (si.size() > 4096) continue;
        for (size_t k = 0; k < si.size(); ++k)
        {
            void* item = (void*)si[k].item;
            char cs[kSidCap]; cs[0] = 0; int iq = 0;
            if (!ItObj(item) || ItBaseSidPod(item, cs, kSidCap) == 0 || want.baseSid != cs || ItIntPod(item, kItemQuantity, &iq) == 0 || iq < n) continue;
            ItEntry fe; ItClear(&fe);
            if (ItReadFields(item, &fe) != 1 || coopshop::SameDesc(want, ShopDescOfEntry(fe)) == 0) continue;
            if (wantOwner != 0)
            {
                coopmark::OwnerId o;
                ItOwnerTranslate(fe.ownerRaw, fe.ownerHave, &o, 0);   /* book 0: a comparison, not a send */
                if (!coopmark::OwnerEqual(o, *wantOwner)) continue;
            }
            if (item == prefer) { *qOut = iq; return item; }
            if (best == 0) { best = item; bestQ = iq; }
        }
    }
    *qOut = bestQ;
    return best;
}
/* T-164 part 2 fold (H1): what the tracked copy becomes after an engine call that may have changed the cursor (coopshop::CursorAfter):
   kept while it is still on the cursor; a DIFFERENT item whose source window (MouseInventory +0x68) still shows the copy's stand-in
   left it under the guard (0x714990's swap 0x712990 + 0x748EE0, or its clamp leftover) and is ADOPTED - a shop-sourced cursor item is
   never forgotten; anything else, an empty cursor included, is forgotten (the pointer may be reused by the allocator). */
void ShopDragClear() { g_shopDrag.item = 0; g_shopDrag.st = 0; g_shopDrag.shopInv = 0; }
void ShopDragTrackCursor()
{
    if (g_shopDrag.item == 0 && g_shopDrag.shopInv == 0) return;
    void* const cur = ItHeldLive();
    int fromShop = 0;
    if (cur != 0 && cur != g_shopDrag.item && g_shopDrag.shopInv != 0)
    {
        void* const mouse = ShopMousePod();
        void* srcGui = 0; void* srcInv = 0;
        if (mouse != 0 && ItPtrPod(mouse, kMouseInvSrcWin, &srcGui) != 0 && srcGui != 0 && ItGuiInventoryCall(srcGui, &srcInv) != 0
            && srcInv == g_shopDrag.shopInv && ShopTraderOfInv(srcInv) == g_shopDrag.st) fromShop = 1;
    }
    const int d = coopshop::CursorAfter((cur != 0) ? 1 : 0, (cur != 0 && cur == g_shopDrag.item) ? 1 : 0, fromShop);
    if (d == coopshop::kCurAdopt)
    {
        ++g_shopDragAdopted;
        DebugLog("[SHOP] drag: the engine put another item of the same shop window on the cursor (a swap / a leftover) - it is tracked as the shop copy");
        g_shopDrag.item = cur;
    }
    else if (d == coopshop::kCurForget) ShopDragClear();
}

/* I2. 0 = the original as is; 1 = under the guard (the other game holds the shop, or its holder is not known); 2 = refused here,
   nothing ran (no Updating row or no 0x70CC90 put-back hook: an unguarded copy could later be filed into a piece) - the string is freed.
   Off the main thread: the original as is, counted (the drain's shopNotIntercepted refusal is that road's net, as for I1). */
int ShopPickupGate(void* gui, void* sectionStr)
{
    void* inv = 0;
    if (ItGuiInventoryCall(gui, &inv) == 0) return 0;
    void* st = ShopTraderOfInv(inv);
    if (st == 0) return 0;
    if (ItOnMainThread() == 0) { ++g_shopDragOffThread; return 0; }
    ShopGateRes sg;
    ShopGateOf(st, &sg);
    if (coopshop::PickupGuarded(sg.gate) == 0) return 0;
    if (kShopFacadeUpdatingRva == 0 || orig_putBack == 0 || orig_mouseGive == 0)
    {
        ++g_shopDragPickRefused;
        DebugLog("[SHOP] drag pick-up REFUSED here: a shop the other game holds (or with no known holder), and the " + std::string(kShopFacadeUpdatingRva == 0
                 ? "ShopFacadeUpdating row" : (orig_putBack == 0 ? "0x70CC90 put-back hook" : "0x7118C0 give-to-object hook")) + " is missing - nothing ran");
        ShopFreeByValueStr(sectionStr);
        return 2;
    }
    g_shopDrag.item = 0; g_shopDrag.st = st; g_shopDrag.shopInv = inv;
    return 1;
}
void ShopPickupDone(int guarded)
{
    if (guarded != 1) { g_shopDrag.item = 0; g_shopDrag.st = 0; g_shopDrag.shopInv = 0; return; }
    void* const live = ItHeldLive();
    g_shopDrag.item = live;
    if (live != 0) ++g_shopDragPickGuarded;
    else { g_shopDrag.st = 0; g_shopDrag.shopInv = 0; }
}
char ShopGuardedPlace(void* gui, void* sectionStr, void* point)
{
    ShopGuardSave sv;
    const int in = ShopGuardEnter(&sv);
    char r = 0;
    __try { r = orig_guiPlace(gui, sectionStr, point); }
    __finally { if (in != 0) ShopGuardLeave(&sv); }
    ShopDragTrackCursor();
    return r;
}
/* H2 (fold): the put-back 0x70CC90's decision (coopshop::PutBackGuard). The gate is asked on the MAIN THREAD only (the GUI's own);
   off it only the tracked copy is guarded (counted). *tracked = the item is the tracked copy. */
int ShopPutBackDecide(void* gui, void* item, int* tracked)
{
    *tracked = (item != 0 && g_shopDrag.item != 0 && item == g_shopDrag.item) ? 1 : 0;
    const int inGuard = (g_shopGuardDepth > 0) ? 1 : 0;
    if (inGuard != 0 || item == 0) return coopshop::PutBackGuard(inGuard, *tracked, 0, coopshop::kGateOriginal);
    void* inv = 0;
    void* const st = (ItGuiInventoryCall(gui, &inv) != 0 && inv != 0) ? ShopTraderOfInv(inv) : 0;
    /* fold 2 (LOW): the tracked copy is guarded only into a stand-in; into a window with no shop the guard has nothing to keep out */
    if (st == 0 || *tracked != 0) return coopshop::PutBackGuard(0, *tracked, (st != 0) ? 1 : 0, coopshop::kGateOriginal);
    if (ItOnMainThread() == 0) { ++g_shopPutBackOffThread; return coopshop::kPbAsIs; }
    ShopGateRes g; g.gate = coopshop::kGateOriginal; g.keeper = 0; g.hk[0] = 0;
    ShopGateOf(st, &g);
    return coopshop::PutBackGuard(0, 0, 1, g.gate);
}
void ShopPutBackGuardedCall(void* gui, void* item, const void* sectionRef)
{
    ShopGuardSave sv;
    const int in = ShopGuardEnter(&sv);
    __try { orig_putBack(gui, item, sectionRef); }
    __finally { if (in != 0) ShopGuardLeave(&sv); }
}
/* The detour's body. A put-back of the tracked copy ends it: the item is in a window again, not on the cursor (L1: part 2's return
   hook forgot it there; 0x70D000 clears the cursor right after this call). */
void ShopPutBack(void* gui, void* item, const void* sectionRef)
{
    if (orig_putBack == 0) return;
    int tracked = 0;
    const int d = ShopPutBackDecide(gui, item, &tracked);
    if (d == coopshop::kPbGuard) { ++g_shopPutBackGuarded; ShopPutBackGuardedCall(gui, item, sectionRef); }
    else orig_putBack(gui, item, sectionRef);
    if (tracked != 0) ShopDragClear();
}
/* HIGH (fold 2): 0x7118C0's decision (coopshop::GiveRefused). 1 = refused: the item is the tracked copy, or the source window shows a
   stand-in of a shop not held here. The gate is asked on the MAIN THREAD only (the GUI's own); off it a stand-in source is refused
   (its holder is not known there), counted. Refusing only puts the item back where it came from (0x712AD0 runs 0x70D000). */
int ShopGiveRefuse(void* srcGui, void* item)
{
    if (item == 0) return 0;
    const int tracked = (g_shopDrag.item != 0 && item == g_shopDrag.item) ? 1 : 0;
    void* inv = 0;
    void* const st = (srcGui != 0 && ItGuiInventoryCall(srcGui, &inv) != 0 && inv != 0) ? ShopTraderOfInv(inv) : 0;
    int gate = coopshop::kGateOriginal;
    if (tracked == 0 && st != 0)
    {
        if (ItOnMainThread() == 0) { ++g_shopGiveOffThread; gate = coopshop::kGateRefuse; }
        else { ShopGateRes g; g.gate = coopshop::kGateOriginal; g.keeper = 0; g.hk[0] = 0; ShopGateOf(st, &g); gate = g.gate; }
    }
    if (coopshop::GiveRefused(tracked, (st != 0) ? 1 : 0, gate) == coopshop::kGiveAsIs) return 0;
    ++g_shopGiveRefused;
    DebugLog(std::string("[SHOP] release over a character or container REFUSED: ") + (tracked != 0 ? "the shop copy" : "an item out of a shop not held here")
             + " - put back under the guard, not given (T-164 part 2 fold 2)");
    return 1;
}
/* I3. 0 = run the original as is; 2 = run it under the guard; 1 = answered here (*rOut = 0, the original did not run, its by-value
   section string is freed). */
int ShopInterceptPlace(void* gui, void* sectionStr, char* rOut)
{
    *rOut = 0;
    void* const held = ItHeldLive();
    if (held == 0) { ShopDragClear(); return 0; }   /* L1 (fold): an empty cursor carries no copy */
    const int copy = (g_shopDrag.item != 0 && held == g_shopDrag.item) ? 1 : 0;
    void* dstInv = 0;
    if (ItGuiInventoryCall(gui, &dstInv) == 0) dstInv = 0;
    void* const dstSt = (dstInv != 0) ? ShopTraderOfInv(dstInv) : 0;
    if (copy == 0 && dstSt == 0) return 0;   /* the common drop: no shop in it */
    void* const mouse = ShopMousePod();
    void* srcGui = 0;
    if (mouse == 0 || ItPtrPod(mouse, kMouseInvSrcWin, &srcGui) == 0) srcGui = 0;
    if (ItOnMainThread() == 0)
    {
        ++g_shopDragOffThread;
        if (copy == 0) return 0;
        ++g_shopDragReturned;   /* a copy is never settled off the main thread: back under the guard */
        ShopReturnPod(mouse, 1);
        ShopDragTrackCursor();
        ShopFreeByValueStr(sectionStr);
        return 1;
    }
    /* the copy's shop, re-checked through the LIVE source window (never the remembered pointers alone) */
    ShopGateRes cg; cg.gate = coopshop::kGateOriginal; cg.keeper = 0; cg.hk[0] = 0; cg.caravan = 0;
    if (copy != 0)
    {
        void* srcInv = 0;
        const int live = (srcGui != 0 && ItGuiInventoryCall(srcGui, &srcInv) != 0 && srcInv == g_shopDrag.shopInv
                          && ShopTraderOfInv(srcInv) == g_shopDrag.st) ? 1 : 0;
        if (live != 0) ShopGateOf(g_shopDrag.st, &cg); else cg.gate = coopshop::kGateRefuse;
    }
    ShopGateRes dg; dg.gate = coopshop::kGateOriginal; dg.keeper = 0; dg.hk[0] = 0; dg.caravan = 0;
    if (dstSt != 0) ShopGateOf(dstSt, &dg);
    unsigned int dstUid = 0, srcUid = 0;
    void* const dstMine = ItChargeMineOfGui(gui, &dstUid);
    void* const srcMine = (srcGui != 0) ? ItChargeMineOfGui(srcGui, &srcUid) : 0;
    int forMoney = -1;
    if (srcGui != 0) ItTradingForMoneyPair(srcGui, gui, &forMoney);
    const int sameShop = (copy != 0 && dstInv != 0 && dstInv == g_shopDrag.shopInv) ? 1 : 0;
    int route = coopshop::DropRoute(copy, sameShop, cg.gate, dg.gate, (dstMine != 0) ? 1 : 0, (srcMine != 0) ? 1 : 0, forMoney);
    /* TEST-ONLY refusehere (as I1): a trade this game would send is refused before anything moves */
    if (route == coopshop::kDropBuy && ItRefuseHere(tradecharge::kGateNoHolder, 1) != 0) route = coopshop::kDropReturnGuarded;
    if (route == coopshop::kDropSell && ItRefuseHere(tradecharge::kGateNoHolder, 1) != 0) route = coopshop::kDropReturnPlain;
    if (route == coopshop::kDropOriginal) return 0;
    if (route == coopshop::kDropGuardedOriginal) { ++g_shopDragSameShop; return 2; }
    if (route == coopshop::kDropReturnGuarded || route == coopshop::kDropReturnPlain)
    {
        const int guarded = (route == coopshop::kDropReturnGuarded) ? 1 : 0;
        if (ShopReturnFn() == 0) return guarded ? 2 : 0;   /* no put-back to call: a copy drops under the guard, anything else as before */
        if (guarded != 0) ++g_shopDragReturned; else ++g_shopDragReturnPlain;
        const int gateUnknown = (copy != 0) ? ((cg.gate == coopshop::kGateRefuse) ? 1 : 0) : ((dg.gate == coopshop::kGateRefuse) ? 1 : 0);
        if (gateUnknown != 0) { ++g_shopDragRefusedGate; if (((copy != 0) ? cg.caravan : dg.caravan) != 0) ++g_shopCarRefusedGate; }   /* T-1 B5 */
        DebugLog("[SHOP] drag " + std::string(copy != 0 ? "of a shop copy" : "onto a shop not held here") + " put back"
                 + std::string(guarded != 0 ? " under the guard" : "") + ": " + std::string(gateUnknown != 0 ? "the shop's holder is not known"
                 : (copy != 0 ? "not dropped on a window of ours in a money trade" : "not a money sale of an item of ours"))
                 + " (copyGate=" + N((long long)cg.gate) + " dstGate=" + N((long long)dg.gate) + " forMoney=" + N((long long)forMoney)
                 + ") - nothing traded, nothing sent");
        ShopReturnPod(mouse, guarded);
        ShopDragTrackCursor();
        ShopFreeByValueStr(sectionStr);
        return 1;
    }
    /* BUY (route kDropBuy) or SALE (kDropSell): n and the item's description BEFORE the put-back, the price after it */
    const int buy = (route == coopshop::kDropBuy) ? 1 : 0;
    char secName[kSecCap];
    void* const dstSec = ShopSectionNamed(dstInv, sectionStr, secName);
    int q = 0, fn = 0;
    const int qOk = (ItIntPod(held, kItemQuantity, &q) != 0 && q > 0) ? 1 : 0;
    const int stackMax = (dstSec != 0) ? ShopStackMax(held, dstSec) : -1;
    /* M2 / L2 (fold): the units the destination affords, asked as 0x714990 :447-458 asks it - Item slot 0x298 with the destination's
       money and the SOURCE window record's +10 side flag. A buy: our purse; a sale: the shop's money (the drop window's, slot 0x1B8). */
    int afford = -1;
    int purse = -1;
    int srcSide = -1;
    ShopWinRecFlagPod(srcGui, kWinRecSide, &srcSide);
    if (buy != 0) { if (ItPurseRead(dstMine, &purse) == 0) purse = -1; }
    else ShopGuiMoneyPod(gui, &purse);
    if (purse < 0 || srcSide < 0 || ShopAffordPod(held, purse, srcSide, &afford) == 0) { afford = -1; ++g_shopDragAffordUnread; }
    const int n = (qOk != 0) ? coopshop::DragUnits(q, stackMax, afford) : 0;
    ItEntry fe; ItClear(&fe);
    const int described = (ItReadFields(held, &fe) == 1) ? 1 : 0;
    const int money = (ItIntPod(held, kItemFunction, &fn) != 0 && fn == kItemFuncMoney) ? 1 : 0;
    /* M1 (fold): the engine drop's first check, the range 0x70C6C0 (decomp_714990 :81-90), and the right-click's lock test, as I1 runs
       them (coopshop::PreCheck). The drop's other checks - the 0x2E container-type refusal (:130-143), the per-cell fit 0x74B380
       (:148-160), the section-type test 0x5935C0 (:162-176) and the locked-under-the-footprint test (:190-270) - decide WHERE the item
       lands in the drop window; I1 runs none of them and the holder places the units itself, so they are not run here. */
    const int locked = (ShopItemLockedPod(held) == 1) ? 1 : 0;
    const int range = ShopRangePod(gui, srcGui);
    const int pre = coopshop::PreCheck(locked, (range == 1) ? 1 : 0, money, qOk);
    if (pre == coopshop::kTrOutOfRange) ShopSoundPod(gui, "gui_notrade", held);   /* the drop's own sound (:85), while the item is live */
    coopmark::OwnerId own;
    if (described != 0) ItOwnerTranslate(fe.ownerRaw, fe.ownerHave, &own, 0);   /* book 0: a comparison, not a send */
    void* const backInv = (buy != 0) ? g_shopDrag.shopInv : 0;
    void* const copySt = (buy != 0) ? g_shopDrag.st : 0;   /* kept: the put-back below forgets the copy */
    void* sellInv = 0;
    if (buy == 0 && (srcGui == 0 || ItGuiInventoryCall(srcGui, &sellInv) == 0)) sellInv = 0;
    /* the put-back: a copy under the guard (the window shows it again, no piece touched), our own item plainly (the pack re-adds it) */
    if (buy != 0) ++g_shopDragReturned;
    if (ShopReturnPod(mouse, buy) == 0)
    {
        ++g_shopDragUnread;
        return (buy != 0) ? 2 : 0;   /* unreachable while ShopPickupGate requires the return hook; a sale then runs as before */
    }
    ShopDragTrackCursor();
    ShopFreeByValueStr(sectionStr);
    if (pre != 0)
    {
        ++g_shopIcPre;
        if (pre != coopshop::kTrQuiet) ShopShowResultPod(pre);   /* the engine's own answer (decomp_714990 :84, 0x70EC10) */
        DebugLog("[SHOP] drag " + std::string(buy != 0 ? "BUY" : "SALE") + " refused by the drop's own checks: result " + N((long long)pre)
                 + " (locked=" + N((long long)locked) + " range=" + N((long long)range) + " money=" + N((long long)money) + ") - put back, nothing sent");
        return 1;
    }
    if (n <= 0 && afford == 0)
    {
        ++g_shopIcShort;
        ShopShowResultPod(coopshop::DragShortResult(srcSide));   /* the engine's own answer (decomp_714990 :472-476): 3 our purse, 4 the shop's */
        return 1;
    }
    const unsigned int keeperUid = (buy != 0) ? ((cg.keeper != 0) ? FindSpawnedUid(cg.keeper) : 0) : ((dg.keeper != 0) ? FindSpawnedUid(dg.keeper) : 0);
    int fq = 0;
    void* const found = (n > 0 && described != 0 && money == 0)
        ? ShopFindStack((buy != 0) ? backInv : sellInv, ShopDescOfEntry(fe), n, held, (buy != 0) ? 0 : &own, &fq) : 0;
    int unit = -1;
    const int priced = (found != 0 && ShopUnitPricePod(found, (buy != 0) ? 0 : 1, fq, &unit) != 0 && unit >= 0) ? 1 : 0;
    const int price = (priced != 0) ? coopshop::TotalPrice(unit, n) : -1;
    char sid[kSidCap]; sid[0] = 0;
    if (found != 0) ItBaseSidPod(found, sid, kSidCap);
    if (found == 0 || keeperUid == 0 || sid[0] == 0 || price < 0)
    {
        ++g_shopDragUnread;
        DebugLog("[SHOP] drag " + std::string(buy != 0 ? "BUY" : "SALE") + " REFUSED here after the put-back: " + std::string(money != 0 ? "a money item is never carried"
                 : (n <= 0 ? "no unit to move" : (found == 0 ? "the item was not found again where it went back" : (keeperUid == 0 ? "the keeper carries no uid"
                 : "the price did not read")))) + " (n=" + N((long long)n) + " stackMax=" + N((long long)stackMax) + " afford=" + N((long long)afford) + ") - nothing sent");
        return 1;
    }
    ShopSendArgs sa;
    sa.dir = (buy != 0) ? 0 : 1; sa.sound = 1; sa.q = fq; sa.n = n; sa.entry = coopshop::kEntryDrag; sa.unit = unit; sa.price = price;
    sa.soundGui = (buy != 0) ? gui : srcGui; sa.srcInv = (buy != 0) ? backInv : sellInv; sa.item = found;
    sa.mine = (buy != 0) ? dstMine : srcMine; sa.mineUid = (buy != 0) ? dstUid : srcUid;
    sa.st = (buy != 0) ? copySt : dstSt;
    sa.shopInv = (buy != 0) ? backInv : dstInv; sa.keeper = (buy != 0) ? cg.keeper : dg.keeper; sa.keeperUid = keeperUid;
    sa.hk = (buy != 0) ? cg.hk : dg.hk; sa.sid = sid; sa.caravan = (buy != 0) ? cg.caravan : dg.caravan;   /* T-1 B5 */
    int mark = 0;
    const int res = ShopSendTrade(sa, &mark);
    if (mark == 1) { if (buy != 0) ++g_shopDragBuy; else ++g_shopDragSell; } else ++g_shopDragNotSent;
    if (res == coopshop::kTrNoRoom) ShopShowResultPod(coopshop::kTrNoRoom);   /* the right-click hands 2 to the engine, which shows it */
    DebugLog("[SHOP] drag " + std::string(buy != 0 ? "BUY" : "SALE") + " intercepted at the drop: n=" + N((long long)n) + " of " + N((long long)q)
             + " (stackMax=" + N((long long)stackMax) + " afford=" + N((long long)afford) + ") item=" + std::string(sid) + " price=" + N((long long)price)
             + " " + std::string(mark == 1 ? "SENT" : (mark == 2 ? "refused: can't afford" : "refused here (result " + N((long long)res) + ")"))
             + " - the engine's drop did not run; the " + std::string(buy != 0 ? "copy went back to the window under the guard" : "item went back to the pack first"));
    return 1;
}

/* THE HOLDER'S SHOP BRANCH, keyed on the trader's HOME - T-1 B5: or on a caravan's packs, the same steps on ShopStockResolve's
   stock (MAIN THREAD; not behind the applying guard - the piece moves and the keeper's pot are this game's own and publish as such). It re-checks from its own state (the home resolves, this game holds it, the keeper
   uid is that home's trader with a squad pot, the access policy, refusenext), then BUY: n units of the record across the home's
   pieces in chain order (0x951BA0's first-holder rule), removed and destroyed, the keeper paid (ItKeeperPaySquad, a gift); SALE: the
   keeper pays first (short = reason 4), the item is created and filed in the first piece that accepts it (0x951B10's rule), no room
   = the keeper refunded, reason 2. The confirm names the item, n, the price and every piece key written. */
void ApplyShopRequest(const ItemRequestMsg& r, unsigned int fromPeer)
{
    ItemConfirmMsg cf;
    cf.id = r.id; cf.ok = 0; cf.quantity = r.shop.n; cf.trade = r.trade; cf.price = 0;
    cf.toKey = fromPeer; cf.toHave = 1;   /* M7b slice 2: the answer goes back to the asker */
    cf.shop.has = 1;
    const int n = r.shop.n;
    const int blockOk = (((r.dir == 0 && r.trade == 1) || (r.dir == 1 && r.trade == 2)) && n > 0
                         && coopshop::TotalPrice(r.shop.unitPrice, n) == r.price && r.shop.sid == r.baseSid) ? 1 : 0;
    /* T-1 B5: the stock the request names - a home's pieces, or a caravan's packs (held by the game that runs the keeper's squad,
       coopshop::CaravanHolder: a pack worn by a member - or a formal leader - the other game runs is kVNotHolder, nothing moves) */
    const int caravan = (r.shop.stock == coopshop::kStockCaravan) ? 1 : 0;
    ShopStock stock;
    int heldHere = 0, keeperOk = 0;
    const int stockFound = ShopStockResolve(r.shop.stock, r.shop.homeKey, r.shop.keeperUid, &stock, &heldHere, &keeperOk);
    void* const home = stock.home;
    void* const keeper = stock.keeper;
    const int policyOk = (caravan != 0) ? 1 : ((home != 0 && BoxAccessAllowed(home, fromPeer, false)) ? 1 : 0);   /* E36 is a building's; a caravan has none */
    if (keeper != 0) PtHolderLegsCheck(r, keeper, fromPeer);   /* T-619: the price legs on the real keeper - counted and said, never refused */
    int refuseNext = 0;
    int common = coopshop::HolderCommon(stockFound, heldHere, keeperOk, policyOk, 0, blockOk);
    if (common == coopshop::kVOk && g_refuseNextLeft > 0 && r.price > 0)
    {   /* TEST-ONLY refusenext: the earliest point where the holder would otherwise accept - nothing has moved */
        --g_refuseNextLeft; refuseNext = 1;
        const int rn = (g_refuseNextReason >= 0 && g_refuseNextReason < kRefuseNameCount) ? g_refuseNextReason : 0;
        if (g_refuseNames[rn].counter != 0) ++*g_refuseNames[rn].counter;
        DebugLog("[ITEMS] refusenext used reason=" + std::string(g_refuseNames[rn].name) + " left=" + N((long long)g_refuseNextLeft)
                 + " id=" + N((long long)r.id) + " trade=" + N((long long)r.trade) + " price=" + N((long long)r.price) + " peer=" + N((long long)fromPeer)
                 + " (TEST-ONLY lever: a shop request refused before anything moved on this game)");
        common = coopshop::RefuseNextVerdict(g_refuseNames[rn].name);   /* T620 fold: the named reason's own verdict (keeperBroke 7 -> message 4) */
        DebugLog("[ITEMS] refusenext verdict=" + N((long long)common) + " (" + std::string(g_refuseNames[rn].name) + ")");
    }
    /* fold 2 (MED 2 / item 12): a record of this peer under an older epoch belongs to a requester process that has ended (its link went
       down and its world left) - it can never be acked or revoked: dropped now, said and counted (appliedStale) */
    for (size_t i = 0; i < g_shopApplied.size(); )
    {
        const ShopApplied& s = g_shopApplied[i];
        if (coopshop::RecordStale(s.peer == fromPeer ? 1 : 0, s.epoch, r.shop.epoch) == 0) { ++i; continue; }
        ++g_shopAppliedStale;
        ErrorLog("[SHOP] holder: applied " + std::string(s.dir == 0 ? "BUY" : "SELL") + " id=" + N((long long)s.id) + " n=" + N((long long)s.n)
                 + " price=" + N((long long)s.price) + " of peer " + N((long long)s.peer) + " was never acked and that requester restarted"
                 " (new epoch) - the record is dropped. Counted shopRec appliedStale.");
        g_shopApplied.erase(g_shopApplied.begin() + (std::ptrdiff_t)i);
    }
    /* fold 2 (MED 2): a full record table refuses a NEW shop trade before anything moves - an unacked record is never evicted */
    if (common == coopshop::kVOk && coopshop::RecordAdmit(g_shopApplied.size(), kShopAppliedCap) == 0)
    {
        common = coopshop::kVBusy;
        ++g_shopAppliedFull;
        DebugLog("[SHOP] holder id=" + N((long long)r.id) + ": the applied-record table is full (" + N((long long)g_shopApplied.size())
                 + " unacked) - REFUSED before anything moved. Counted shopRec appliedFull.");
    }
    std::vector<std::string> touched;
    int verdict = common;
    int paid = 0;   /* fold 2 (LOW 7): the cats the keeper really received (buy) / paid out (sale) */
    std::string srcKey;   /* T-1 B5 fold 2 (T811 L8): a buy's piece the FIRST removed units came from - its undo files there first */
    int soldN = n, soldPrice = r.price;   /* T-447 leftover 1: what this trade moved - less than asked only for a PARTIAL sale */
    if (r.dir == 0)
    {
        /* the stacks of EXACTLY the clicked variant across the home's pieces, chain order (MED 4 fold: the buy carries the full
           description since protocol 93; a stack of another maker / material / grade is not the item that was priced) */
        std::vector<void*> items, invs; std::vector<int> qty, pieceOf;
        if (common == coopshop::kVOk) ShopCollectStacks(stock.invs, ShopDescOfReq(r), &items, &invs, &qty, &pieceOf);
        int held = 0;
        for (size_t i = 0; i < qty.size(); ++i) held += qty[i];
        verdict = coopshop::HolderBuy(common, held, n);
        if (verdict == coopshop::kVOk)
        {
            std::vector<int> takes(qty.size() + 1, 0);
            coopshop::TakePlan(qty.empty() ? 0 : &qty[0], (int)qty.size(), n, &takes[0]);
            int got = 0, described = 0;
            for (size_t i = 0; i < qty.size(); ++i)
            {
                if (takes[i] <= 0) continue;
                void* gone = ShopRemovePod(invs[i], items[i], (takes[i] >= qty[i]) ? -1 : takes[i]);
                if (gone == 0) { ++g_shopHoldTakeFault; continue; }
                got += takes[i];
                if (described == 0)
                {
                    ItEntry fe; ItClear(&fe);
                    if (ItReadFields(gone, &fe) == 1)
                    {
                        described = 1;
                        cf.baseSid = fe.baseSid; cf.companySid = fe.companySid; cf.materialSid = fe.materialSid; cf.colorSid = fe.colorSid;
                        cf.quality = fe.quality; cf.charges = fe.charges; cf.functionKind = fe.functionKind; cf.level = fe.level; cf.unique = fe.unique;
                        ItOwnerTranslate(fe.ownerRaw, fe.ownerHave, &cf.owner);
                    }
                }
                ItDestroyPod(gone, "coop T-164 B4-4 holder: units bought by the other game's player out of this shop");
                if (std::find(touched.begin(), touched.end(), stock.keys[pieceOf[i]]) == touched.end()) touched.push_back(stock.keys[pieceOf[i]]);
                if (srcKey.empty()) srcKey = stock.keys[pieceOf[i]];   /* T-1 B5 fold 2: TakePlan's first source that gave units */
            }
            if (got != n || described == 0)
            {
                /* LEFTOVER: a take that faulted part-way leaves what it removed removed; the requester is refunded */
                verdict = coopshop::kVFault;
                ErrorLog("[SHOP] holder BUY id=" + N((long long)r.id) + ": took " + N((long long)got) + " of " + N((long long)n) + " (described="
                         + N((long long)described) + ") - REFUSED; the units taken stay taken. Counted shopHold takeFault.");
            }
            else if (r.price > 0)
            {
                const int t = ItKeeperPaySquad(keeper, -r.price);   /* a gift into the keeper's squad money - it cannot be refused */
                if (t == 1) { paid = r.price; ShopPotPublish(stock, (size_t)pieceOf[0]); }
                else ++g_shopHoldKeeperPayFailed;
            }
            if (verdict == coopshop::kVOk) g_shopLastBuySid = r.baseSid;   /* T-1 B5 fold 1 TEST-ONLY (packbuytest sid=lastbuy): the holder applied this buy */
        }
    }
    else
    {
        int pay = 1;
        if (common == coopshop::kVOk && r.price > 0) pay = ItKeeperPaySquad(keeper, r.price);   /* the keeper pays first */
        int placed = 0;
        if (common == coopshop::kVOk && pay == 1)
        {
            ItemMoveMsg mm;
            mm.baseSid = r.baseSid; mm.companySid = r.companySid; mm.materialSid = r.materialSid; mm.colorSid = r.colorSid;
            mm.quality = r.quality; mm.charges = r.charges; mm.functionKind = r.functionKind; mm.level = r.level; mm.unique = r.unique;
            mm.quantity = n; mm.owner = r.owner;
            ::Item* it = ItCreateItem(0, mm, 1);
            /* T-447 leftover 1: a piece may absorb part of the stack into its own stacks and refuse the rest; the next piece is then
               offered only the rest. `got` = the units the shop's pieces took; every piece that took units is named (asked again).
               T-1 B5: a caravan's packs in squad-member order, the same loop (no destroy-on-fail: ItAddAnywhereCount). */
            int got = 0, faulted = 0;
            for (size_t pi = 0; it != 0 && placed == 0 && faulted == 0 && pi < stock.invs.size(); ++pi)
            {
                ::Inventory* inv = (::Inventory*)stock.invs[pi];
                if (inv == 0) continue;
                int took = 0;
                const int ad = ItAddAnywhereCount(inv, (void*)it, &took);
                if (ad == -1) { faulted = 1; continue; }
                if (ad == -2)
                {   /* T-447 review 6 / fold 2: the quantity could not be read - nothing tried; the object is unfiled and goes below */
                    ++g_shopHoldQtyUnread;
                    ErrorLog("[SHOP] holder SELL id=" + N((long long)r.id) + ": the sold item's quantity could not be read - it is offered to no"
                             " more pieces (the shop took " + N((long long)got) + " of " + N((long long)n) + "). Counted shopPartial holdQtyUnread.");
                    break;
                }
                if (ad == 1 || took > 0) touched.push_back(stock.keys[pi]);
                if (ad == 1) placed = 1; else got += took;
            }
            if (placed == 1 || got > n) got = n;
            int splitN = n, splitPrice = r.price, payBack = 0;   /* T-447 review 7: the split is coopshop::HolderSellSplit's */
            coopshop::HolderSellSplit(n, r.shop.unitPrice, r.price, got, &splitN, &splitPrice, &payBack);
            if (faulted != 0)
            {
                ++g_shopAddFault;
                ErrorLog("[SHOP] holder SELL id=" + N((long long)r.id) + ": a piece's add FAULTED - the rest of the sold stack is left as it is"
                         " (never destroyed or offered again); the shop is counted as having taken " + N((long long)got) + " of " + N((long long)n)
                         + " units. Counted shopFold addFault.");
            }
            if (got < n)
            {
                if (it != 0 && faulted == 0)
                    ItDestroyPod((void*)it, got > 0 ? "T-447 shop holder: the rest of a sold stack no piece of the shop had room for"
                                                     : "coop T-164 B4-4 holder: a sold item no piece of the shop accepted");
                int backOk = 1;
                if (payBack > 0 && ItKeeperPaySquad(keeper, -payBack) != 1) { ++g_shopHoldKeeperPayFailed; backOk = 0; }   /* the keeper's pay back: the rest's price only */
                if (got > 0)
                {   /* a PARTIAL sale: the shop took `got` of the n units and only those are sold - the requester keeps the rest of its escrow */
                    placed = 1;
                    soldN = splitN; soldPrice = splitPrice;
                    ++g_shopHoldSellPartial;
                    paid = (backOk != 0) ? soldPrice : r.price;
                    if (paid > 0) ShopPotPublish(stock, 0);
                    DebugLog("[SHOP] holder SELL id=" + N((long long)r.id) + " PARTIAL: the shop's pieces had room for " + N((long long)got) + " of "
                             + N((long long)n) + " units - sold " + N((long long)got) + " for " + N((long long)soldPrice) + "; the rest is destroyed here"
                             " and stays the seller's (its escrow). Counted shopPartial holdSell.");
                }
            }
            else if (r.price > 0) { paid = r.price; ShopPotPublish(stock, 0); }
        }
        verdict = coopshop::HolderSell(common, pay, placed);
        if (verdict == coopshop::kVOk)
        {
            cf.baseSid = r.baseSid; cf.companySid = r.companySid; cf.materialSid = r.materialSid; cf.colorSid = r.colorSid;
            cf.quality = r.quality; cf.charges = r.charges; cf.functionKind = r.functionKind; cf.level = r.level; cf.unique = r.unique;
        }
        if (verdict == coopshop::kVKeeperBroke && refuseNext == 0) ++g_shopKeeperBroke;   /* T620 fold: the lever counted it already */
    }
    cf.ok = (verdict == coopshop::kVOk) ? 1 : 0;
    cf.shop.verdict = verdict;
    cf.shop.show = coopshop::ShowResult(verdict);
    cf.shop.n = (cf.ok != 0) ? soldN : 0;   /* T-447 leftover 1: a partial sale names the units it moved */
    cf.shop.price = (cf.ok != 0) ? soldPrice : 0;
    cf.price = cf.shop.price;
    if (touched.size() > (size_t)coopshop::kMaxPieces) touched.resize((size_t)coopshop::kMaxPieces);
    cf.shop.pieces = touched;
    if (cf.ok != 0) { if (r.dir == 0) ++g_shopHoldBuyOk; else ++g_shopHoldSellOk; } else { ++g_shopHoldRefused; ++g_reqRefused; }
    if (caravan != 0) { if (cf.ok != 0) ++g_shopCarHeld; else ++g_shopCarHoldRefused; }   /* T-1 B5 */
    if (cf.ok != 0)
    {
        /* HIGH 2 fold: the applied row is remembered, so a revoke (the requester's answer to this ok arriving after its lapse) can undo it.
           fold 2 (MED 2): kept until the requester's ack; keyed {peer, epoch, id}; paid = what the keeper really moved (LOW 7) */
        ShopApplied a;
        a.id = r.id; a.peer = fromPeer; a.at = ::GetTickCount(); a.keeperUid = r.shop.keeperUid; a.dir = r.dir; a.n = soldN; a.price = soldPrice;
        a.epoch = r.shop.epoch; a.paid = paid;
        a.homeKey = r.shop.homeKey; a.stock = r.shop.stock;   /* T-1 B5: the undo resolves the same stock */
        a.srcKey = (r.dir == 0) ? srcKey : std::string();   /* T-1 B5 fold 2: a buy undo's first piece; a sale's undo is unchanged */
        a.mm.baseSid = cf.baseSid; a.mm.companySid = cf.companySid; a.mm.materialSid = cf.materialSid; a.mm.colorSid = cf.colorSid;
        a.mm.quality = cf.quality; a.mm.charges = cf.charges; a.mm.functionKind = cf.functionKind; a.mm.level = cf.level; a.mm.unique = cf.unique;
        a.mm.quantity = soldN; a.mm.owner = (r.dir == 0) ? cf.owner : r.owner;
        g_shopApplied.push_back(a);   /* fold 2 (MED 2): never evicted - admitted above only while the table had room; the ack drops it */
        if (r.dir == 0) { g_shopLastBuyDesc = a.mm; g_shopLastBuyHaveDesc = 1; }   /* T-1 B5 fold 2 TEST-ONLY: packfill template=created */
    }
    if (!touched.empty()) ShopHolderRefresh(stock, touched);   /* MED 7 fold: this game's own open shop window shows what it wrote */
    DebugLog("[SHOP] holder " + std::string(r.dir == 0 ? "BUY" : "SELL") + " id=" + N((long long)r.id) + " item=" + r.shop.sid + " n=" + N((long long)n)
             + " price=" + N((long long)r.price) + " " + ShopStockWords(r.shop.stock, r.shop.homeKey, r.shop.keeperUid) + " keeper=" + N((long long)r.shop.keeperUid) + " peer=" + N((long long)fromPeer)
             + " verdict=" + N((long long)verdict) + (cf.ok != 0 ? " APPLIED" : " REFUSED")
             + (soldN != n ? " PARTIAL sold=" + N((long long)soldN) + " for " + N((long long)soldPrice) : std::string()) + " pieces=" + N((long long)touched.size())
             + " (" + (caravan != 0 ? "packs=" + N((long long)stock.invs.size()) + " wearers mine/other/unknown=" + N((long long)stock.wMine) + "/"
                       + N((long long)stock.wOther) + "/" + N((long long)stock.wUnknown) : "home=" + N((long long)(home != 0 ? 1 : 0)))
             + " held=" + N((long long)heldHere) + " keeper=" + N((long long)keeperOk)
             + " policy=" + N((long long)policyOk) + " block=" + N((long long)blockOk) + ")");
    if (!ItSendConfirm(cf)) ++g_reqConfirmSendFailed;
}

