/* loot2c - TEST-ONLY LEVER `boxtake <n> <sid|any>`. Among the n nearest non-player boxes to this game's lowest owned
   player-faction character (boxopen's rule), the NEAREST one whose research rows hold <sid> (any row for `any`) is opened
   through the engine's own loot open (_showTradeWindow TW_LOOTING, as boxopen). Once this player's copies are shown, ONE copy
   of <sid> is moved into that character's inventory through the engine's own transfer calls (removeItemDontDestroy whole
   stack -> _addItem at a free slot, the itemtake lever's pair) at the K2 safe point, so the drain sees the copy's REMOVE
   from its box - the take on leave. The window is held 1 s more, then closeAllInventories. Nothing shown within 10 s:
   `shown=0` (the expected answer once this player has taken that box's copy). */
std::string g_boxTakeKey, g_boxTakeSid, g_boxTakeResult;
int g_boxTakeState = 0;   /* 0 idle, 1 open, 2 wait for the show, 3 move asked (K2), 4 hold then close */
unsigned int g_boxTakeAt = 0;
int g_boxTakeTown[kTownHandDwords];
int g_boxTakeHaveTown = 0;
long long g_boxTakeArmed = 0, g_boxTakeMoved = 0, g_boxTakeNothing = 0, g_boxTakeFailed = 0;
int ItLootCopyFor(const std::string& key, const std::string& sid)
{
    for (int i = 0; i < kLootRegCap; ++i)
        if (g_lootReg[i].used != 0 && ItLootState(i) == kCopyLive && g_lootReg[i].key == key && (sid == "any" || g_lootReg[i].sid == sid)) return i;
    return -1;
}
std::string BoxTakeCommand(const std::string& arg)
{
    int n = 0; char sidBuf[128]; sidBuf[0] = 0;
    if (std::sscanf(arg.c_str(), "%d %127s", &n, sidBuf) != 2 || n < 1 || n > 32)
        return "error boxtake: usage boxtake <n> <sid|any> (n 1..32: the nearest of the n nearest boxes with a research row for <sid>)";
    if (g_base == 0 || kShowTradeWindowRva == 0 || kCloseInventoriesRva == 0 || orig_showInventory == 0)
        return "error boxtake: the showInventory hook or the open/close calls are not installed";
    if (g_researchMode == 0) return "error boxtake: researchmode is off - no research copies are shown";
    if (StoreTearingDown() != 0) return "error boxtake: the engine is tearing the world down - try again";
    if (g_boxOpenState != 0) return "error boxtake: a boxopen run is still going";
    if (g_boxTakeState != 0) return "error boxtake: a boxtake is still going (key " + g_boxTakeKey + ")";
    if (ItParityCursorBusy() != 0) return "error boxtake: something is on the cursor - opening a window closes every window, and a close can destroy a cursor item";
    ::Character* opener = ItBoxOpenOpener();
    float cp[3]; cp[0] = 0; cp[1] = 0; cp[2] = 0;
    if (opener == 0 || ItBoxPosPod(opener, cp) == 0) return "error boxtake: no player-faction character with a uid this game owns";
    long long ps = 0, kl = 0;
    g_furnTriedGen = -1;
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl);
    std::vector<std::pair<float, std::string> > cand;
    for (int r = 0; r < rn; ++r)
    {
        float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
        if (ItBoxPosPod(g_parityRefs[r].b, bp) == 0) continue;
        const float dx = bp[0] - cp[0], dz = bp[2] - cp[2];
        cand.push_back(std::make_pair(dx * dx + dz * dz, std::string(g_parityRefs[r].key)));
    }
    std::sort(cand.begin(), cand.end());
    const std::string sid(sidBuf);
    std::string pick; int rank = 0; float dist = 0;
    for (size_t i = 0; i < cand.size() && (int)i < n && pick.empty(); ++i)
    {
        std::map<std::string, std::vector<coopres::ResearchRow> >::const_iterator rw = g_researchRows.find(cand[i].second);
        if (rw == g_researchRows.end()) continue;
        for (size_t r = 0; r < rw->second.size(); ++r)
            if (rw->second[r].index >= 0 && (sid == "any" || rw->second[r].sid == sid)) { pick = cand[i].second; rank = (int)i + 1; dist = std::sqrt(cand[i].first); break; }
    }
    if (pick.empty())
        return "error boxtake: none of the " + N((long long)n) + " nearest boxes (candidates=" + N((long long)cand.size()) + ") has a research row for " + sid
             + " (known boxes=" + N((long long)g_researchRows.size()) + ")";
    g_boxTakeKey = pick; g_boxTakeSid = sid; g_boxTakeResult.clear(); g_boxTakeState = 1; g_boxTakeAt = 0; ++g_boxTakeArmed;
    char dd[32]; std::sprintf(dd, "%.0f", dist);
    ItLootSay("[LOOT2] boxtake armed key=" + pick + " sid=" + sid + " rank=" + N((long long)rank) + " dist=" + std::string(dd));
    return "ok boxtake armed key=" + pick + " sid=" + sid + " rank=" + N((long long)rank) + " (see [LOOT2] boxtake)";
}
void ItBoxTakeDrive()
{
    if (g_boxTakeState == 0) return;
    const unsigned int now = ::GetTickCount();
    if (g_boxTakeState == 1)
    {
        if (ItParityCursorBusy() != 0) { ++g_boxTakeFailed; g_boxTakeState = 0; ItLootSay("[LOOT2] boxtake STOPPED key=" + g_boxTakeKey + " - an item is on the cursor"); return; }
        void* b = ItBoxResolve(g_boxTakeKey.c_str());
        ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
        ::Character* opener = ItBoxOpenOpener();
        if (inv == 0 || opener == 0) { ++g_boxTakeFailed; g_boxTakeState = 0; ItLootSay("[LOOT2] boxtake skip key=" + g_boxTakeKey + (inv == 0 ? std::string(" - the box no longer resolves") : std::string(" - no opener"))); return; }
        if (g_boxTakeHaveTown == 0) g_boxTakeHaveTown = ItSaveTownHand(g_boxTakeTown);
        if (ItOpenLootWindow(opener, b) == 0 || ItParityWindowOpen(inv) == 0)
        { ++g_boxTakeFailed; g_boxTakeResult = "no window"; g_boxTakeState = 4; g_boxTakeAt = now; ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " - the loot open made no window"); return; }
        g_boxTakeState = 2; g_boxTakeAt = now;
        ItLootSay("[LOOT2] boxtake opened key=" + g_boxTakeKey + " - waiting for this player's copies");
        return;
    }
    if (g_boxTakeState == 2)
    {
        if (ItLootCopyFor(g_boxTakeKey, g_boxTakeSid) >= 0) { g_boxTakeState = 3; g_boxTakeAt = now; return; }
        if ((unsigned int)(now - g_boxTakeAt) > 10000u)
        {
            ++g_boxTakeNothing; g_boxTakeResult = "shown none";
            ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " sid=" + g_boxTakeSid + " shown=0 - no copy of it was shown to this player (already taken by this player, or no row)");
            g_boxTakeState = 4; g_boxTakeAt = now;
        }
        return;
    }
    if (g_boxTakeState == 3)
    {
        if ((unsigned int)(now - g_boxTakeAt) > 3000u) { ++g_boxTakeFailed; g_boxTakeResult = "the K2 move never ran"; g_boxTakeState = 4; g_boxTakeAt = now; }
        return;
    }
    if ((unsigned int)(now - g_boxTakeAt) < 1000u) return;
    const int closed = ItCloseTradeWindow(g_boxTakeTown, g_boxTakeHaveTown);
    g_boxTakeHaveTown = 0; g_boxTakeState = 0;
    ItLootSay("[LOOT2] boxtake done key=" + g_boxTakeKey + " sid=" + g_boxTakeSid + " result=" + g_boxTakeResult + " closeAllInventories=" + N((long long)closed)
              + " boxtake[armed,moved,shownNone,failed]=" + N(g_boxTakeArmed) + "," + N(g_boxTakeMoved) + "," + N(g_boxTakeNothing) + "," + N(g_boxTakeFailed));
}
/* ======================= inv6 phase 1 - TEST-ONLY levers under `itemtest` (design Q5) =======================
   `itemtest steal <n> [sid]`: among the n nearest non-player boxes to this game's lowest owned player-faction character (boxopen's
   rule) whose building (or its furniture parent) names a RESIDENT SQUAD (Building+0xD0 - who the engine's findProperOwner marks a box
   theft with), the nearest one holding a non-money item (a single item first; `sid` = a base-sid substring) is opened through the
   engine's own loot open and ONE item is right-clicked into that character through `InventoryGUI::RClickAutoTrade` 0x713150 with
   thieveryChecks 1 - the player's own path, so the ENGINE writes the mark and runs its crime arm. The landed cell is remembered.
   On the game that holds the box that is an ordinary move (R1); on the other it becomes a TAKE request (the drain undoes it, D5-2).
   `itemtest stolen <me|peer|name>`: read-only - every item in that character (own or copy) whose owner hand is set.
   `itemtest givestolen <peer|name>`: GIVE the remembered stolen stack to that character through the itemgive lever (R2).
   MAIN THREAD (the command channel; the steal's open / move / close run from ItemsTick, as boxtake's). [OWN] lines. */
std::string g_stealKey, g_stealWant, g_stealResult;
int g_stealState = 0;   /* 0 idle, 1 open, 2 move, 3 hold then close */
unsigned int g_stealAt = 0;
int g_stealTown[kTownHandDwords];
int g_stealHaveTown = 0;
std::string g_stolenSid, g_stolenSec;
int g_stolenX = -1, g_stolenY = -1, g_stolenHave = 0;
long long g_stealArmed = 0, g_stealMoved = 0, g_stealFailed = 0;
/* 1 = the box (or its furniture parent) names a resident squad; its five words in w5. */
int ItBoxOwnerSquadPod(void* b, unsigned int* w5)
{
    __try
    {
        /* Building::furnitureParentBuilding 0xD5F60 is exactly these two loads (see kBldFurnitureLayout above) */
        void* src = b;
        void* layout = *(void* const*)((const char*)b + kBldFurnitureLayout);
        if (ItPlaus(layout)) { void* host = *(void* const*)((const char*)layout + kLayoutOwnerBuilding); if (ItPlaus(host)) src = host; }
        for (int i = 0; i < 5; ++i) w5[i] = ((const unsigned int*)((const char*)src + kBldResidentSquad))[i];
        return coopmark::RawHandIsOwner(w5) ? 1 : 0;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
/* The engine's own wasStolen(includeUnknown) 0x79D9B0, both ways. 1 the calls were made. */
int ItIsStolenPod(void* item, int* s0, int* s1)
{
    *s0 = -1; *s1 = -1;
    __try { *s0 = ((::Item*)item)->wasStolen(false) ? 1 : 0; *s1 = ((::Item*)item)->wasStolen(true) ? 1 : 0; return 1; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
/* The item to steal in `sec`'s grid: non-money, base sid containing `want` (any when empty), a SINGLE item first (a stack's
   right-click moves a one-unit clone, which the E22b pairing does not see as the same object). */
::Item* ItStealPick(::InventorySection* sec, const std::string& want, int* x, int* y, char* sidOut)
{
    *x = -1; *y = -1; sidOut[0] = 0;
    if (!ItObj(sec)) return 0;
    const Ogre::vector< ::InventorySection::SectionItem>::type& ps = sec->items;
    if (ps.size() > 4096) return 0;
    for (int pass = 0; pass < 2; ++pass)
        for (size_t k = 0; k < ps.size(); ++k)
        {
            ::Item* it = ps[k].item;
            if (!ItObj(it)) continue;
            char cs[kSidCap]; std::memset(cs, 0, sizeof(cs));
            ItBaseSidPod(it, cs, kSidCap);
            if (cs[0] == 0 || (!want.empty() && std::string(cs).find(want) == std::string::npos)) continue;
            int fn = 0, q = 0;
            if (ItIntPod(it, kItemFunction, &fn) == 0 || fn == kItemFunctionMoney) continue;
            if (ItIntPod(it, kItemQuantity, &q) == 0) continue;
            if (pass == 0 && q != 1) continue;
            *x = (int)ps[k].x; *y = (int)ps[k].y; std::memcpy(sidOut, cs, kSidCap);
            return it;
        }
    return 0;
}
/* A marked item of base sid `sid` in `sec`'s grid (the remembered cell first). */
::Item* ItStolenFind(::InventorySection* sec, const std::string& sid, int prefX, int prefY, int* x, int* y)
{
    *x = -1; *y = -1;
    if (!ItObj(sec)) return 0;
    const Ogre::vector< ::InventorySection::SectionItem>::type& ps = sec->items;
    if (ps.size() > 4096) return 0;
    ::Item* found = 0;
    for (size_t k = 0; k < ps.size(); ++k)
    {
        ::Item* it = ps[k].item;
        if (!ItObj(it)) continue;
        char cs[kSidCap]; std::memset(cs, 0, sizeof(cs));
        ItBaseSidPod(it, cs, kSidCap);
        unsigned int w[5];
        if (sid != cs || ItRawHandAtPod(it, kItemOwnerHand, w) == 0 || !coopmark::RawHandIsOwner(w)) continue;
        if (found == 0 || ((int)ps[k].x == prefX && (int)ps[k].y == prefY)) { found = it; *x = (int)ps[k].x; *y = (int)ps[k].y; }
    }
    return found;
}
/* inv6 fold (T401): the section and cell of `item` in `inv`, by ADDRESS only (the object is never read - it may be gone). 1 found. */
int ItObjSectionOf(::Inventory* inv, const ::Item* item, char* secOut, int* x, int* y)
{
    secOut[0] = 0; *x = -1; *y = -1;
    if (inv == 0 || item == 0) return 0;
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) return 0;
    for (ItSecMap::const_iterator si = secs.begin(); si != secs.end(); ++si)
    {
        ::InventorySection* sec = si->second;
        if (!ItObj(sec)) continue;
        const Ogre::vector< ::InventorySection::SectionItem>::type& ps = sec->items;
        if (ps.size() > 4096) continue;
        for (size_t k = 0; k < ps.size(); ++k)
            if (ps[k].item == item)
            {
                ItSecNameInto((const char*)sec + kSecName, secOut);
                *x = (int)ps[k].x; *y = (int)ps[k].y;
                return 1;
            }
    }
    return 0;
}
void ItStealSay(const std::string& s) { DebugLog(s); }
std::string ItemTestStealCommand(const std::string& arg)
{
    int n = 0; char sidBuf[128]; sidBuf[0] = 0;
    const int got = std::sscanf(arg.c_str(), "%d %127s", &n, sidBuf);
    if (got < 1 || n < 1 || n > 32) return "error itemtest steal: usage itemtest steal <n> [sid] (n 1..32)";
    if (g_base == 0 || kRClickAutoTradeRva == 0 || kShowTradeWindowRva == 0 || kCloseInventoriesRva == 0 || orig_showInventory == 0)
        return "error itemtest steal: the trade call or the open / close calls are not installed";
    if (StoreTearingDown() != 0) return "error itemtest steal: the engine is tearing the world down - try again";
    if (g_stealState != 0) return "error itemtest steal: a steal is still going (box " + g_stealKey + ")";
    if (g_boxTakeState != 0 || g_boxOpenState != 0) return "error itemtest steal: a boxtake / boxopen run is still going";
    if (ItParityCursorBusy() != 0) return "error itemtest steal: something is on the cursor - opening a window closes every window";
    ::Character* opener = ItBoxOpenOpener();
    float cp[3]; cp[0] = 0; cp[1] = 0; cp[2] = 0;
    if (opener == 0 || ItBoxPosPod(opener, cp) == 0) return "error itemtest steal: no player-faction character with a uid this game owns";
    long long ps = 0, kl = 0;
    g_furnTriedGen = -1;
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl);
    std::vector<std::pair<float, int> > cand;
    for (int r = 0; r < rn; ++r)
    {
        float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
        if (ItBoxPosPod(g_parityRefs[r].b, bp) == 0) continue;
        const float dx = bp[0] - cp[0], dz = bp[2] - cp[2];
        cand.push_back(std::make_pair(dx * dx + dz * dz, r));
    }
    std::sort(cand.begin(), cand.end());
    const std::string want(sidBuf);
    int noSquad = 0, nothing = 0, rank = 0;
    std::string pick, pickSid;
    unsigned int sq[5]; std::memset(sq, 0, sizeof(sq));
    for (size_t i = 0; i < cand.size() && (int)i < n && pick.empty(); ++i)
    {
        void* b = g_parityRefs[cand[i].second].b;
        if (ItBoxOwnerSquadPod(b, sq) == 0) { ++noSquad; continue; }
        ::Inventory* inv = ItBoxInventory(b);
        std::string sn;
        ::InventorySection* sec = (inv != 0) ? ItGeneralSection(inv, &sn) : 0;
        int x = -1, y = -1; char sid[kSidCap]; sid[0] = 0;
        if (sec == 0 || ItStealPick(sec, want, &x, &y, sid) == 0) { ++nothing; continue; }
        pick = g_parityRefs[cand[i].second].key; pickSid = sid; rank = (int)i + 1;
    }
    if (pick.empty())
    {
        ItStealSay("[OWN] steal n=" + N((long long)n) + " candidates=" + N((long long)cand.size()) + " noResidentSquad=" + N((long long)noSquad)
                   + " nothingToTake=" + N((long long)nothing) + " - no box to steal from");
        return "error itemtest steal: none of the " + N((long long)n) + " nearest boxes has a resident squad and a non-money item"
             + " (noResidentSquad=" + N((long long)noSquad) + " nothingToTake=" + N((long long)nothing) + ")";
    }
    g_stealKey = pick; g_stealWant = want; g_stealResult.clear(); g_stealState = 1; g_stealAt = 0; ++g_stealArmed;
    ItStealSay("[OWN] steal armed box=" + pick + " sid=" + pickSid + " rank=" + N((long long)rank) + " squadType=" + N((long long)sq[0]));
    return "ok itemtest steal armed box=" + pick + " sid=" + pickSid + " (see [OWN] steal)";
}
/* The move itself, with both windows open. */
void ItStealMove()
{
    void* b = ItBoxResolve(g_stealKey.c_str());
    ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
    ::Character* opener = ItBoxOpenOpener();
    ::Inventory* dinv = (opener != 0) ? ItInventoryOf(opener) : 0;
    if (inv == 0 || dinv == 0) { ++g_stealFailed; g_stealResult = "the box or the taker could not be read"; return; }
    void* g1 = 0; void* g2 = 0;
    ItInventoryGuiPod(inv, &g1);
    ItInventoryGuiPod(dinv, &g2);
    if (g1 != 0 && ItSameWindow(g1, inv) == 0) g1 = 0;
    if (g2 != 0 && ItSameWindow(g2, dinv) == 0) g2 = 0;
    if (g1 == 0 || g2 == 0 || g1 == g2) { ++g_stealFailed; g_stealResult = "no pair of open windows (box / taker)"; return; }
    std::string sn;
    ::InventorySection* sec = ItGeneralSection(inv, &sn);
    int x = -1, y = -1; char sid[kSidCap]; sid[0] = 0;
    ::Item* it = (sec != 0) ? ItStealPick(sec, g_stealWant, &x, &y, sid) : 0;
    if (it == 0) { ++g_stealFailed; g_stealResult = "nothing left to take in the box"; return; }
    int res = -1;
    const int called = ItRClickAutoTradePod(g1, &sn, x, y, g2, &res);
    std::string dn;
    ::InventorySection* dsec = ItGeneralSection(dinv, &dn);
    int fx = -1, fy = -1;
    ::Item* landed = 0;
    if (dsec != 0) { ItSlotOfInSection(dsec, it, &fx, &fy); if (fx >= 0) landed = it; }
    if (landed == 0 && dsec != 0) landed = ItStolenFind(dsec, std::string(sid), -1, -1, &fx, &fy);
    unsigned int w[5]; std::memset(w, 0, sizeof(w));
    int have = 0, s0 = -1, s1 = -1;
    if (landed != 0)
    {
        if (ItRawHandAtPod(landed, kItemOwnerHand, w) != 0) have = coopmark::RawHandIsOwner(w) ? 1 : 0;
        ItIsStolenPod(landed, &s0, &s1);
    }
    coopmark::OwnerId o;
    ItOwnerTranslate(w, have, &o);
    if (landed != 0) { g_stolenSid = sid; g_stolenSec = dn; g_stolenX = fx; g_stolenY = fy; g_stolenHave = 1; ++g_stealMoved; g_stealResult = "moved"; }
    else { ++g_stealFailed; g_stealResult = "not found in the taker's grid after the call"; }
    ItStealSay("[OWN] steal box=" + g_stealKey + " sid=" + std::string(sid) + " cell=" + dn + "," + N((long long)fx) + "," + N((long long)fy)
               + " owner=" + ItOwnerText(o) + " type=" + N((long long)w[0]) + " s0=" + N((long long)s0) + " s1=" + N((long long)s1)
               + " tradeResult=" + N((long long)res) + " called=" + N((long long)called)
               + (landed == 0 ? std::string(" - the item is not in the taker's general grid after the call") : std::string()));
    /* inv6 fold (T401): T399's right-click answered 1 and nothing moved - say WHERE the object is now: any section of the taker, or
       still the box (by address; none = in neither, e.g. merged or destroyed). */
    char tsec[kSecCap]; int tx = -1, ty = -1;
    char bsec[kSecCap]; int bx = -1, by = -1;
    const int inTaker = ItObjSectionOf(dinv, it, tsec, &tx, &ty);
    const int inBox = ItObjSectionOf(inv, it, bsec, &bx, &by);
    ItStealSay("[OWN] steal where box=" + g_stealKey + " sid=" + std::string(sid)
               + " taker=" + (inTaker != 0 ? std::string(tsec) + "," + N((long long)tx) + "," + N((long long)ty) : std::string("none"))
               + " stillInBox=" + (inBox != 0 ? std::string(bsec) + "," + N((long long)bx) + "," + N((long long)by) : std::string("none"))
               + " tradeResult=" + N((long long)res) + " called=" + N((long long)called));
}
void ItStealDrive()
{
    if (g_stealState == 0) return;
    const unsigned int now = ::GetTickCount();
    if (g_stealState == 1)
    {
        if (ItParityCursorBusy() != 0) { ++g_stealFailed; g_stealState = 0; ItStealSay("[OWN] steal STOPPED box=" + g_stealKey + " - an item is on the cursor"); return; }
        void* b = ItBoxResolve(g_stealKey.c_str());
        ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
        ::Character* opener = ItBoxOpenOpener();
        if (inv == 0 || opener == 0) { ++g_stealFailed; g_stealState = 0; ItStealSay("[OWN] steal skip box=" + g_stealKey + " - the box or the taker no longer resolves"); return; }
        if (g_stealHaveTown == 0) g_stealHaveTown = ItSaveTownHand(g_stealTown);
        if (ItOpenLootWindow(opener, b) == 0 || ItParityWindowOpen(inv) == 0)
        { ++g_stealFailed; g_stealResult = "no window"; g_stealState = 3; g_stealAt = now; return; }
        g_stealState = 2; g_stealAt = now;
        return;
    }
    if (g_stealState == 2)
    {
        if ((unsigned int)(now - g_stealAt) < 300u) return;
        ItStealMove();
        g_stealState = 3; g_stealAt = now;
        return;
    }
    if ((unsigned int)(now - g_stealAt) < 1000u) return;
    const int closed = ItCloseTradeWindow(g_stealTown, g_stealHaveTown);
    g_stealHaveTown = 0; g_stealState = 0;
    ItStealSay("[OWN] steal done box=" + g_stealKey + " result=" + g_stealResult + " closeAllInventories=" + N((long long)closed)
               + " steal[armed,moved,failed]=" + N(g_stealArmed) + "," + N(g_stealMoved) + "," + N(g_stealFailed));
}
std::string ItemTestStolenCommand(const std::string& who)
{
    if (who.empty()) return "error itemtest stolen: usage itemtest stolen <me|peer|name>";
    ::Character* c = 0; unsigned int u = 0; std::string nm; long long hits = 0;
    if (ItLeverPick(who, &c, &u, &nm, &hits) == 0) return "error itemtest stolen: no loaded character matches '" + who + "'";
    ::Inventory* inv = ItInventoryOf(c);
    if (inv == 0) return "error itemtest stolen: that character has no readable inventory";
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) return "error itemtest stolen: implausible section count";
    const long long t0 = g_markTranslated, u0 = g_markSenderUnknown;   /* a read-only listing books no send-side counter */
    int marked = 0, lines = 0;
    for (ItSecMap::const_iterator si = secs.begin(); si != secs.end(); ++si)
    {
        ::InventorySection* sec = si->second;
        if (!ItObj(sec)) continue;
        char snm[kSecCap]; snm[0] = 0;
        ItSecNameInto((const char*)sec + kSecName, snm);
        const Ogre::vector< ::InventorySection::SectionItem>::type& ps = sec->items;
        if (ps.size() > 4096) continue;
        for (size_t k = 0; k < ps.size(); ++k)
        {
            ::Item* item = ps[k].item;
            if (!ItObj(item)) continue;
            unsigned int w[5];
            if (ItRawHandAtPod(item, kItemOwnerHand, w) == 0 || !coopmark::RawHandIsOwner(w)) continue;
            ++marked;
            coopmark::OwnerId o;
            ItOwnerTranslate(w, 1, &o);
            int s0 = -1, s1 = -1, q = 0;
            ItIsStolenPod(item, &s0, &s1);
            ItIntPod(item, kItemQuantity, &q);
            char sid[kSidCap]; sid[0] = 0;
            ItBaseSidPod(item, sid, kSidCap);
            if (lines < 24)
            {
                ++lines;
                DebugLog("[OWN] stolen who='" + nm + "' uid=" + N((long long)u) + " cell=" + std::string(snm) + "," + N((long long)ps[k].x) + "," + N((long long)ps[k].y)
                         + " sid=" + std::string(sid) + " qty=" + N((long long)q) + " owner=" + ItOwnerText(o) + " type=" + N((long long)w[0])
                         + " tomb=0 s0=" + N((long long)s0) + " s1=" + N((long long)s1));
            }
        }
    }
    g_markTranslated = t0; g_markSenderUnknown = u0;
    DebugLog("[OWN] stolen who='" + nm + "' uid=" + N((long long)u) + " marked=" + N((long long)marked) + " (listed " + N((long long)lines) + ")");
    return "ok itemtest stolen who=" + nm + " uid=" + N((long long)u) + " marked=" + N((long long)marked);
}
std::string ItemTestGiveStolenCommand(const std::string& who)
{
    if (who.empty()) return "error itemtest givestolen: usage itemtest givestolen <peer|name>";
    if (g_stolenHave == 0) return "error itemtest givestolen: nothing remembered - run itemtest steal first";
    ::Character* me = 0; unsigned int mu = 0; std::string mn; long long mh = 0;
    if (ItLeverPick("me", &me, &mu, &mn, &mh) == 0) return "error itemtest givestolen: no own character";
    ::Inventory* inv = ItInventoryOf(me);
    std::string sn;
    ::InventorySection* sec = (inv != 0) ? ItGeneralSection(inv, &sn) : 0;
    int x = -1, y = -1;
    ::Item* it = (sec != 0) ? ItStolenFind(sec, g_stolenSid, g_stolenX, g_stolenY, &x, &y) : 0;
    if (it == 0)
    {
        DebugLog("[OWN] givestolen sid=" + g_stolenSid + " - no MARKED item of that sid in '" + mn + "' (remembered cell " + g_stolenSec + ","
                 + N((long long)g_stolenX) + "," + N((long long)g_stolenY) + ")");
        return "error itemtest givestolen: the remembered stolen stack (" + g_stolenSid + ") is not in my character, marked";
    }
    unsigned int w[5]; std::memset(w, 0, sizeof(w));
    ItRawHandAtPod(it, kItemOwnerHand, w);
    coopmark::OwnerId o;
    ItOwnerTranslate(w, 1, &o);
    const bool ok = ItemGive("me", sn, x, y, who);
    DebugLog("[OWN] givestolen sid=" + g_stolenSid + " cell=" + sn + "," + N((long long)x) + "," + N((long long)y) + " owner=" + ItOwnerText(o)
             + " to '" + who + "' -> " + (ok ? std::string("asked (see [ITEMS] itemgive)") : std::string("REFUSED (see [ITEMS] itemgive)")));
    return ok ? "ok itemtest givestolen sid=" + g_stolenSid : "error itemtest givestolen: the itemgive lever refused (see [ITEMS] itemgive)";
}
/* inv6 fold (T401) - TEST-ONLY `itemtest mark <sid|any> [<uid>]` (T399's steal moved nothing, so no marked item existed): on this
   game's first own player character (ItBoxOpenOpener) the first item of base sid `sid` in the general section (any = the first
   non-money item there) gets an owner hand through the item's own setProperOwner (vt+0x2B0: Item 0xD2120, ContainerItem 0x76B340)
   - the character <uid> (must resolve here), else the nearest live non-player character this game owns (any distance; T403 found none within 50 units). It is
   remembered for `givestolen` exactly as a steal is. A mark change publishes NOTHING (no hook sees setProperOwner; the mark rides
   only the next move / give / take). MAIN THREAD (the command channel).
   inv6p2 TEST lever: `itemtest mark <sid|any> [box|pack] [<uid>]` - an optional PLACE. `pack`: the first matching item in the
   backpack_content section of that character's WORN pack (ItBagFirstPack, as bagtest). `box`: the nearest box by boxopen's own
   selection (ItParityBoxes, default mode - player boxes left out - sorted by distance to ItBoxOpenOpener) that THIS game writes
   (ItBoxWriterAt == kBoxMine) and that holds a matching item, in any of its sections; a mark SET there queues that box for the fill
   push (g_fillDirty, ItParityFillPush), so its whole contents - the mark in the OWNL tail - go to the other game as a PARITY_BOX.
   Only a general-section mark is remembered for givestolen. */
/* inv6p2: the first item of `want` (any = the first non-money item) in one section. 1 found. */
int ItMarkFindIn(::InventorySection* sec, const std::string& want, int anySid, ::Item** it, int* x, int* y, char* sid)
{
    if (!ItObj(sec)) return 0;
    const Ogre::vector< ::InventorySection::SectionItem>::type& ps = sec->items;
    if (ps.size() > 4096) return 0;
    for (size_t k = 0; k < ps.size(); ++k)
    {
        ::Item* cand = ps[k].item;
        if (!ItObj(cand)) continue;
        char cs[kSidCap]; std::memset(cs, 0, sizeof(cs));
        ItBaseSidPod(cand, cs, kSidCap);
        if (cs[0] == 0 || (anySid == 0 && want != cs)) continue;
        int fn = 0;
        if (anySid != 0 && (ItIntPod(cand, kItemFunction, &fn) == 0 || fn == kItemFunctionMoney)) continue;
        *it = cand; *x = (int)ps[k].x; *y = (int)ps[k].y; std::memcpy(sid, cs, kSidCap);
        return 1;
    }
    return 0;
}
int ItIsDeadPod(::Character* c)
{
    __try { return c->hasDied() ? 1 : 0; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
/* items9: `itemtest set <any|sid|section:x,y> [q=<0-100>] [ch=<n>]` - TEST-ONLY (item-stats-parity.md 4), the same standing as the
   other itemtest verbs: the grade and/or the uses left of one item on this game's FIRST OWN character (the `mark` lever's character) -
   `any`, a base sid (the first such item in its general section) or a slot. ch= alone is the stand-in for drainMedkit / eatItem: a
   raw +0x118 write that publishes NOTHING here - the inventory safety net must catch it and send ITEM_MOVE op 4, which is what a
   player's medkit use gets. q= has no in-place engine writer (a grade never changes in play), so after a q= write the lever
   republishes the item as its owner's remove + add at the same slot - the other game rebuilds it with every field, as a move does. */
std::string ItemTestSetCommand(const std::string& arg)
{
    coopistat::SetArgs a; std::string err;
    if (coopistat::ParseSetArgs(arg, &a, &err) == 0)
        return "error itemtest set: " + err + " - usage itemtest set <any|sid|section:x,y> [q=<0-100>] [ch=<n>]";
    if (StoreTearingDown() != 0) return "error itemtest set: the engine is tearing the world down - try again";
    ::Character* me = ItBoxOpenOpener();
    if (me == 0) { DebugLog("[ITEMSET] REFUSED - no player-faction character with a uid this game owns"); return "error itemtest set: no own character"; }
    const unsigned int meUid = FindSpawnedUid(me);
    ::Inventory* inv = ItInventoryOf(me);
    if (inv == 0 || meUid == 0) return "error itemtest set: no inventory";
    std::string sn;
    ::InventorySection* sec = 0;
    ::Item* it = 0; int x = -1, y = -1;
    char sid[kSidCap]; std::memset(sid, 0, sizeof(sid));
    if (a.isSlot != 0)
    {
        sn = a.section;
        sec = inv->getSection(sn);
        if (!ItObj(sec)) return "error itemtest set: no section '" + sn + "'";
        if (ItSlotInSectionWhy(sec, a.x, a.y) != 1 || !ItObj(it = sec->getItemAt(a.x, a.y))) return "error itemtest set: nothing at " + a.ref;
        x = a.x; y = a.y;
    }
    else
    {
        sec = ItGeneralSection(inv, &sn);
        ItMarkFindIn(sec, a.ref, (a.ref == "any") ? 1 : 0, &it, &x, &y, sid);
        if (it == 0) return "error itemtest set: no '" + a.ref + "' in " + (sn.empty() ? std::string("the general section") : sn);
    }
    static ItEntry before;
    ItClear(&before);
    if (ItReadFields(it, &before) != 1) return "error itemtest set: the item's fields will not read";
    if (a.haveQ != 0 && ItWriteFloatPod(it, kItemQuality, a.q) == 0) return "error itemtest set: the quality write faulted";
    if (a.haveCh != 0 && ItWriteFloatPod(it, kItemCharges, a.ch) == 0) return "error itemtest set: the charges write faulted";
    std::string pub("none (ch= only: the safety net publishes it as op 4)");
    if (a.haveQ != 0)
    {
        static ItEntry e;
        ItClear(&e);
        int qty = 1; ItIntPod(it, kItemQuantity, &qty);
        if (qty < 1) qty = 1;
        if (ItReadFields(it, &e) != 1) pub = "FAILED (the fields will not read after the write)";
        else
        {
            ItemMoveMsg rm;
            rm.uid = meUid; rm.op = 1; rm.section = sn; rm.x = x; rm.y = y; rm.quantity = qty;
            ItemMoveMsg ad;
            ItMsgFromEntry(e, &ad);
            ad.uid = meUid; ad.op = 0; ad.section = sn; ad.x = x; ad.y = y; ad.quantity = qty; ad.boxKey.clear();
            pub = (ItNetSendMove(rm) && ItNetSendMove(ad)) ? "remove+add sent" : "FAILED (send)";
        }
    }
    char q0[32], c0[32], q1[32], c1[32];
    float qa = before.quality, ca = before.charges;
    ItFloatPod(it, kItemQuality, &qa); ItFloatPod(it, kItemCharges, &ca);
    std::sprintf(q0, "%.2f", (double)before.quality); std::sprintf(c0, "%.2f", (double)before.charges);
    std::sprintf(q1, "%.2f", (double)qa); std::sprintf(c1, "%.2f", (double)ca);
    const std::string line = "uid=" + N((long long)meUid) + " item=" + std::string(before.baseSid) + " slot=" + sn + ":" + N((long long)x) + ","
        + N((long long)y) + " q=" + q0 + "->" + q1 + " ch=" + c0 + "->" + c1 + " published=" + pub;
    DebugLog("[ITEMSET] " + line + " (TEST-ONLY lever)");
    return "ok itemtest set " + line;
}
std::string ItemTestMarkCommand(const std::string& arg)
{
    char sidBuf[128]; sidBuf[0] = 0; char w2[32]; w2[0] = 0; unsigned int wantUid = 0;
    const int nw = std::sscanf(arg.c_str(), "%127s %31s %u", sidBuf, w2, &wantUid);
    if (nw < 1 || sidBuf[0] == 0) return "error itemtest mark: usage itemtest mark <sid|any> [box|pack] [<uid>]";
    const int place = (std::strcmp(w2, "pack") == 0) ? 1 : (std::strcmp(w2, "box") == 0) ? 2 : 0;   /* inv6p2 */
    int got = 1;
    if (nw >= 2 && place == 0)
    {
        if (std::sscanf(w2, "%u", &wantUid) != 1) return "error itemtest mark: usage itemtest mark <sid|any> [box|pack] [<uid>]";
        got = 2;
    }
    else if (nw >= 3) got = 2;
    if (StoreTearingDown() != 0) return "error itemtest mark: the engine is tearing the world down - try again";
    const std::string want(sidBuf);
    const int anySid = (want == "any") ? 1 : 0;
    ::Character* me = ItBoxOpenOpener();
    float cp[3]; cp[0] = 0; cp[1] = 0; cp[2] = 0;
    if (me == 0 || ItBoxPosPod(me, cp) == 0)
    { DebugLog("[OWN] mark REFUSED sid=" + want + " - no player-faction character with a uid this game owns"); return "error itemtest mark: no own character"; }
    const unsigned int meUid = FindSpawnedUid(me);
    ::Inventory* inv = ItInventoryOf(me);
    std::string sn, where("general"), boxKey;
    ::Item* it = 0; int x = -1, y = -1;
    char sid[kSidCap]; std::memset(sid, 0, sizeof(sid));
    if (place == 0)
    {
        ::InventorySection* sec = (inv != 0) ? ItGeneralSection(inv, &sn) : 0;
        ItMarkFindIn(sec, want, anySid, &it, &x, &y, sid);
    }
    else if (place == 1)   /* inv6p2: the worn pack's rows */
    {
        where = "pack";
        std::string psec; int px = -1, py = -1;
        void* pack = (inv != 0) ? ItBagFirstPack(inv, &psec, &px, &py) : 0;
        void* pinv = 0;
        if (pack != 0 && ItBagInvPod(pack, &pinv) != 0 && pinv != 0)
        { sn = "backpack_content"; ItMarkFindIn(((::Inventory*)pinv)->getSection(sn), want, anySid, &it, &x, &y, sid); }
        else sn = "(no worn pack)";
    }
    else   /* inv6p2: the nearest box this game WRITES that holds one */
    {
        where = "box";
        long long ps = 0, kl = 0;
        const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl, kPbLegacy);
        std::vector<std::pair<float, int> > cand;
        for (int r = 0; r < rn; ++r)
        {
            float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
            if (ItBoxPosPod(g_parityRefs[r].b, bp) == 0) continue;
            const float dx = bp[0] - cp[0], dz = bp[2] - cp[2];
            cand.push_back(std::make_pair(dx * dx + dz * dz, r));
        }
        std::sort(cand.begin(), cand.end());
        long long written = 0;
        for (size_t i = 0; i < cand.size() && it == 0; ++i)
        {
            void* b = g_parityRefs[cand[i].second].b;
            const std::string key(g_parityRefs[cand[i].second].key);
            float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
            if (ItBoxPosPod(b, bp) == 0 || ItBoxWriterAt(b, bp, key.c_str()) != kBoxMine) continue;
            ++written;
            ::Inventory* binv = ItBoxInventory(b);
            if (!ItObj(binv)) continue;
            const ItSecMap& secs = *(const ItSecMap*)((char*)binv + 0x28);
            if (secs.size() > 64) continue;
            for (ItSecMap::const_iterator si = secs.begin(); si != secs.end() && it == 0; ++si)
            {
                char nm[kSecCap]; nm[0] = 0;
                if (ItStrPod(&si->first, nm, kSecCap) == 0) continue;
                if (ItMarkFindIn(si->second, want, anySid, &it, &x, &y, sid) != 0) { sn = nm; boxKey = key; }
            }
        }
        if (it == 0) sn = "(" + N((long long)cand.size()) + " boxes near, " + N(written) + " written here, none holds it)";
    }
    if (it == 0)
    {
        DebugLog("[OWN] mark REFUSED sid=" + want + " place=" + where + " - no such item in '" + sn + "' of uid=" + N((long long)meUid));
        return "error itemtest mark: no item '" + want + "' in my " + where + " " + sn;
    }
    ::Character* owner = 0; unsigned int ownerUid = 0; float bestD = 0;
    if (got >= 2)
    {
        ::Character* c = (wantUid != 0) ? FindSpawned(wantUid) : 0;
        if (ItPlaus(c) && ItObj(c)) { owner = c; ownerUid = wantUid; }
    }
    else if (ItPlaus(coop::GameWorldPtr()))
    {
        ::Faction* mineF = LocalPlayerFaction();
        const GameHashSet< ::Character*>::type& all = coop::GameWorldPtr()->activeCharacters();
        if (all.size() <= 20000)
            for (GameHashSet< ::Character*>::type::const_iterator ci = all.begin(); ci != all.end(); ++ci)
            {
                ::Character* c = *ci;
                if (!ItObj(c) || c == me) continue;
                const unsigned int u = FindSpawnedUid(c);
                if (u == 0 || !net::IsUidMine(u)) continue;
                void* f = 0;
                if (ItFactionPod(c, &f) == 0 || f == 0 || f == (void*)mineF || IsPlayerFaction((::Faction*)f)) continue;
                if (ItIsDeadPod(c) != 0) continue;
                float pp[3]; pp[0] = 0; pp[1] = 0; pp[2] = 0;
                if (ItBoxPosPod(c, pp) == 0) continue;
                const float dx = pp[0] - cp[0], dz = pp[2] - cp[2];
                const float d = dx * dx + dz * dz;
                if (owner == 0 || d < bestD) { owner = c; ownerUid = u; bestD = d; }
            }
    }
    if (owner == 0)
    {
        DebugLog("[OWN] mark REFUSED sid=" + std::string(sid) + " - " + (got >= 2 ? "uid " + N((long long)wantUid) + " does not resolve on this game"
                 : std::string("no live non-player character this game owns (nearest, any distance - T403: none within 50 units)")));
        return "error itemtest mark: no owner character";
    }
    unsigned int w[5]; std::memset(w, 0, sizeof(w));
    if (ItRawHandAtPod(owner, kRootHandFields, w) == 0 || !coopmark::RawHandIsOwner(w) || w[0] != coopmark::kHandTypeCharacter)
    {
        DebugLog("[OWN] mark REFUSED sid=" + std::string(sid) + " owner uid=" + N((long long)ownerUid) + " - its own hand is unreadable or not a character's");
        return "error itemtest mark: the owner's hand is unreadable";
    }
    const hand h = ItHandFromRaw(w);
    const int r = ItSetOwnerPod(it, &h, w[0]);
    int s0 = -1, s1 = -1;
    ItIsStolenPod(it, &s0, &s1);
    unsigned int rw[5]; std::memset(rw, 0, sizeof(rw));
    const int rh = (ItRawHandAtPod(it, kItemOwnerHand, rw) != 0 && coopmark::RawHandIsOwner(rw)) ? 1 : 0;
    const long long t0 = g_markTranslated, u0 = g_markSenderUnknown;   /* a TEST read-back books no send-side counter */
    coopmark::OwnerId o;
    ItOwnerTranslate(rw, rh, &o);
    g_markTranslated = t0; g_markSenderUnknown = u0;
    if (r == 1 && place == 0) { g_stolenSid = sid; g_stolenSec = sn; g_stolenX = x; g_stolenY = y; g_stolenHave = 1; }
    int pushQueued = 0;   /* inv6p2: a box mark publishes that box's contents through the fill push */
    if (r == 1 && place == 2 && !boxKey.empty() && (g_fillDirty.size() < kFillDirtyCap || g_fillDirty.count(boxKey) != 0))
    { g_fillDirty[boxKey]; pushQueued = 1; }
    DebugLog("[OWN] mark sid=" + std::string(sid) + " place=" + where + (boxKey.empty() ? std::string() : " box=" + boxKey)
             + (place == 2 ? (pushQueued != 0 ? std::string(" pushQueued=1") : std::string(" pushQueued=0")) : std::string()) + " cell=" + sn + "," + N((long long)x) + "," + N((long long)y) + " of uid=" + N((long long)meUid)
             + " ownerUid=" + N((long long)ownerUid) + " owner=" + ItOwnerText(o) + " type=" + N((long long)rw[0])
             + (r == 1 ? std::string(" SET") : r == 2 ? std::string(" set but read back different") : std::string(" FAULTED"))
             + " s0=" + N((long long)s0) + " s1=" + N((long long)s1) + (r == 1 && place == 0 ? std::string(" (remembered for givestolen)") : std::string()));
    return (r == 1) ? "ok itemtest mark sid=" + std::string(sid) + " ownerUid=" + N((long long)ownerUid) + " s0=" + N((long long)s0)
                    : std::string("error itemtest mark: the owner set did not read back (see [OWN] mark)");
}
void BoxTakeDrain()
{
    if (g_boxTakeState != 3) return;
    g_boxTakeState = 4; g_boxTakeAt = ::GetTickCount();
    const int r = ItLootCopyFor(g_boxTakeKey, g_boxTakeSid);
    void* b = ItBoxResolve(g_boxTakeKey.c_str());
    ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
    ::Character* opener = ItBoxOpenOpener();
    ::Inventory* dstInv = (opener != 0) ? ItInventoryOf(opener) : 0;
    void* item = (r >= 0) ? g_lootReg[r].item : 0;
    std::string secName; int sx = 0, sy = 0;
    if (item == 0 || inv == 0 || dstInv == 0 || ItLootLocate(inv, item, &secName, &sx, &sy) == 0)
    { ++g_boxTakeFailed; g_boxTakeResult = "the copy, the box or the character could not be read"; ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " - " + g_boxTakeResult); return; }
    ::InventorySection* srcSec = inv->getSection(secName);
    std::string dstSecName;
    ::InventorySection* dstSec = ItGeneralSection(dstInv, &dstSecName);
    if (!ItObj(srcSec) || !ItObj(dstSec)) { ++g_boxTakeFailed; g_boxTakeResult = "no section"; ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " - no source or destination section"); return; }
    void* moved = 0;
    if (ItTakeOutPod(inv, item, -1, &moved) == 0 || moved == 0) { ++g_boxTakeFailed; g_boxTakeResult = "take-out faulted"; ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " - the engine's take-out faulted"); return; }
    ItemsLootTouch(item, kLootTouchLever);   /* part A step 11: the lever's take-out is a touch (the removeItem detour has normally marked it already); the drain / after-drain step records it */
    int x = -1, y = -1, placed = 0;
    if (ItFirstFreeSlot(dstSec, moved, &x, &y) != 0) placed = ItAddAtPod(dstSec, moved, x, y);
    if (placed != 1)
    {
        const int back = ItAddAtPod(srcSec, moved, sx, sy);   /* part A: touched = this player's real item - back into the box, materialised after the drain */
        if (back != 1) ItDestroyPod(moved, "coop boxtake: the character had no room and the box would not take the item back");
        ++g_boxTakeFailed; g_boxTakeResult = "the character had no room";
        ItLootSay("[LOOT2] boxtake key=" + g_boxTakeKey + " - the character had no room (" + (back == 1 ? std::string("put back into the box: this player's real item now")
                  : std::string("DESTROYED - the take stands (test lever only)")) + ")");
        return;
    }
    ++g_boxTakeMoved; g_boxTakeResult = "moved";
    ItLootSay("[LOOT2] boxtake moved key=" + g_boxTakeKey + " sid=" + g_boxTakeSid + " into section=" + dstSecName + " slot=" + N((long long)x) + "," + N((long long)y)
              + " - the drain sees the take next tick");
}
/* MAIN THREAD, ItParityTick (before the drain): unsent take rows, queued opens shown, the lever. The close retract and the slot reaping run AFTER the drain (ItLootAfterDrain). */
void ItLootTick()
{
    for (int i = 0; i < kLootRegCap; ++i) if (g_lootReg[i].used != 0 && g_lootReg[i].item == 0) ItLootFree(i);
    if (!g_lootUnconf.empty() && StoreLinkIsUp())   /* part A: unconfirmed takes marked for sending (a failed send, or every WELCOME) */
        for (size_t i = 0; i < g_lootUnconf.size(); ++i)
        {
            if (g_lootUnconf[i].needSend == 0) continue;
            if (!ItLootSendTake(g_lootUnconf[i].t)) { ++g_lootTakeSendFailed; break; }
            g_lootUnconf[i].needSend = 0;
        }
    if (::InterlockedExchange(&g_lootCloseMark, 0) != 0)
    {
        ++g_lootCloseSignals;
        if (ItLootRetractClosed() != 0) ::InterlockedExchange(&g_lootCloseMark, 1);
    }
    if (!g_lootShowQ.empty())
    {
        const unsigned int now = ::GetTickCount();
        for (std::map<std::string, unsigned int>::iterator it = g_lootShowQ.begin(); it != g_lootShowQ.end(); )
        {
            if (ItLootShowBox(it->first, (unsigned int)(now - it->second)) != 0) g_lootShowQ.erase(it++); else ++it;
        }
    }
    ItBoxTakeDrive();
    ItStealDrive();   /* inv6: the TEST-ONLY `itemtest steal` lever's window and move */
}
/* MAIN THREAD, every ItemsTick, BEFORE the ring drain: zone arrivals, the asks, deferred re-asks. The holder's answers and
   the asker's queued swaps run AFTER the drain (ItParityAfterDrain, review-par1 4a). */
/* inv7d (e47-inv7-replan 6, inv4 phase P5): THE OWNER'S ARRIVAL EDGE. When this game's own bit appears in a sector's notebook
   map (a new MyMapLoadedSinceTS stamp - the event), every box THIS game owns there is put through the writer decision once
   (ItBoxWriterDecide -> the owner rung -> ItHandbackGate), which asks the area's previous writer for the current contents
   before this game writes the box. Until inv7d the gate ran only when some other writer decision happened to reach the box,
   so an arrival with no move, open or push on the box never asked, and the owner's stale copy stood. The gate itself keeps
   "once per stamp"; this only makes sure the stamp is seen. Polled with the active-zone set (once a second). MAIN THREAD. */
double g_arriveSwept[4096];            /* sector index -> the stamp already swept (0 none) */
unsigned char g_arrivePolls[4096];     /* sector index -> one-second polls it has been active here (capped) */
void ItOwnerArriveTick()
{
    static DWORD s_last = 0;
    const DWORD nowMs = ::GetTickCount();
    if ((DWORD)(nowMs - s_last) < 1000u) return;
    s_last = nowMs;
    if (StorePlayerReachable(-1) == 0) return;   /* nobody to ask: the session link, or another player in the world through the world server */
    static unsigned char dueSec[4096];
    static double dueSince[4096];
    std::memset(dueSec, 0, sizeof(dueSec));
    int due = 0;
    for (int s = 0; s < 4096; ++s)
    {
        if (g_parityZoneNow[s] == 0) { g_arrivePolls[s] = 0; g_arriveSwept[s] = 0.0; continue; }
        if (g_arrivePolls[s] < 250) ++g_arrivePolls[s];
        Sector sc; sc.x = s / 64; sc.y = s % 64;
        const double since = MyMapLoadedSinceTS(sc);
        if (since <= 0.0) { g_arriveSwept[s] = 0.0; continue; }
        if (coopwriter::OwnerArriveEdge(since, g_arriveSwept[s], (int)g_arrivePolls[s]) != coopwriter::kArriveSweep) continue;
        dueSec[s] = 1; dueSince[s] = since; due = 1;
    }
    if (due == 0) return;
    long long ps = 0, kl = 0;
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl, kPbOwn);   /* only boxes this game owns */
    for (int r = 0; r < rn; ++r)
    {
        const int sx = g_parityRefs[r].sx, sy = g_parityRefs[r].sy;
        if (sx < 0 || sx >= 64 || sy < 0 || sy >= 64 || dueSec[sx * 64 + sy] == 0) continue;
        float pos[3]; pos[0] = 0; pos[1] = 0; pos[2] = 0;
        if (ItBoxPosPod(g_parityRefs[r].b, pos) == 0) continue;
        ItBoxWriterDecide(g_parityRefs[r].b, pos, g_parityRefs[r].key, kAreaForBox, 0, "arrive");
        ++g_arriveSweepBoxes;
    }
    for (int s = 0; s < 4096; ++s)
        if (dueSec[s] != 0) { g_arriveSwept[s] = dueSince[s]; ++g_arriveSweeps; }
}
void ItParityTick()
{
    g_paritySwapBoxesTick = 0; g_paritySwapItemsTick = 0;   /* review-par1 6b: the swap budget is per tick */
    /* review-par1 minor 4: RE-ARMED ON LINK-UP. An ask made while the link was down went nowhere, and one in flight when it
       dropped may never be answered; on the rising edge every active sector counts as arriving again, so its boxes are
       listed and asked for afresh (recurrence-covered: each later link-up does the same). */
    static int s_wasLinked = 0;
    int forcePoll = 0;
    {
        const int linked = net::SessionLinked() ? 1 : 0;
        static long s_arrCursor = 0;   /* M11 C2: re-armed at every player entering the world (the old link's up edge is the session peer's) */
        if (StoreArrivalsSince(kArrServeParity, &s_arrCursor, 0) > 0)
        {
            ++g_parityRelinks;
            std::memset(g_parityZoneNow, 0, sizeof(g_parityZoneNow));
            g_parityPending.clear();
            g_grCatchWait.clear();   /* every active sector arrives again on the next poll and lists its ground again */
            forcePoll = 1;
        }
        s_wasLinked = linked;
    }
    if (g_base == 0 || StoreTearingDown() != 0 || EngineWritesBlocked()) return;
    ItBoxOpenDrive();      /* parity3: the test lever opens its next box (its open is queued by the detour) */
    ItLootTick();          /* loot2c: close signals -> retract, queued opens -> show, the boxtake lever, unsent take rows */
    ItResearchLiftTick();  /* loot2b fold 2: pending lifts - echoed ones removed and published, the rest dropped on link loss or timeout */
    ItParityOpenDrain();   /* parity3: every box opened since the last tick asks its holder now */
    /* 1. the active-zone set, read ONCE A SECOND (review-par1 6d, ZonesTick's own cadence) and at once after a link-up or a
       world teardown: an arrival becomes pending, a departure forgets its activation */
    static unsigned int s_lastPoll = 0;
    int polledNow = 0;   /* P109 R1: step 2b runs on the zone poll's cadence */
    const unsigned int nowMs = ::GetTickCount();
    if (forcePoll != 0 || g_parityPollNow != 0 || (unsigned int)(nowMs - s_lastPoll) >= 1000u)
    {
        s_lastPoll = nowMs; g_parityPollNow = 0; polledNow = 1;
        static int zx[64], zy[64];
        static unsigned char now[4096];
        const int zn = ActiveZoneSectors(zx, zy, 64);
        if (zn >= 0)
        {
            std::memset(now, 0, sizeof(now));
            for (int i = 0; i < zn; ++i) if (zx[i] >= 0 && zx[i] < 64 && zy[i] >= 0 && zy[i] < 64) now[zx[i] * 64 + zy[i]] = 1;
            int left = 0;
            for (int s = 0; s < 4096; ++s)
            {
                if (now[s] != 0 && g_parityZoneNow[s] == 0) { if (kParityArrivalAsks != 0) g_parityPending[s] = ItParitySector(); g_furnDirty = 1; }   /* P94 (owner 219): an arrival lists its boxes and asks their holder */
                else if (now[s] == 0 && g_parityZoneNow[s] != 0) { g_parityPending.erase(s); g_grCatchWait.erase(s); g_parityPullSecDone[s] = 0; left = 1; }
            }
            if (left != 0) g_parityRetryN.clear();
            std::memcpy(g_parityZoneNow, now, sizeof(now));
            /* the ground settle record: cleared for every sector not active here; one ground walk per poll while an active
               sector's ground is not settled yet (cooppar::GroundSettleStep). A walk cut at its cap counts nothing, and with that
               many items loaded it may be cut on every poll, so it resets nothing: a sector it cannot count is settled once it has
               been active for kGrSettleCapPolls polls (the fewest a whole walk needs) */
            int unsettled = 0;
            for (int s = 0; s < 4096; ++s)
            {
                g_grSecLoaded[s] = (now[s] != 0) ? (unsigned char)GrSectorLoadedNow(s) : (unsigned char)0;
                if (now[s] == 0 || g_grSecLoaded[s] == 0)
                {   /* not active, or active but not loaded by the engine yet: its ground count says nothing */
                    if (now[s] != 0) ++g_grSettleNotLoaded;
                    g_grSettleState[s] = 0; g_grSettleLast[s] = 0; g_grSettlePolls[s] = 0;
                }
                else
                {
                    if (g_grSettlePolls[s] < 255) ++g_grSettlePolls[s];
                    if (g_grSettleState[s] != 2) unsettled = 1;
                }
            }
            if (unsettled != 0)
            {
                static int counts[4096];
                int walkedN = 0;
                const int whole = GrGroundCounts(counts, &walkedN);
                static int s_capLogged = 0;
                if (whole == 0 && s_capLogged == 0)
                {
                    s_capLogged = 1;
                    DebugLog("[GROUND] settle: the ground walk is capped (" + N((long long)walkedN) + " items) - sectors settle on time"
                             " (logged once per session; counted groundSettle cappedOnTime)");
                }
                for (int s = 0; s < 4096; ++s)
                {
                    if (now[s] == 0 || g_grSettleState[s] == 2) continue;
                    if (whole == 0)
                    {
                        if (g_grSettlePolls[s] >= kGrSettleCapPolls) { g_grSettleState[s] = 2; ++g_grSettleCapped; }
                        continue;
                    }
                    cooppar::GroundSettleStep(&g_grSettleLast[s], &g_grSettleState[s], counts[s]);
                }
            }
        }
    }
    ItOwnerArriveTick();   /* inv7d: the owner's arrival edge asks for its own boxes (after the zone poll above) */
    /* 2. pending sectors: list their boxes once settled, then ask when the holder verdict is settled */
    if (!g_parityPending.empty())
    {
        ItFurnEnsure();
        if (ItFurnValid() != 0)
        {
            int needScan = 0;
            for (std::map<int, ItParitySector>::iterator it = g_parityPending.begin(); it != g_parityPending.end(); ++it)
            {
                ++it->second.ticks;
                if (it->second.scanned == 0 && it->second.ticks >= kParityScanAfterTicks) needScan = 1;
            }
            /* review-par1 6a: ONE enumeration per tick, shared by the scan and the asks below - the asks read each box through
               the pointer this tick's walk and live registry rows found, never ItBoxResolve per key */
            int refsTick = 0, rn = 0;
            if (needScan != 0)
            {
                long long ps = 0, kl = 0;
                rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl, kPbAsk);   /* inv4: no player-owned box in the arrival ask */
                refsTick = 1;
                for (std::map<int, ItParitySector>::iterator it = g_parityPending.begin(); it != g_parityPending.end(); ++it)
                {
                    if (it->second.scanned != 0 || it->second.ticks < kParityScanAfterTicks) continue;
                    const int sx = it->first / 64, sy = it->first % 64;
                    for (int r = 0; r < rn; ++r)
                        if (g_parityRefs[r].sx == sx && g_parityRefs[r].sy == sy) it->second.keys.push_back(std::string(g_parityRefs[r].key));
                    it->second.scanned = 1;
                }
            }
            for (std::map<int, ItParitySector>::iterator it = g_parityPending.begin(); it != g_parityPending.end(); )
            {
                ItParitySector& ps = it->second;
                if (ps.scanned == 0) { ++it; continue; }
                /* the sector's verdict, asked at the first box's own keyed position. P94 fold 1 (review F4): a sector whose scan
                   listed no box is asked at its centre point and waits for its verdict too, so P109's mark does not depend on a
                   box having been listed; it is then dropped as `sectorsEmpty` with nothing asked. */
                ItBoxKeyParts kp;
                float pos[3]; pos[0] = 0; pos[1] = 0; pos[2] = 0;
                if (ps.keys.empty()) { Sector cs; cs.x = it->first / 64; cs.y = it->first % 64; SectorCentrePointTS(cs, pos); }
                else if (ItBoxKeyParse(ps.keys[0].c_str(), &kp) != 0) { pos[0] = (float)kp.x10 / 10.0f; pos[1] = (float)kp.y10 / 10.0f; pos[2] = (float)kp.z10 / 10.0f; }
                const int v = ItAreaVerdictAt(pos, kAreaForBox);
                if (StoreAreaPictureVerdict() == kPicLoading || v == kBoxNoAnswer)
                {
                    if (ps.ticks > kParityVerdictTicks) { ++g_parityGaveUp; ItParityMarkSector(it->first, 0, 0, 1); g_parityPending.erase(it++); } else ++it;   /* P109 R3: a gave-up arrival is marked */
                    continue;
                }
                ItParityMarkSector(it->first, (v == kBoxMine) ? 1 : 0, (v == kBoxHeld) ? 1 : 0, 0);   /* P94 / P109 (R3: cooppar::ParitySectorMark) */
                /* a sector another game holds is asked even with no box listed: the ask carries this game's ground items there
                   (the PRQG listing) and the holder answers with the items missing here or gone there (GrCatchUpServe) */
                if (ps.keys.empty() && v != kBoxHeld) { ++g_paritySectorsEmpty; g_parityPending.erase(it++); continue; }
                if (v == kBoxHeld)
                {
                    if (refsTick == 0 && !ps.keys.empty()) { long long ps2 = 0, kl2 = 0; rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps2, &kl2, kPbAsk); refsTick = 1; }
                    const int sx = it->first / 64, sy = it->first % 64;
                    std::vector<cooppar::ParityBoxRow> rows;
                    for (int r = 0; r < rn; ++r)
                    {
                        if (g_parityRefs[r].sx != sx || g_parityRefs[r].sy != sy) continue;
                        ::Inventory* inv = ItBoxInventory(g_parityRefs[r].b);
                        unsigned int d = 0; long long c = 0, u = 0;
                        if (inv == 0 || ItParityDigest(inv, &d, &c, &u) == 0) continue;
                        g_parityLocalUnread += u;
                        cooppar::ParityBoxRow row; row.key = g_parityRefs[r].key; row.digest = d; row.items = (unsigned int)c;
                        rows.push_back(row);
                    }
                    /* the ground listing only once the sector's ground is settled here (a zone item placed after the listing
                       would come back as a duplicate ADD); until then it waits in g_grCatchWait and the boxes are asked now */
                    const int settled = (g_grSettleState[it->first] == 2) ? 1 : 0;
                    std::vector<cooppar::ParityGroundRow> ground;
                    unsigned int groundLeft = 0;
                    if (settled != 0) groundLeft = GrCatchUpKeys(sx, sy, &ground);
                    else if (g_grCatchWait.count(it->first) == 0) { g_grCatchWait[it->first] = 0; ++g_grSettleAskWaited; }
                    ItParitySendReq(sx, sy, rows, cooppar::kParityAskPlain, settled != 0 ? &ground : 0, groundLeft);   /* P94 / P109: the sector was marked above (fold 1, F4) */
                    if (!ps.keys.empty()) ++g_parityAskSectors;
                    DebugLog("[PARITY] -> PARITY_REQ sector=" + N((long long)sx) + "," + N((long long)sy)
                             + " boxes=" + N((long long)rows.size()) + " listed=" + N((long long)ps.keys.size())
                             + (settled != 0 ? " ground=" + N((long long)ground.size()) : std::string(" ground=waiting for the sector to settle")));
                }
                else ++g_paritySectorsNotHeld;
                g_parityPending.erase(it++);
            }
        }
    }
    /* 2a. the ground listings waiting for their sector's ground to settle here: sent alone (no box rows) once it is settled while
       another game holds the sector; dropped when this game holds it now, or past kParityVerdictTicks drains (counted given up;
       the sector's ground is then not caught up); a sector that leaves the active set drops its wait at the zone poll */
    for (std::map<int, int>::iterator w = g_grCatchWait.begin(); w != g_grCatchWait.end(); )
    {
        const int sx = w->first / 64, sy = w->first % 64;
        Sector cs; cs.x = sx; cs.y = sy;
        float cpos[3]; cpos[0] = 0; cpos[1] = 0; cpos[2] = 0;
        SectorCentrePointTS(cs, cpos);
        const int v = ItAreaVerdictAt(cpos, kAreaForGround);
        if (v == kBoxMine) { ++g_grSettleAskGaveUp; g_grCatchWait.erase(w++); continue; }
        if (g_grSettleState[w->first] == 2 && v == kBoxHeld && StoreAreaPictureVerdict() != kPicLoading)
        {
            std::vector<cooppar::ParityGroundRow> ground;
            const unsigned int groundLeft = GrCatchUpKeys(sx, sy, &ground);
            std::vector<cooppar::ParityBoxRow> none;
            ItParitySendReq(sx, sy, none, cooppar::kParityAskPlain, &ground, groundLeft);
            DebugLog("[PARITY] -> PARITY_REQ sector=" + N((long long)sx) + "," + N((long long)sy) + " ground=" + N((long long)ground.size())
                     + " (the sector's ground settled here after " + N((long long)w->second) + " drains)");
            g_grCatchWait.erase(w++);
            continue;
        }
        if (g_grSecLoaded[w->first] == 0) { ++w; continue; }   /* the engine has not loaded the sector here yet: the wait is not counted */
        if (++w->second > kParityVerdictTicks) { ++g_grSettleAskGaveUp; g_grCatchWait.erase(w++); continue; }
        ++w;
    }
    /* 2b. P109 R1: A MARKED SECTOR THIS GAME NOW HOLDS PULLS ITS NEVER-RECEIVED BOXES from the previous holder, once per holding
       (cooppar::ParityPullSector): on the zone poll's cadence, over the marked sectors loaded here whose arrival is decided. The
       verdict is read now; once per LOAD of the sector (its departure re-arms it; a re-holding within the same load is left to
       the refusal pull - fold 1, F3). A furniture registry not ready leaves the sector un-pulled, so
       the next poll tries again. */
    if (polledNow != 0)
    {
        int refs = -1;
        for (int sct = 0; sct < 4096; ++sct)
        {
            if (g_parityWasNonHolder[sct] == 0 || g_parityZoneNow[sct] == 0 || g_parityPullSecDone[sct] != 0) continue;
            if (g_parityPending.count(sct) != 0) continue;   /* its arrival is still being decided */
            Sector cs; cs.x = sct / 64; cs.y = sct % 64;
            float cpos[3]; cpos[0] = 0; cpos[1] = 0; cpos[2] = 0;
            SectorCentrePointTS(cs, cpos);
            const int v = ItAreaVerdictAt(cpos, kAreaForBox);
            if (StoreAreaPictureVerdict() == kPicLoading) break;
            if (cooppar::ParityGaveUpClears(g_parityMarkGaveUp[sct], (v == kBoxMine) ? 1 : 0, OtherLoadedTS(cs)) != 0)
            {   /* fold 1 (F2, manager ruling): this game holds the sector ALONE (the notebook's fresh loaded map: no other game has
                   it loaded) - a gave-up mark does not outlive that. Fold 1b (ruling revised): the sector is only unmarked, never
                   made owned here - owned only by a later arrival's normal rule (cooppar::ParitySectorOwned) */
                g_parityWasNonHolder[sct] = 0; g_parityMarkGaveUp[sct] = 0; ++g_parityGaveUpCleared;
                continue;
            }
            if (cooppar::ParityPullSector(1, 1, g_parityPullSecDone[sct], (v == kBoxMine) ? 1 : 0) == 0) continue;
            if (refs < 0)
            {
                ItFurnEnsure();
                if (ItFurnValid() == 0) break;
                long long ps3 = 0, kl3 = 0;
                refs = ItParityBoxes(g_parityRefs, kParityRefCap, &ps3, &kl3, kPbAsk);
            }
            g_parityPullSecDone[sct] = 1; ++g_parityPullSectors;
            for (int r = 0; r < refs; ++r)
            {
                if (g_parityRefs[r].sx != cs.x || g_parityRefs[r].sy != cs.y) continue;
                const std::string k(g_parityRefs[r].key);
                if (ItParityNeverReceived(g_parityRefs[r].b, k) != 0) ItParityPullOne(k);
            }
        }
    }
    /* 3. asker: a deferred answer is asked for again. A box ON SCREEN is re-asked once the cursor is empty and its moves are
       out (parity3). P94 fold 1 (review F2): a CLOSED box is re-asked too instead of dropped - the holder set its safety-net
       baseline as if the answer arrived, so a dropped one left the copies apart until the next open - once its moves are
       out; the cursor does not hold it back (a cursor item cannot belong to a closed box). At most kParityClosedReaskTick
       closed boxes a drain and kParityClosedReaskCap re-asks a key (reset when its contents arrive, and at world teardown);
       past the cap the key is dropped as before (`deferDropped`). Both kinds share the 5 s per-box interval below. */
    if (!g_parityDeferKeys.empty())
    {
        const int cursorBusy = ItParityCursorBusy();
        int closedTick = 0;
        for (std::set<std::string>::iterator it = g_parityDeferKeys.begin(); it != g_parityDeferKeys.end(); )
        {
            void* b = ItBoxResolve(it->c_str());
            ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
            if (inv == 0) { g_parityDeferKeys.erase(it++); continue; }
            const int shown = ItParityShown(inv);   /* fold 3b: a counter counts as shown while its shop window is open */
            if (shown != 0 && cursorBusy != 0) { ++it; continue; }
            if (shown == 0)
            {
                std::map<std::string, int>::iterator cn = g_parityClosedReaskN.find(*it);
                if (cn != g_parityClosedReaskN.end() && cn->second >= kParityClosedReaskCap)
                { ++g_openDeferDropped; g_parityClosedReaskN.erase(cn); g_parityDeferKeys.erase(it++); continue; }
                if (closedTick >= kParityClosedReaskTick) { ++it; continue; }   /* the rest wait for the next drain */
            }
            if (ItBoxHasPendingMoves(b, it->c_str()) != 0) { ++it; continue; }
            /* recheck-loot2c (2): a box held back by a watched book that cannot move (no room anywhere) is re-asked at
               most once per 5 s while its window stays open - the view stays as it is (the book waits with its notice),
               the link is not flooded. */
            { std::map<std::string, DWORD>::iterator ra = g_parityReaskAt.find(*it); const DWORD nowRa = ::GetTickCount();
              if (ra != g_parityReaskAt.end() && (DWORD)(nowRa - ra->second) < 5000) { ++g_parityReaskLimited; ++it; continue; }
              g_parityReaskAt[*it] = nowRa; }
            ++g_parityReasked;
            if (shown == 0) { ++closedTick; ++g_parityClosedReaskN[*it]; ++g_parityClosedReasked; }   /* fold 1 (F2b) */
            ItParityAskOne(*it);
            g_parityDeferKeys.erase(it++);
        }
    }
}
void ItParityWorldTeardown()
{
    g_parityReaskAt.clear();   /* recheck-loot2c (2) */
    g_furnN = 0; g_furnBuiltAt = -1; g_furnDirty = 1; g_furnTriedGen = -1;
    g_parityPending.clear();
    std::memset(g_parityZoneNow, 0, sizeof(g_parityZoneNow));
    std::memset(g_arriveSwept, 0, sizeof(g_arriveSwept)); std::memset(g_arrivePolls, 0, sizeof(g_arrivePolls));   /* inv7d fold */
    g_parityServeQ.clear();
    g_grCatchQ.clear(); g_grCatchAskedAt.clear(); g_grCatchWait.clear();   /* they name the world that is going */
    std::memset(g_grSettleState, 0, sizeof(g_grSettleState)); std::memset(g_grSettleLast, 0, sizeof(g_grSettleLast));
    std::memset(g_grSettlePolls, 0, sizeof(g_grSettlePolls));
    g_parityDeferKeys.clear();
    g_parityRetryN.clear();
    g_parityApplyQ.clear();
    ItOwnKeyReset();   /* inv4b: the per-key owner records and hand-backs name the world that is going */
    g_parityPollNow = 1;
    g_fillDirty.clear();   /* par2: the dirty boxes name the world that is going */
    std::memset(g_parityWasNonHolder, 0, sizeof(g_parityWasNonHolder)); g_parityFilledHere.clear();   /* P94 / P109 */
    std::memset(g_parityOwnedHere, 0, sizeof(g_parityOwnedHere)); std::memset(g_parityPullSecDone, 0, sizeof(g_parityPullSecDone)); g_parityPull.clear();   /* P109 */
    std::memset(g_parityMarkGaveUp, 0, sizeof(g_parityMarkGaveUp)); g_parityGaveUpCleared = 0;   /* P109 fold 1 (F2) */
    g_snapRecvKeys.clear(); g_snapRecvOverflow = 0; g_parityClosedReaskN.clear();   /* P94 fold 1 (review F8): they name the world that is going */
    g_parityOpenAsked.clear(); g_parityOpened.clear(); g_openQN = 0;   /* parity3 */
    g_boxOpenState = 0; g_boxOpenKeys.clear(); g_boxOpenCur.clear(); g_boxOpenIdx = 0; g_boxOpenHaveTown = 0;
}
/* par2 (docs/design-loot2.md rev 2, 0.5): THE PUSH. MAIN THREAD, after this tick's ring drain and the pull answers, sharing
   their per-tick budgets. Nothing happens while any thread is still inside a fill (g_fillsActive): the dirty boxes wait for
   the end of the OUTERMOST fill. Then each dirty box is resolved and asked, LIVE, who holds it:
     mine    -> (P94 fold 1, review F3: not a box of a sector once had as the non-holder that this game never received nor
                restocked - `parityPushNeverReceived`, the answer's P109 test) if the peer has the sector loaded, one MSG_PARITY_BOX (status CONTENTS) with the box's whole contents, read
                now (`parityPushed`); a box with an unpublished ordinary move waits a drain (`pushHeldBack`). Peer not
                loaded: dropped - its first-sight ask covers it (`pushNoPeer`). Peer map stale: waits.
     held    -> a non-holder's own fill never counts: the holder is asked again through the PAR-1 ask (`fillAsked`), unless
                the sector's arrival ask is still to come and will carry the live digest anyway (`fillAskCovered`).
     loading -> waits, up to kParityVerdictTicks drains (`fillGaveUp`).
   Recurrence: a push that is lost, or a box that could not be read, is repaired by the next first-sight ask. */
long long g_parityPushed = 0, g_parityPushItems = 0, g_parityPushNoPeer = 0, g_parityPushHeldBack = 0, g_parityPushGone = 0,
          g_parityPushPlayer = 0, g_parityPushUnreadable = 0, g_parityPushWaitFill = 0, g_parityPushUnowned = 0,
          g_parityFillAsked = 0, g_parityFillAskCovered = 0, g_parityFillGaveUp = 0, g_parityPushPeerStale = 0,
          g_parityPushNeverReceived = 0;   /* P94 fold 1 (review F3) */
int g_parityPushLines = 0;
/* P94: a dirty box that ends WITHOUT a push (gone, gave up, not mine, never received (fold 1), peer not loaded, unreadable, send failed, or a non-holder's
   fill asked of the holder) forgets its inv2a baseline, as the drop did under parity3 - the safety net must not publish the
   fill as moves; its next visit takes a fresh baseline and the peer's next arrival or open ask repairs its copy. */
void ItFillDirtyForget(std::map<std::string, ItFillDirty>::iterator at)
{
    InvNetForget(0, at->first);
    g_fillDirty.erase(at);
}
void ItParityFillPush(int* answered, long long* itemsSent)
{
    if (g_fillDirty.empty()) return;
    if (::InterlockedCompareExchange(&g_fillsActive, 0, 0) != 0) { ++g_parityPushWaitFill; return; }
    for (std::map<std::string, ItFillDirty>::iterator it = g_fillDirty.begin(); it != g_fillDirty.end(); )
    {
        const std::string key = it->first;
        void* b = ItBoxResolve(key.c_str());
        ::Inventory* inv = (b != 0) ? ItBoxInventory(b) : 0;
        float pos[3]; pos[0] = 0; pos[1] = 0; pos[2] = 0;
        if (inv == 0 || ItBoxPosPod(b, pos) == 0) { ++g_parityPushGone; ItFillDirtyForget(it++); continue; }
        const int v = ItBoxWriterAt(b, pos, key.c_str());   /* inv4 site 7: my own box pushes, another player's asks its owner */
        if (StoreAreaPictureVerdict() == kPicLoading || v == kBoxNoAnswer)
        {
            if (++it->second.ticks > kParityVerdictTicks) { ++g_parityFillGaveUp; ItFillDirtyForget(it++); } else ++it;
            continue;
        }
        if (v == kBoxHeld)
        {
            ItBoxKeyParts kp;
            int sec = -1;
            if (ItBoxKeyParse(key.c_str(), &kp) != 0 && kp.sx >= 0 && kp.sx < 64 && kp.sy >= 0 && kp.sy < 64) sec = kp.sx * 64 + kp.sy;
            /* review-parity2 2d: ALWAYS asked. A pending arrival ask for the sector may still end "not held" or give up, and
               the box's re-ask would be lost with it; a duplicate ask only comes back "equal". pendingToo is informational. */
            if (sec >= 0 && g_parityPending.count(sec) != 0) ++g_parityFillAskCovered;
            ++g_parityFillAsked; ItParityAskOne(key);
            ItFillDirtyForget(it++);
            continue;
        }
        if (v != kBoxMine) { ++g_parityPushUnowned; ItFillDirtyForget(it++); continue; }
        /* P94 / P109: this game stocked the box while holding it. P94 fold 1 (review F3): only a RESTOCK counts - a move rung
           inside refreshInventory's restock depth (ItRestockAsFill: the timer's restock and a squad's first stocking through
           refreshInventory, with the building fill nested in it), which replaces the stock whole. The building fill alone
           (refreshBuildingInventory, kFillBuilding), the town's artifact deal (distributeArtifacts, kFillArtifacts) and the
           `itemtest mark` lever add to contents this game may never have received, so they do not make the box trusted. */
        if (it->second.restock != 0)
        {
            if (g_parityFilledHere.size() < kSnapRecvCap || g_parityFilledHere.count(key) != 0) g_parityFilledHere.insert(key);
            else ++g_parityFilledHereOverflow;
        }
        /* fold 1 (F3): the push of a box this game never received is refused as its answer would be (P109) */
        if (ItParityNeverReceived(b, key) != 0) { ++g_parityPushNeverReceived; ItParityNeverRecvSay(key, 1); ItFillDirtyForget(it++); continue; }
        const Sector sct = SectorOf(pos[0], pos[2]);
        const int peer = PeerSectorLoadedTS(sct);
        if (peer == 0) { ++g_parityPushNoPeer; ItFillDirtyForget(it++); continue; }
        if (peer < 0)
        {
            ++g_parityPushPeerStale;
            if (++it->second.ticks > kParityVerdictTicks) { ++g_parityFillGaveUp; ItFillDirtyForget(it++); } else ++it;
            continue;
        }
        if (*answered >= kParityServeBudget || *itemsSent >= kParityServeItemBudget) break;   /* the rest go next drain */
        if (ItBoxHasPendingMoves(b, key.c_str()) != 0) { ++g_parityPushHeldBack; ++it; continue; }
        if (ItLootBeforePublishRead(key, kLootWhyPush) < 0) { ++g_parityPushHeldBack; ++it; continue; }   /* loot2c fold (review 2g): copies out before the contents are read for a push */
        cooppar::ParityBox a;
        a.key = key; a.status = cooppar::kParityStatusContents;
        if (ItParityContents(inv, &a.items) == 0) { ++g_parityPushUnreadable; ItFillDirtyForget(it++); continue; }
        a.digest = cooppar::ParityDigestOf(a.items);
        std::vector<char> bytes;
        if (!cooppar::EncodeParityBox(&bytes, a)) { ++g_paritySendFailed; ItFillDirtyForget(it++); continue; }
        if (net::SendParityPush(bytes, sct.x, sct.y))   /* M7b slice 2: to every game covering the box's sector */
        {
            g_parityBytes += (long long)bytes.size();
            g_markRowCarried += (long long)cooppar::ParityMarkedCount(a.items);   /* inv6 phase 2: the box publish */
            g_markSenderUnknown += (long long)cooppar::ParityUnknownCount(a.items);   /* review-inv6p2 LOW: unknown-owner rows (publish) */
            ++g_parityPushed; g_parityPushItems += (long long)a.items.size();
            InvNetSnapshotBox(key, inv);   /* inv2a: the other game now holds these contents */
            if (g_parityPushLines < 400)
            {
                ++g_parityPushLines;
                char hex[16]; std::sprintf(hex, "%08x", a.digest);
                DebugLog("[PARITY] push key=" + key + " items=" + N((long long)a.items.size()) + " digest=" + std::string(hex)
                         + " sector=" + N((long long)sct.x) + "," + N((long long)sct.y) + " - the box's whole contents after a fill");
            }
        }
        else { ++g_paritySendFailed; InvNetForget(0, key); }   /* P94: as every other exit without a push */
        ++*answered; *itemsSent += (long long)a.items.size();
        g_fillDirty.erase(it++);
    }
}
/* MAIN THREAD, AFTER this tick's ring drain (review-par1 4a): the asker's queued swaps within the budget, then the holder's
   answers - at most kParityServeBudget boxes or kParityServeItemBudget items; a box with a move not yet published waits. */
void ItParityAfterDrain()
{
    if (g_base == 0 || StoreTearingDown() != 0 || EngineWritesBlocked()) return;
    while (!g_parityApplyQ.empty())
    {
        if (g_parityApplyQ.front().stale != 0)
        {
            const std::string key = g_parityApplyQ.front().a.key;
            g_parityApplyQ.pop_front();
            ++g_parityStaleReasked;
            ItParityAskOne(key);
            continue;
        }
        if (ItParityBudgetLeft(g_parityApplyQ.front().a) == 0) break;
        const cooppar::ParityBox a = g_parityApplyQ.front().a;
        g_parityApplyQ.pop_front();
        ItParityApply(a);
    }
    /* the ground listings asked of us (GrCatchUpServe), kGrCatchPerTick answered per drain. A listing for a sector whose ground is
       not settled here waits at the back of the queue (a walk before the zone's saved items are placed would send GONE for items
       still coming); past kParityVerdictTicks drains, or once the sector is not active here, it is answered with ADDs only */
    {
        int served = 0;
        const size_t qn = g_grCatchQ.size();
        for (size_t c = 0; c < qn && served < kGrCatchPerTick && !g_grCatchQ.empty(); ++c)
        {
            ItGrCatchAsk q;
            q.sx = g_grCatchQ.front().sx; q.sy = g_grCatchQ.front().sy; q.asker = g_grCatchQ.front().asker; q.ticks = g_grCatchQ.front().ticks;
            q.keys.swap(g_grCatchQ.front().keys);
            q.left = g_grCatchQ.front().left;
            g_grCatchQ.pop_front();
            const int sct = (q.sx >= 0 && q.sx < 64 && q.sy >= 0 && q.sy < 64) ? q.sx * 64 + q.sy : -1;
            int allowGone = 1;
            if (sct >= 0 && g_grSettleState[sct] != 2)
            {
                if (q.ticks == 0) ++g_grSettleServeWaited;
                if (++q.ticks <= kParityVerdictTicks && g_parityZoneNow[sct] != 0) { g_grCatchQ.push_back(q); continue; }
                allowGone = 0;
            }
            ++served;
            GrCatchUpServe(q.sx, q.sy, q.keys, q.left, q.asker, allowGone);
        }
    }
    const size_t start = g_parityServeQ.size();
    int answered = 0;
    long long itemsSent = 0;
    for (size_t s = 0; s < start && answered < kParityServeBudget && itemsSent < kParityServeItemBudget; ++s)
    {
        const ItParityAsk q = g_parityServeQ.front();
        g_parityServeQ.pop_front();
        const long long sent = ItParityServe(q.row, q.asker);   /* M7b slice 2: answered back to the game that asked */
        if (sent < 0) { g_parityServeQ.push_back(q); ++g_parityServeHeldBack; continue; }
        ++answered; itemsSent += sent;
    }
    if (kParityFillPushes != 0) ItParityFillPush(&answered, &itemsSent);   /* par2 / P94 (owner 219): the dirty boxes of finished fills, inside the same budget */
    else if (!g_fillDirty.empty() && ::InterlockedCompareExchange(&g_fillsActive, 0, 0) == 0)   /* the push switched off (0) only */
    {
        g_fillDirtyDropped += (long long)g_fillDirty.size();
        /* inv2a: a dropped fill is left for the next open ask - the safety net must not publish it as moves */
        for (std::map<std::string, ItFillDirty>::const_iterator fd = g_fillDirty.begin(); fd != g_fillDirty.end(); ++fd) InvNetForget(0, fd->first);
        g_fillDirty.clear();
    }
}
/* ======================= inv2a (user decision 2026-09-26): THE INVENTORY SAFETY NET =======================
   WHY. The mod publishes an inventory change only when a hooked engine function sees it. inv1-inventory-change-audit.md found
   engine routes that write straight into an item: Inventory::takeOneItemOnly 0x749FF0 lowers the SOURCE stack (eat task, medic
   stocking, hauling), research consume 0x82DA30 writes Item+0x12C, kit charges and food bites are raw +0x118 writes. The other
   game never hears of them.
   WHAT. Each game, only for what it is the authority of - its OWN player-faction characters (every section of the character's
   inventory, NOT a worn backpack's contents: effort inv3) and the loaded boxes whose area it HOLDS (the parity serve's holder
   test) - keeps the LAST-ANNOUNCED contents (the baseline, src/common/invnet.h) and compares the live contents with it on a
   rotating budget. A difference goes out as the ordinary ITEM_MOVE (op 0 add / op 1 remove / op 2 absolute quantity) exactly
   as the authority sends a normal change; a charges change on an item that stays put has no wire form and is counted
   `uncarried` (effort inv2b decides).
   THE BASELINE FOLLOWS THE WIRE: every ITEM_MOVE this file publishes goes through ItNetSendMove, which applies the same op to
   the baseline the receiver applies to its copy - so an already-sent change is never caught twice. It is SET (snapshot) when
   the other game is handed the whole inventory: a character's CLOTHING snapshot at spawn-settle (appearance.cpp), a box's
   parity answer (ItParityServe equal/contents) or push; and on the first visit. It is FORGOTTEN when this game stops being the
   authority (a visit finds the character not ours / the box not held, or the other game sends a move for it), when a
   restock's folded fill ends without a push (ItFillDirtyForget, P94), on link-down and at world teardown.
   BUDGET, main thread, after the drain and the parity answers: own characters - one per step, a full cycle every ~5 s
   (kInvNetCharCycleMs; never closer than 20 ms); boxes - a step every 250 ms of ceil(n/100) boxes (at most 16), from a list of
   the loaded non-player boxes rebuilt once per ~25 s cycle (kInvNetBoxCycleMs) from the parity walk; the holder test is
   asked per visit. Registries only - no per-tick sweep.
   LOOP SAFETY: an inventory with a move not yet published (ring entry, split, held remove, owner- or requester-side pending
   request, a queued parity answer or open ask, a pending research lift, a fill not yet pushed) is skipped (skippedPending);
   one whose window is open while something is on the cursor is skipped (skippedOpen); one holding a loot2c copy or a
   watched book is skipped (skippedLoot). Every catch is logged ([INVNET] catch), rate-limited per (inventory, item) with the
   repeats counted, and `report` prints [INVNET] REPORT. */
const unsigned int kInvNetCharCycleMs = 5000;
const unsigned int kInvNetCharMinGapMs = 20;
const unsigned int kInvNetBoxCycleMs = 25000;
const unsigned int kInvNetBoxSlotMs = 250;
const int kInvNetBoxSlotsPerCycle = 100;
const int kInvNetBoxPerSlotMax = 16;
const unsigned int kInvNetLogGapMs = 30000;
const size_t kInvNetMapCap = 4096;
struct InvNetHookSeen { int op; unsigned int at; };
struct InvNetLogSeen { unsigned int at; long long suppressed; };
struct InvNetCharRef { ::Character* ch; unsigned int uid; };
struct InvNetBoxRef { void* b; std::string key; };
static std::map<std::string, std::vector<coopinv::Slot> > g_invNetBase;   /* "c<uid>" / "b<box key>" -> the last-announced contents */
static std::map<std::string, InvNetHookSeen> g_invNetHook;               /* the last watched-hook event per inventory (the drain) */
static std::map<std::string, InvNetLogSeen> g_invNetLog;                 /* the catch-line rate limit per (inventory, item) */
static std::map<std::string, long long> g_invNetBySid;
static std::vector<InvNetCharRef> g_invNetChars;
static std::vector<InvNetBoxRef> g_invNetBoxes;
static size_t g_invNetCharIdx = 0, g_invNetBoxIdx = 0;
static unsigned int g_invNetCharAt = 0, g_invNetCharGap = 0, g_invNetBoxAt = 0, g_invNetBoxListAt = 0;
static int g_invNetBoxListEver = 0;
static long long g_invNetPasses = 0, g_invNetChecked = 0, g_invNetCatches = 0, g_invNetUncarried = 0, g_invNetSendFailed = 0,
                 g_invNetSkippedOpen = 0, g_invNetSkippedPending = 0, g_invNetSkippedLoot = 0, g_invNetUnreadable = 0,
                 g_invNetNotHeld = 0, g_invNetSnapFirst = 0, g_invNetSnapAnnounce = 0, g_invNetSnapServe = 0, g_invNetFollowed = 0,
                 g_invNetFollowMiss = 0, g_invNetForgotten = 0, g_invNetSuppressed = 0, g_invNetLogged = 0, g_invNetCharCycles = 0,
                 g_invNetBoxCycles = 0, g_invNetClears = 0, g_invNetSent = 0;
static double g_invNetMsMax = 0.0, g_invNetMsSum = 0.0;

std::string InvNetKey(unsigned int uid, const std::string& boxKey)
{
    return (uid != 0) ? ("c" + N((long long)uid)) : ("b" + boxKey);
}
/* THE ONE ITEM_MOVE SENDER of this file: the send, then the baseline follows what went out. */
bool ItNetSendMove(const ItemMoveMsg& mIn)
{
    /* bag23 part 2: an op-0 ADD whose pack rows no one asked for gets them here (ItOp0BagRowsLate) */
    ItemMoveMsg late;
    const ItemMoveMsg* mp = &mIn;
    if (mIn.op == 0 && mIn.bagChecked == 0 && mIn.bag.empty() && mIn.bagPath.has == 0)
    {
        late = mIn;
        late.bagChecked = 1;
        if (ItOp0BagRowsLate(&late) != 0) mp = &late;
    }
    const ItemMoveMsg& m = *mp;
    const bool ok = net::SendItemMove(m);
    /* P109 fold 1 (F1): a box move this game SENT while its pull for that box is out ends the pull - the other game's answer may
       have been read before this move reached it, so swapping it in would undo the move (a take duplicated, a put lost). The
       late answer is then refused (ItParityApply: not this game's pull - ours stands); the box stays never-received, so the
       next ask is refused and R4 pulls again once the other game has the move. */
    if (ok && m.uid == 0 && !m.boxKey.empty() && g_parityPull.erase(m.boxKey) != 0) ++g_parityPullRefused;
    if (ok && m.bagPath.has != 0) ++g_bagSent;   /* bag23 part 2 */
    /* bag23 part 2: the net's baseline is the TOP level; a move inside a pack is not one of its rows (phase 4 nets packs). */
    if (ok && !g_invNetBase.empty() && m.bagPath.has == 0)
    {
        std::map<std::string, std::vector<coopinv::Slot> >::iterator bi = g_invNetBase.find(InvNetKey(m.uid, m.boxKey));
        if (bi != g_invNetBase.end())
        {
            if (coopinv::ApplyOp(&bi->second, m.op, m.section, m.x, m.y, m.baseSid, m.quantity, m.charges) != 0) ++g_invNetFollowed;
            else ++g_invNetFollowMiss;
        }
    }
    return ok;
}
/* the drain, pass 1: one ring entry's inventory and op - the `lastHook` of a later catch */
void InvNetNoteHook(unsigned int uid, const char* boxKey, int op)
{
    if (uid == 0 && (boxKey == 0 || boxKey[0] == 0)) return;
    if (g_invNetHook.size() >= kInvNetMapCap) g_invNetHook.clear();
    InvNetHookSeen& h = g_invNetHook[InvNetKey(uid, (uid != 0) ? std::string() : std::string(boxKey))];
    h.op = op; h.at = ::GetTickCount();
}
void InvNetForget(unsigned int uid, const std::string& boxKey)
{
    if (g_invNetBase.empty()) return;
    if (g_invNetBase.erase(InvNetKey(uid, boxKey)) != 0) ++g_invNetForgotten;
}
void InvNetClearAll()
{
    if (!g_invNetBase.empty() || !g_invNetChars.empty() || !g_invNetBoxes.empty()) ++g_invNetClears;
    g_invNetBase.clear(); g_invNetHook.clear(); g_invNetLog.clear();
    g_invNetChars.clear(); g_invNetBoxes.clear();
    g_invNetCharIdx = 0; g_invNetBoxIdx = 0; g_invNetBoxListEver = 0;
}
/* is `item` a watched loot2c book (not yet settled)? pointer compares only */
int InvNetWatched(void* item)
{
    for (int i = 0; i < kLootWatchCap; ++i)
        if (g_lootWatch[i].used != 0 && g_lootWatch[i].item == item) return 1;
    return 0;
}
/* THE LIVE CONTENTS, every section. 1 read; 0 unreadable; -1 a loot2c copy or a watched book is in it (skip the inventory). */
int InvNetRead(::Inventory* inv, std::vector<coopinv::Slot>* out)
{
    out->clear();
    if (!ItObj(inv)) return 0;
    const ItSecMap& secs = *(const ItSecMap*)((char*)inv + 0x28);
    if (secs.size() > 64) return 0;
    const int copies = ItLootRegCount(), watched = ItLootWatchCount();
    for (ItSecMap::const_iterator it = secs.begin(); it != secs.end(); ++it)
    {
        ::InventorySection* sec = it->second;
        if (!ItObj(sec)) continue;
        char secName[kSecCap]; secName[0] = 0;
        if (ItStrPod(&it->first, secName, kSecCap) == 0) return 0;
        const Ogre::vector< ::InventorySection::SectionItem>::type& si = sec->items;
        if (si.size() > 4096) return 0;
        for (size_t k = 0; k < si.size(); ++k)
        {
            void* item = (void*)si[k].item;
            if (!ItPlaus(item)) return 0;
            if (copies != 0 && ItLootFindAny(item) >= 0) return -1;
            if (watched != 0 && InvNetWatched(item) != 0) return -1;
            char base[kSidCap];
            void* gd = 0;
            int q = 0;
            float ch = 0.0f;
            if (ItPtrPod(item, kObjData, &gd) == 0 || !ItPlaus(gd) || ItStrPodWhy((const char*)gd + kGdStringId, base, kSidCap) != 1
                || ItIntPod(item, kItemQuantity, &q) == 0 || ItFloatPod(item, kItemCharges, &ch) == 0) return 0;
            if (out->size() >= 4096) return 0;
            coopinv::Slot sl;
            sl.section = secName; sl.x = (int)si[k].x; sl.y = (int)si[k].y; sl.sid = base; sl.qty = q; sl.charges = ch;
            out->push_back(sl);
        }
    }
    return 1;
}
void InvNetSnapshotBox(const std::string& key, ::Inventory* inv)
{
    if (key.empty() || inv == 0) return;
    static std::vector<coopinv::Slot> cur;
    const std::string k = InvNetKey(0, key);
    if (InvNetRead(inv, &cur) == 1) { g_invNetBase[k] = cur; ++g_invNetSnapServe; }
    else if (g_invNetBase.erase(k) != 0) ++g_invNetForgotten;
}
/* appearance.cpp, right after an owned character's CLOTHING snapshot went out: the other game now holds the whole inventory */
void InvNetNoteAnnounced(void* ch, unsigned int uid)
{
    if (g_base == 0 || uid == 0 || StoreTearingDown() != 0 || StorePlayerReachable(-1) == 0) return;   /* InvNetTick's own gate */
    ::Faction* mineF = LocalPlayerFaction();
    void* f = 0;
    if (mineF == 0 || !ItObj(ch) || ItFactionPod(ch, &f) == 0 || f != (void*)mineF) return;
    ::Inventory* inv = ItInventoryOf((::Character*)ch);
    if (inv == 0) return;
    static std::vector<coopinv::Slot> cur;
    const std::string k = InvNetKey(uid, std::string());
    if (InvNetRead(inv, &cur) == 1) { g_invNetBase[k] = cur; ++g_invNetSnapAnnounce; }
    else if (g_invNetBase.erase(k) != 0) ++g_invNetForgotten;
}
/* DOES THIS CHARACTER HAVE A MOVE NOT YET PUBLISHED, OR A REQUEST IN FLIGHT? (ItBoxHasPendingMoves's character twin) */
int InvNetCharPending(void* ch, unsigned int uid)
{
    /* bag23 fold (review R4) char: an undrained pack move (kKindBag) is pending for every character too - ItBoxHasPendingMoves */
    for (int i = 0; i < kRing; ++i)
        if (::InterlockedCompareExchange(&g_ring[i].ready, 0, 0) != 0
            && (g_ring[i].kind == kKindBag || (g_ring[i].kind == kKindChar && g_ring[i].ch == ch))) return 1;
    if (::InterlockedCompareExchange(&g_itSplit.ready, 0, 0) != 0
        && (g_itSplit.re.kind == kKindBag || (g_itSplit.re.kind == kKindChar && g_itSplit.re.ch == ch))) return 1;
    if (g_splitPend.used != 0 && (g_splitPend.re.ch == ch || g_splitPend.uid == uid)) return 1;
    if (g_heldPend.used != 0 && (g_heldPend.re.ch == ch || g_heldPend.uid == uid)) return 1;
    for (int q = 0; q < kOwnerPendCap; ++q)
        if (g_ownerPend[q].used != 0 && g_ownerPend[q].isBox == 0 && g_ownerPend[q].uid == uid) return 1;
    for (int p = 0; p < kPendCap; ++p)
        if (g_pend[p].used != 0 && g_pend[p].mineUid == uid) return 1;
    return 0;
}
/* T-1 B2 fold (review F2): MAY A PENDING KIT BE APPLIED TO THIS COPY NOW? The kit apply (appearance.cpp ApplyPendingGarments ->
   ApplyGarments) runs clearAll on the copy - every item it and its packs hold is destroyed and rebuilt - and since T-1 B2 the
   writer's wandering restock resends a LIVE pack wearer's kit, so it can land mid-life. Not while something on this game still
   holds one of those items by pointer. MAIN THREAD (AppearanceTick). 0 = clear;
   1 = an inventory window shows the character or one of its packs - ItParityShown: the Inventory's own window pointer
       round-tripped through InventoryGUI::getInventory (ItParityWindowOpen), or the open trade window's stand-in built over it
       (ItOpenShopFacadeFor - a wandering trader's trade window is a facade whose sections are its packs);
   2 = an item from it is on the cursor - the cursor holds something (ItHeldLive) and it is this file's held remove / held split
       of this character or uid (g_heldPend / g_splitPend, kept exactly as long as the cursor names the object), or an undrained
       ring move out of the character or one of its packs;
   3 = a request against it awaits an answer - one this game sent with it as the other half (g_pend ghostUid) or granted on it
       (g_ownerPend uid). */
int KitApplyBusy(void* ch, unsigned int uid)
{
    ::Character* c = (::Character*)ch;
    if (g_base == 0 || c == 0 || !ItObj(c)) return 0;
    ::Inventory* inv = ItInventoryOf(c);
    std::vector<void*> packs; std::vector<std::string> where;
    if (inv != 0)
    {
        if (ItParityShown(inv) != 0) return 1;
        TlPacksOf(inv, &packs, &where);
        for (size_t q = 0; q < packs.size(); ++q)
        {
            void* bi = 0;
            if (ItBagInvPod(packs[q], &bi) != 0 && bi != 0 && ItParityShown((::Inventory*)bi) != 0) return 1;
        }
    }
    if (ItHeldLive() != 0)
    {
        if (g_heldPend.used != 0 && (g_heldPend.re.ch == ch || g_heldPend.uid == uid)) return 2;
        if (g_splitPend.used != 0 && (g_splitPend.re.ch == ch || g_splitPend.uid == uid)) return 2;
        for (int i = 0; i < kRing; ++i)
        {
            if (::InterlockedCompareExchange(&g_ring[i].ready, 0, 0) == 0) continue;
            if (g_ring[i].kind == kKindChar && g_ring[i].ch == ch) return 2;
            if (g_ring[i].kind == kKindBag)
                for (size_t q = 0; q < packs.size(); ++q) if (g_ring[i].bag == packs[q]) return 2;
        }
    }
    if (uid != 0)
    {
        for (int p = 0; p < kPendCap; ++p)
            if (g_pend[p].used != 0 && g_pend[p].ghostIsBox == 0 && g_pend[p].ghostUid == uid) return 3;
        for (int q = 0; q < kOwnerPendCap; ++q)
            if (g_ownerPend[q].used != 0 && g_ownerPend[q].isBox == 0 && g_ownerPend[q].uid == uid) return 3;
    }
    return 0;
}
/* one caught difference out as the ordinary op. 1 sent; 0 not (the add's item would not read, or the send failed) */
int InvNetSendOp(::Inventory* inv, unsigned int uid, const std::string& boxKey, const coopinv::Op& o)
{
    ItemMoveMsg m;
    m.uid = uid;
    if (uid == 0) m.boxKey = boxKey;
    m.section = o.section; m.x = o.x; m.y = o.y;
    if (o.kind == coopinv::kOpAdd)
    {
        ::InventorySection* sec = inv->getSection(o.section);
        if (!ItObj(sec)) return 0;
        void* item = ItItemAtPod(sec, o.x, o.y);
        static ItEntry e;
        ItClear(&e);
        if (item == 0 || ItReadFields(item, &e) != 1) return 0;
        ItMsgFromEntry(e, &m);
        m.op = 0; m.quantity = (o.qtyTo > 0) ? o.qtyTo : 1;
    }
    else if (o.kind == coopinv::kOpRemove) { m.op = 1; m.quantity = o.qtyFrom; }
    else if (o.kind == coopinv::kOpQty) { m.op = 2; m.quantity = o.qtyTo; }
    else if (o.kind == coopinv::kOpCharges) { m.op = 4; m.quantity = o.qtyTo; m.charges = o.chTo; m.baseSid = o.sid; }   /* items9 */
    else return 0;
    if (!ItNetSendMove(m)) return 0;
    ++g_invNetSent; ++g_sent;
    return 1;
}
std::string InvNetCharges(float c)
{
    char b[48];
    std::sprintf(b, "%.2f", (double)c);
    return std::string(b);
}
/* compare one inventory with its baseline; a first visit only takes the baseline */
void InvNetVisit(::Inventory* inv, unsigned int uid, const std::string& boxKey)
{
    const std::string key = InvNetKey(uid, boxKey);
    static std::vector<coopinv::Slot> cur;
    const int r = InvNetRead(inv, &cur);
    if (r < 0) { ++g_invNetSkippedLoot; return; }
    if (r == 0) { ++g_invNetUnreadable; return; }
    ++g_invNetChecked;
    std::map<std::string, std::vector<coopinv::Slot> >::iterator bi = g_invNetBase.find(key);
    if (bi == g_invNetBase.end()) { g_invNetBase[key] = cur; ++g_invNetSnapFirst; return; }
    static std::vector<coopinv::Op> ops;
    coopinv::Diff(bi->second, cur, &ops);
    if (ops.empty()) return;
    const unsigned int now = ::GetTickCount();
    std::string lastHook = "none";
    {
        std::map<std::string, InvNetHookSeen>::const_iterator h = g_invNetHook.find(key);
        if (h != g_invNetHook.end())
        {
            static const char* const kHookName[4] = { "add", "remove", "merge", "split" };
            lastHook = std::string((h->second.op >= 0 && h->second.op <= 3) ? kHookName[h->second.op] : "op?")
                     + "/" + N((long long)(unsigned int)(now - h->second.at)) + "msAgo";
        }
    }
    for (size_t i = 0; i < ops.size(); ++i)
    {
        const coopinv::Op& o = ops[i];
        ++g_invNetCatches;
        if (g_invNetBySid.size() < kInvNetMapCap || g_invNetBySid.count(o.sid) != 0) ++g_invNetBySid[o.sid];
        std::string sent;
        const int showCharges = (o.kind == coopinv::kOpCharges || o.chargesChanged != 0) ? 1 : 0;
        /* items9 (protocol 78): a charges change (a medkit used, food bitten - drainMedkit / eatItem's raw +0x118 writes) now goes out
           as ITEM_MOVE op 4; a quantity change that also changed the uses sends op 4 right after its op 2. */
        if (InvNetSendOp(inv, uid, boxKey, o) != 0)
        {
            sent = "op" + N((long long)o.kind);
            if (o.kind == coopinv::kOpCharges) ++g_invNetChargesSent;
            if (o.chargesChanged != 0)
            {
                coopinv::Op co = o; co.kind = coopinv::kOpCharges;
                if (InvNetSendOp(inv, uid, boxKey, co) != 0) { ++g_invNetChargesSent; sent += "+op4"; }
                else { ++g_invNetUncarried; sent += "+chargesUncarried"; }
            }
            coopinv::ApplyCatch(&bi->second, o);
        }
        else { ++g_invNetSendFailed; sent = "failed"; }
        const std::string lk = key + "|" + o.sid;
        if (g_invNetLog.size() >= kInvNetMapCap && g_invNetLog.count(lk) == 0) g_invNetLog.clear();
        std::map<std::string, InvNetLogSeen>::iterator lg = g_invNetLog.find(lk);
        if (lg != g_invNetLog.end() && (unsigned int)(now - lg->second.at) < kInvNetLogGapMs)
        { ++lg->second.suppressed; ++g_invNetSuppressed; continue; }
        long long before = 0;
        if (lg == g_invNetLog.end()) { InvNetLogSeen z; z.at = now; z.suppressed = 0; g_invNetLog[lk] = z; }
        else { before = lg->second.suppressed; lg->second.at = now; lg->second.suppressed = 0; }
        ++g_invNetLogged;
        DebugLog("[INVNET] catch inv=" + ((uid != 0) ? N((long long)uid) : boxKey) + " own=" + std::string(uid != 0 ? "char" : "box")
                 + " item=" + o.sid + " slot=" + o.section + ":" + N((long long)o.x) + "," + N((long long)o.y)
                 + " qty=" + N((long long)o.qtyFrom) + "->" + N((long long)o.qtyTo)
                 + (showCharges != 0 ? " charges=" + InvNetCharges(o.chFrom) + "->" + InvNetCharges(o.chTo) : std::string())
                 + " lastHook=" + lastHook + " sent=" + sent
                 + (before > 0 ? " repeatsSuppressedBefore=" + N(before) : std::string()));
    }
}
void InvNetCharsRebuild()
{
    g_invNetChars.clear();
    ::Faction* mineF = LocalPlayerFaction();
    if (!ItPlaus(coop::GameWorldPtr()) || mineF == 0) return;
    const GameHashSet< ::Character*>::type& all = coop::GameWorldPtr()->activeCharacters();
    if (all.size() > 20000) return;
    for (GameHashSet< ::Character*>::type::const_iterator it = all.begin(); it != all.end(); ++it)
    {
        ::Character* ch = *it;
        if (!ItObj(ch)) continue;
        void* f = 0;
        if (ItFactionPod(ch, &f) == 0 || f != (void*)mineF) continue;
        const unsigned int u = FindSpawnedUid(ch);
        if (u == 0 || !net::IsUidMine(u)) continue;
        InvNetCharRef r; r.ch = ch; r.uid = u;
        g_invNetChars.push_back(r);
    }
}
int InvNetCharStep(unsigned int now)
{
    if (g_invNetCharGap != 0 && (unsigned int)(now - g_invNetCharAt) < g_invNetCharGap) return 0;
    g_invNetCharAt = now;
    if (g_invNetCharIdx >= g_invNetChars.size())
    {
        if (!g_invNetChars.empty()) ++g_invNetCharCycles;
        InvNetCharsRebuild();
        g_invNetCharIdx = 0;
        const size_t n = g_invNetChars.size();
        g_invNetCharGap = (n == 0) ? kInvNetCharCycleMs : (unsigned int)(kInvNetCharCycleMs / (unsigned int)n);
        if (g_invNetCharGap < kInvNetCharMinGapMs) g_invNetCharGap = kInvNetCharMinGapMs;
        if (n == 0) return 0;
    }
    const InvNetCharRef r = g_invNetChars[g_invNetCharIdx++];
    if (FindSpawnedUid(r.ch) != r.uid || !net::IsUidMine(r.uid) || LiveCharacter((::Character*)r.ch) == 0)   /* the list is kept across frames: the engine must still know it */
    { if (g_invNetBase.erase(InvNetKey(r.uid, std::string())) != 0) ++g_invNetNotHeld; return 0; }
    ::Inventory* inv = ItInventoryOf(r.ch);
    if (inv == 0) { ++g_invNetUnreadable; return 0; }
    if (InvNetCharPending(r.ch, r.uid) != 0) { ++g_invNetSkippedPending; return 0; }
    if (ItParityCursorBusy() != 0 && ItParityShown(inv) != 0) { ++g_invNetSkippedOpen; return 0; }
    InvNetVisit(inv, r.uid, std::string());
    return 1;
}
int InvNetBoxOne(const InvNetBoxRef& r)
{
    /* review-inv2a (stall): NOT ItBoxResolve - its 16-row cache misses on almost every net visit and each miss is a full
       walk of every active zone. The pointer is checked against the once-per-drain liveness walk (or the furniture
       registry), then its key is rebuilt so a reused address cannot stand in for another box. */
    void* b = r.b;
    bool live = false;
    { const int wn = ItBoxWalkForLiveness(); for (int w = 0; w < wn; ++w) if (g_boxWalkList[w] == b) { live = true; break; } }
    if (!live && b != 0 && ItFurnLive(b) != 0) live = true;
    if (live)
    {
        char hk[kBoxKeyCap];
        if (ItBoxKeyBuild(b, hk, kBoxKeyCap, 0, 0) == 0 || r.key != hk) live = false;
    }
    if (!live) { if (g_invNetBase.erase(InvNetKey(0, r.key)) != 0) ++g_invNetForgotten; return 0; }
    float pos[3]; pos[0] = 0; pos[1] = 0; pos[2] = 0;
    if (ItBoxPosPod(b, pos) == 0 || ItBoxWriterAt(b, pos, r.key.c_str()) != kBoxMine)   /* inv4 site 8: only the writer nets a box */
    { if (g_invNetBase.erase(InvNetKey(0, r.key)) != 0) ++g_invNetNotHeld; return 0; }
    ::Inventory* inv = ItBoxInventory(b);
    if (inv == 0) { ++g_invNetUnreadable; return 0; }
    if (ItBoxHasPendingMoves(b, r.key.c_str()) != 0 || ItParityKeyBusy(r.key) != 0 || ItResearchPendingFor(r.key) != 0
        || g_fillDirty.count(r.key) != 0)
    { ++g_invNetSkippedPending; return 0; }
    if (ItParityCursorBusy() != 0 && ItParityShown(inv) != 0) { ++g_invNetSkippedOpen; return 0; }
    InvNetVisit(inv, 0, r.key);
    return 1;
}
int InvNetBoxStep(unsigned int now)
{
    if ((unsigned int)(now - g_invNetBoxAt) < kInvNetBoxSlotMs) return 0;
    g_invNetBoxAt = now;
    if (g_invNetBoxIdx >= g_invNetBoxes.size())
    {
        const unsigned int wait = g_invNetBoxes.empty() ? kInvNetCharCycleMs : kInvNetBoxCycleMs;
        if (g_invNetBoxListEver != 0 && (unsigned int)(now - g_invNetBoxListAt) < wait) return 0;
        if (!g_invNetBoxes.empty()) ++g_invNetBoxCycles;
        g_invNetBoxes.clear();
        long long ps = 0, kl = 0;
        const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl, kPbAll);   /* inv4: every box; InvNetBoxOne asks the writer */
        for (int i = 0; i < rn; ++i)
        {
            InvNetBoxRef r; r.b = g_parityRefs[i].b; r.key = g_parityRefs[i].key;
            g_invNetBoxes.push_back(r);
        }
        g_invNetBoxListAt = now; g_invNetBoxListEver = 1; g_invNetBoxIdx = 0;
        if (g_invNetBoxes.empty()) return 0;
    }
    int per = (int)((g_invNetBoxes.size() + (size_t)kInvNetBoxSlotsPerCycle - 1) / (size_t)kInvNetBoxSlotsPerCycle);
    if (per > kInvNetBoxPerSlotMax) per = kInvNetBoxPerSlotMax;
    if (per < 1) per = 1;
    int visited = 0;
    for (int k = 0; k < per && g_invNetBoxIdx < g_invNetBoxes.size(); ++k)
    {
        const InvNetBoxRef r = g_invNetBoxes[g_invNetBoxIdx++];
        visited += InvNetBoxOne(r);
    }
    return visited;
}
/* MAIN THREAD, from ItemsTick after the drain and the parity answers */
void InvNetTick()
{
    if (g_base == 0) return;
    if (StoreTearingDown() != 0 || StorePlayerReachable(-1) == 0) { InvNetClearAll(); return; }   /* nobody to send to: the session link, or another player in the world through the world server */
    {   /* a player entering the world holds none of the inventories - every baseline goes, but only for an arrival this net can
           reach now; one it cannot reach yet is left unread and asked again next tick (two games: empty already at the link-up) */
        static long s_arrCursor = 0;
        long peek = s_arrCursor;
        int to = -1;
        if (StoreArrivalsSince(-1, &peek, &to) > 0 && StorePlayerReachable(to) != 0)
        {
            InvNetClearAll();
            StoreArrivalNoteServed(kArrServeInvNet);
            s_arrCursor = peek;
        }
    }
    if (EngineWritesBlocked()) return;
    LARGE_INTEGER f, t0, t1;
    ::QueryPerformanceFrequency(&f);
    ::QueryPerformanceCounter(&t0);
    const unsigned int now = ::GetTickCount();
    int visited = InvNetCharStep(now);
    visited += InvNetBoxStep(now);
    if (visited == 0) return;
    ::QueryPerformanceCounter(&t1);
    const double ms = (f.QuadPart > 0) ? ((double)(t1.QuadPart - t0.QuadPart) * 1000.0 / (double)f.QuadPart) : 0.0;
    ++g_invNetPasses;
    g_invNetMsSum += ms;
    if (ms > g_invNetMsMax) g_invNetMsMax = ms;
}
/* inv2b TEST-ONLY lever `itemtest takeone <n>` (T385): among the n nearest non-player boxes, the nearest one THIS game holds with
   a stack of two or more gives ONE unit through the engine's own Inventory::takeOneItemOnly 0x749FF0 (called at its hooked entry,
   so detour_takeOneItemOnly rings the source's op 2 exactly as an eat / medic / haul task would), and the unit is added to this
   game's first own player-faction character. Main thread (the command channel), as the itemtest lever. [ITEMS] itemtest takeone.
   `other` (par1; review-par1 fold F8 words): the nearest box the OTHER game writes instead - the AI road the drain routes. */
std::string ItemTestTakeOneCommand(const std::string& arg)
{
    int n = 0;
    char ownArg[16]; ownArg[0] = 0;   /* inv4: `own` = my own player boxes; the take is still refused unless this game writes the box */
    char useArg[16]; useArg[0] = 0;   /* t338-lever (T-338 T791, TEST LEVER): `consume` = the unit is used where it was taken (destroyed,
                                         as an eat is) instead of going into the taker's pack - the par1 drain then routes it as a CONSUME */
    if (std::sscanf(arg.c_str(), "%d %15s %15s", &n, ownArg, useArg) < 1 || n < 1 || n > 32) return "error itemtest takeone: usage itemtest takeone <n> [own|other] [consume] (1..32)";
    const int consume = (std::strcmp(useArg, "consume") == 0) ? 1 : 0;
    if (useArg[0] != 0 && consume == 0) return "error itemtest takeone: the third word must be consume";
    const int pbMode = (std::strcmp(ownArg, "own") == 0) ? kPbOwn : kPbLegacy;
    const int wantOther = (std::strcmp(ownArg, "other") == 0) ? 1 : 0;   /* par1: a box the OTHER game writes (the AI road) */
    if (ownArg[0] != 0 && pbMode == kPbLegacy && wantOther == 0) return "error itemtest takeone: the second word must be own or other";
    if (g_base == 0 || kTakeOneItemOnlyRva == 0 || orig_takeOneItemOnly == 0) return "error itemtest takeone: the takeOneItemOnly hook is not installed";
    if (StoreTearingDown() != 0) return "error itemtest takeone: the engine is tearing the world down - try again";
    ::Character* taker = ItBoxOpenOpener();
    float cp[3]; cp[0] = 0; cp[1] = 0; cp[2] = 0;
    if (taker == 0 || ItBoxPosPod(taker, cp) == 0) return "error itemtest takeone: no player-faction character with a uid this game owns";
    ::Inventory* cinv = ItInventoryOf(taker);
    if (cinv == 0) return "error itemtest takeone: the taker has no readable inventory";
    long long ps = 0, kl = 0;
    g_furnTriedGen = -1;
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl, pbMode);
    std::vector<std::pair<float, int> > cand;
    for (int r = 0; r < rn; ++r)
    {
        float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
        if (ItBoxPosPod(g_parityRefs[r].b, bp) == 0) continue;
        const float dx = bp[0] - cp[0], dz = bp[2] - cp[2];
        cand.push_back(std::make_pair(dx * dx + dz * dz, r));
    }
    std::sort(cand.begin(), cand.end());
    int notHeld = 0, noStack = 0;
    for (size_t i = 0; i < cand.size() && (int)i < n; ++i)
    {
        const int r = cand[i].second;
        void* b = g_parityRefs[r].b;
        float bp[3]; bp[0] = 0; bp[1] = 0; bp[2] = 0;
        if ((pbMode == kPbLegacy && ItBldPlayerFaction(b) == 1) || ItBoxPosPod(b, bp) == 0
            || ItBoxWriterAt(b, bp, g_parityRefs[r].key) != (wantOther != 0 ? kBoxHeld : kBoxMine)) { ++notHeld; continue; }   /* inv4: the writer rule, as in play */
        ::Inventory* inv = ItBoxInventory(b);
        int cnt = 0; void* arr = 0;
        if (inv == 0 || ItIntPod(inv, kInvAllItemsN, &cnt) == 0 || ItPtrPod(inv, kInvAllItemsArr, &arr) == 0
            || cnt <= 0 || (unsigned int)cnt > kInvAllItemsCap || !ItPlaus(arr)) { ++noStack; continue; }
        for (int k = 0; k < cnt; ++k)
        {
            void* it = 0; void* gd = 0; int q0 = 0;
            if (ItPtrPod(arr, (size_t)k * 8, &it) == 0 || !ItPlaus(it) || ItIntPod(it, kItemQuantity, &q0) == 0 || q0 < 2
                || ItPtrPod(it, kObjData, &gd) == 0 || !ItPlaus(gd)) continue;
            if (ItFirstItemOfData(inv, gd) != it) continue;   /* the engine takes the FIRST stack of a record - only ask for that one */
            char sid[kSidCap]; sid[0] = 0;
            ItStrPodWhy((const char*)gd + kGdStringId, sid, kSidCap);
            if (consume == 0)   /* t338-f2-lever: the taker's pack is asked BEFORE the take - a full pack is refused and nothing is taken */
            {
                ::Character* tc = 0; ::Inventory* tinv = 0;
                ::InventorySection* tsec = ItResolve(FindSpawnedUid(taker), std::string("main"), &tc, &tinv);
                int fx = -1, fy = -1;
                if (tsec == 0 || ItFirstFreeSlot(tsec, it, &fx, &fy) != 1 || fx < 0)
                {
                    DebugLog("[ITEMS] itemtest takeone box=" + std::string(g_parityRefs[r].key) + " sid=" + std::string(sid)
                             + " - the taker's pack is full (no free cell in its main section for one unit) - nothing taken");
                    return "error itemtest takeone: the taker's pack is full - nothing taken";
                }
            }
            const long long rung0 = g_takeOneRung;
            TakeOneItemOnlyFn take = (TakeOneItemOnlyFn)(g_base + (uintptr_t)kTakeOneItemOnlyRva);
            void* unit = take(inv, gd);
            int q1 = -1;
            ItIntPod(it, kItemQuantity, &q1);
            if (unit == 0)
            {
                DebugLog("[ITEMS] itemtest takeone box=" + std::string(g_parityRefs[r].key) + " sid=" + std::string(sid) + " - the engine took nothing");
                return "error itemtest takeone: the engine took nothing";
            }
            int added = 0, back = 0, used = 0;
            if (consume != 0) used = ItDestroyPod(unit, "itemtest takeone consume (T-338 lever)");   /* t338-lever: used where taken - no ADD follows */
            else
            {
                added = ItAddAnywherePod(0, cinv, unit);
                if (added == 0) back = ItAddAnywherePod(0, inv, unit);   /* the taker is full: the unit goes back (a watched merge) */
                if (added == 0 && back == 0) ItDestroyPod(unit, "itemtest takeone: neither the taker nor the box took the unit back (T-338 lever)");   /* T-447: the engine's destroy at the put-back's refusal, now ours */
            }
            const unsigned int uid = FindSpawnedUid(taker);
            DebugLog("[ITEMS] itemtest takeone box=" + std::string(g_parityRefs[r].key) + " sid=" + std::string(sid)
                     + " qty " + N((long long)q0) + "->" + N((long long)q1) + " takerUid=" + N((long long)uid)
                     + (consume != 0 ? " consumed=" + N((long long)used) : " added=" + N((long long)added) + (added == 0 ? " putBack=" + N((long long)back) : std::string()))
                     + " sourceOpRung=" + N(g_takeOneRung - rung0)
                     + (wantOther != 0
                        ? std::string(" (the other game writes this box: the next drain routes the take (par1) - the unit leaves the taker's"
                                      " pack again and the writer is asked for one unit, which the taker gets only on the writer's confirm;"
                                      " the writer's stack should drop by one)")
                        : std::string(" (the source op 2 goes out in the next drain as a published box move; the other game's stack should drop by one)")));
            return "ok itemtest takeone box=" + std::string(g_parityRefs[r].key) + " sid=" + std::string(sid) + " qty " + N((long long)q0) + "->" + N((long long)q1)
                 + (consume != 0 ? " consumed=" + N((long long)used) : " added=" + N((long long)added));
        }
        ++noStack;
    }
    DebugLog("[ITEMS] itemtest takeone n=" + N((long long)n) + " candidates=" + N((long long)cand.size()) + " notHeld=" + N((long long)notHeld)
             + " noStackOf2=" + N((long long)noStack) + " - no held box near the taker has a stack of two or more");
    return "error itemtest takeone: no held box among the " + N((long long)n) + " nearest has a stack of two or more (notHeld=" + N((long long)notHeld) + ")";
}
std::string InvNetReportLine()
{
    std::vector<std::pair<long long, std::string> > top;
    for (std::map<std::string, long long>::const_iterator it = g_invNetBySid.begin(); it != g_invNetBySid.end(); ++it)
        top.push_back(std::make_pair(-it->second, it->first));
    std::sort(top.begin(), top.end());
    std::string by;
    for (size_t i = 0; i < top.size() && i < 10; ++i) by += (i != 0 ? "," : "") + top[i].second + ":" + N(-top[i].first);
    char ms[64];
    std::sprintf(ms, "%.3f,%.3f", g_invNetMsMax, (g_invNetPasses > 0) ? g_invNetMsSum / (double)g_invNetPasses : 0.0);
    return "[INVNET] REPORT passes=" + N(g_invNetPasses) + " invsChecked=" + N(g_invNetChecked) + " catches=" + N(g_invNetCatches)
         + " direct[takeOne=" + N(g_takeOneSeen) + "/" + N(g_takeOneRung) + "/" + N(g_takeOneNotLowered) + "/" + N(g_takeOneNotFound)
         + ",research=" + N(g_rcSeen) + "/" + N(g_rcRung) + "/" + N(g_rcNoPartial) + "/" + N(g_rcMismatch) + "/" + N(g_rcBusy) + "/" + N(g_rcOverflow)
         + ",buy=" + N(g_buySeen) + "/" + N(g_buyRung) + "/" + N(g_buyNotLowered) + "/" + N(g_buyNotFound)
         + "](takeOne seen/rung/notLowered/notFound, research seen/rung/noPartial/mismatch/busy/overflow, buy seen/rung/notLowered/notFound)"
         + " directThr[takeOne,research,buy:m/o]=" + N(g_thrTakeOneMain) + "/" + N(g_thrTakeOneOff) + "," + N(g_thrRcMain) + "/" + N(g_thrRcOff)
         + "," + N(g_thrBuyMain) + "/" + N(g_thrBuyOff)
         + " bySid[" + by + "] uncarried=" + N(g_invNetUncarried) + " chargesSent=" + N(g_invNetChargesSent) + " chargesApplied=" + N(g_appliedCharges)
         + " chargesSidMismatch=" + N(g_applyChargesSidMismatch) + " sendFailed=" + N(g_invNetSendFailed)
         + " skippedOpen=" + N(g_invNetSkippedOpen) + " skippedPending=" + N(g_invNetSkippedPending) + " ms[max,avg]=" + std::string(ms)
         + " sent=" + N(g_invNetSent) + " skippedLoot=" + N(g_invNetSkippedLoot) + " unreadable=" + N(g_invNetUnreadable)
         + " notHeldForgot=" + N(g_invNetNotHeld) + " forgotten=" + N(g_invNetForgotten)
         + " baseline[set,firstVisit,announce,serve,followed,followMiss,clears]=" + N((long long)g_invNetBase.size()) + ","
         + N(g_invNetSnapFirst) + "," + N(g_invNetSnapAnnounce) + "," + N(g_invNetSnapServe) + "," + N(g_invNetFollowed) + ","
         + N(g_invNetFollowMiss) + "," + N(g_invNetClears)
         + " log[lines,suppressed]=" + N(g_invNetLogged) + "," + N(g_invNetSuppressed)
         + " cycles[chars,boxes]=" + N(g_invNetCharCycles) + "," + N(g_invNetBoxCycles)
         + " list[chars,boxes]=" + N((long long)g_invNetChars.size()) + "," + N((long long)g_invNetBoxes.size())
         + " budget[charCycleMs,boxCycleMs,boxSlotMs,boxesPerSlotMax]=" + N((long long)kInvNetCharCycleMs) + "," + N((long long)kInvNetBoxCycleMs)
         + "," + N((long long)kInvNetBoxSlotMs) + "," + N((long long)kInvNetBoxPerSlotMax);
}
/* review-par1 4a: THE TICK IS THE DRAIN, THEN THE PARITY ANSWERS - so a holder never reads a box for an answer while one of
   its own moves on it is still in the ring, unpublished. */
void ItemsTick()
{
    ItemsTickDrain();
    ItTraderHomeTick();    /* T-164 B4-3 (M4): the trader homes' pieces are decided at the home, on both games */
    ItWanderAfterDrain();  /* T-1 B2: after the drain folded a wandering restock's pack moves - the wearers' packs go whole */
    ItLootAfterDrain();    /* loot2c fold (review 2f): the close retract runs after the drain, so a copy's leaving is seen first */
    ItParityAfterDrain();
    InvNetTick();          /* inv2a: the safety net - after the drain and the parity answers, so nothing it compares is still in flight */
}
/* `boxdigest [<x>,<y>|ring|all]` - read-only. MAIN THREAD (the command channel). */
std::string BoxDigestCommand(const std::string& argIn)
{
    if (argIn.compare(0, 7, "forget ") == 0)
    {   /* P109 fold 1 TEST-ONLY (T751): `boxdigest forget <box key>` - this game forgets it ever had that box's contents (the key
           leaves g_snapRecvKeys and g_parityFilledHere), so P109's never-received rules apply to it. Nothing is moved or sent. */
        const std::string k = argIn.substr(7);
        if (k.empty() || k.find(' ') != std::string::npos) return "error boxdigest: usage boxdigest forget <box key>";
        const long long r1 = (long long)g_snapRecvKeys.erase(k), r2 = (long long)g_parityFilledHere.erase(k);
        ItBoxKeyParts fk;
        int fsec = -1;
        if (ItBoxKeyParse(k.c_str(), &fk) != 0 && fk.sx >= 0 && fk.sx < 64 && fk.sy >= 0 && fk.sy < 64) fsec = fk.sx * 64 + fk.sy;
        const long long marked = (fsec >= 0) ? (long long)g_parityWasNonHolder[fsec] : -1;
        DebugLog("[PARITY] boxdigest forget key=" + k + " received=" + N(r1) + " filledHere=" + N(r2) + " sectorMarked=" + N(marked)
                 + " - TEST-ONLY: this game now counts the box as never received (P109 fold 1)");
        return "ok boxdigest forget received=" + N(r1) + " filledHere=" + N(r2) + " sectorMarked=" + N(marked);
    }
    std::string arg;
    const int withPlayers = joblever::BoxDigestPlayersSplit(argIn, &arg);   /* `players`: player-owned boxes too (kPbAll) - a machine's contents on both games */
    if (arg == "ring") arg.clear();
    ItListWindow w;
    if (ItListWindowOf(arg, &w) == 0) return "error boxdigest: usage boxdigest [<x>,<y>|ring|all] [players]";
    if (StoreTearingDown() != 0) return "error boxdigest: the engine is tearing the world down - try again";
    long long playerSkipped = 0, keyless = 0;
    g_furnTriedGen = -1;   /* the verb may build the registry even when this drain already tried */
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &playerSkipped, &keyless, withPlayers != 0 ? kPbAll : kPbLegacy);
    long long boxes = 0, items = 0, flat = 0, furn = 0, unread = 0, unwalkable = 0;
    long long openedEqual = 0, openedDifferent = 0, openedUnanswered = 0, openedLocal = 0;   /* parity3 */
    for (int r = 0; r < rn; ++r)
    {
        Sector s; s.x = g_parityRefs[r].sx; s.y = g_parityRefs[r].sy;
        if (ItListInWindow(w, s) == 0) continue;
        ::Inventory* inv = ItBoxInventory(g_parityRefs[r].b);
        unsigned int d = 0; long long c = 0, u = 0;
        if (inv == 0 || ItParityDigest(inv, &d, &c, &u) == 0) { ++unwalkable; continue; }
        ++boxes; items += c; unread += u;
        if (g_parityRefs[r].furn != 0) ++furn; else ++flat;
        char hex[16]; std::sprintf(hex, "%08x", d);
        /* parity3: an OPENED box is compared with the holder's latest word on it (the answer to its open ask) */
        std::string openTag;
        std::map<std::string, ItOpenedBox>::const_iterator ob = g_parityOpened.find(std::string(g_parityRefs[r].key));
        if (ob != g_parityOpened.end())
        {
            if (ob->second.local != 0) { ++openedLocal; openTag = " opened=1 openedHolder=this"; }
            else if (ob->second.known == 0) { ++openedUnanswered; openTag = " opened=1 opened=unanswered"; }
            else if (ob->second.digest == d && ob->second.items == c && u == 0) { ++openedEqual; openTag = " opened=1 opened=equal"; }
            else
            {
                ++openedDifferent;
                char hh[16]; std::sprintf(hh, "%08x", ob->second.digest);
                openTag = " opened=1 opened=DIFFERENT holderItems=" + N(ob->second.items) + " holderDigest=" + std::string(hh);
            }
        }
        DebugLog("[PARITY] box key=" + std::string(g_parityRefs[r].key) + " items=" + N(c) + " digest=" + std::string(hex)
                 + (u > 0 ? " unread=" + N(u) : std::string()) + openTag);
    }
    const std::string tally = "total boxes=" + N(boxes) + " items=" + N(items) + " window=" + ItListWindowWords(w)
        + " flat=" + N(flat) + " furniture=" + N(furn) + " unreadItems=" + N(unread) + " unwalkable=" + N(unwalkable)
        + " withPlayers=" + N((long long)withPlayers) + " playerBoxesSkippedAll=" + N(playerSkipped) + " keylessAll=" + N(keyless)
        + " furnRows=" + N((long long)g_furnN) + " furnValid=" + N((long long)ItFurnValid())
        + " opened[equal,different,unanswered,holderHere]=" + N(openedEqual) + "," + N(openedDifferent) + "," + N(openedUnanswered) + "," + N(openedLocal)
        + " openedAll=" + N((long long)g_parityOpened.size());
    DebugLog("[PARITY] boxdigest " + tally);
    return "ok boxdigest " + tally;
}
/* par2 - TEST-ONLY LEVER `restocknow <x>,<y>` (docs/design-loot2.md rev 2, 4A "PAR-2 push"). The verb only ARMS it (main
   thread, the command channel); RestockNowDrain runs it at the K2 safe point 0x7D17E0 (combat.cpp). It lists the shop pieces
   in that sector (flat walk + furniture registry; T-164 B4-4: pieces of a trader home in the shop-stock list, ItShopPieceOf),
   takes each piece's trader squad from that list, and for each squad this game HOLDS (ItRestockHolder, the restock gate's own test) calls the
   engine's own ActivePlatoon::refreshInventory(force=1) THROUGH ITS HOOKED ENTRY - so the gate, the restock counters and
   the fill fold all see it exactly as a timed restock. A squad another game holds is refused and counted here
   (`refusedNotHolder`), NOT in restock[skippedNotHolder]: the lever asked, the engine did not. */
int g_restockNowSector = -1;
int g_restockNowWaits = 0;
long long g_restockNowArmed = 0, g_restockNowRuns = 0, g_restockNowCounters = 0, g_restockNowSquads = 0, g_restockNowRan = 0,
          g_restockNowRefused = 0, g_restockNowNoSquad = 0, g_restockNowGaveUp = 0;
/* T-1 B2: `restocknow wander near` - every loaded wandering trader squad (leader without a home building, with pack wearers:
   TlSquads) whose squad position is within kRestockWanderNear world units of this game's player (the lowest-uid character
   of the local player faction this game runs - packbuytest's buyer rule). 2000 units = about 200 m (10 units = 1 m, the
   scale handoff.cpp's playerteleport peer uses; Inferred). Same K2 safe point, same hooked entry, same refusal as the
   sector arm: a squad this game does not run is refused and counted (`refusedNotWriter`, `refusedUnrun`). */
const float kRestockWanderNear = 2000.0f;
int g_restockNowWander = 0;
long long g_restockNowWanderArmed = 0, g_restockNowWanderRuns = 0, g_restockNowWanderSquads = 0, g_restockNowWanderRan = 0,
          g_restockNowWanderRefusedNotWriter = 0, g_restockNowWanderRefusedUnrun = 0, g_restockNowWanderFar = 0;
long long g_restockNowWanderRefusedSplit = 0;   /* T-1 B2 fold: refused because the wearers are split / partly unrun */
std::string RestockNowCommand(const std::string& arg)
{
    if (arg == "wander near")
    {   /* T-1 B2 */
        if (g_base == 0 || orig_refreshInventory == 0) return "error restocknow: the refreshInventory hook is not installed";
        /* T-1 B2 fold (review F8): the waits counter is shared with the sector arm - a sector arm already waiting keeps its count */
        g_restockNowWander = 1; if (g_restockNowSector < 0) g_restockNowWaits = 0;
        ++g_restockNowWanderArmed;
        DebugLog("[PARITY] restocknow armed wander near radius=" + N((long long)kRestockWanderNear) + " - runs at the next K2 safe point");
        return "ok restocknow armed wander near radius=" + N((long long)kRestockWanderNear) + " (runs at the next safe point; see [PARITY] restocknow)";
    }
    int x = -1, y = -1;
    if (std::sscanf(arg.c_str(), "%d,%d", &x, &y) != 2 || x < 0 || x >= 64 || y < 0 || y >= 64)
        return "error restocknow: usage restocknow <x>,<y> (a sector, e.g. 34,28) | restocknow wander near";
    if (g_base == 0 || orig_refreshInventory == 0) return "error restocknow: the refreshInventory hook is not installed";
    g_restockNowSector = x * 64 + y; g_restockNowWaits = 0; ++g_restockNowArmed;
    DebugLog("[PARITY] restocknow armed sector=" + N((long long)x) + "," + N((long long)y) + " - runs at the next K2 safe point");
    return "ok restocknow armed sector=" + N((long long)x) + "," + N((long long)y) + " (runs at the next safe point; see [PARITY] restocknow)";
}
/* T-1 B2: the `wander near` arm, from RestockNowDrain once engine writes are allowed. MAIN THREAD. */
void RestockNowWanderRun()
{
    ++g_restockNowWanderRuns;
    ::Faction* mineF = LocalPlayerFaction();
    if (!ItPlaus(coop::GameWorldPtr()) || mineF == 0) { DebugLog("[PARITY] restocknow wander near MISSED reason=no world or no player faction"); return; }
    const GameHashSet< ::Character*>::type& all = coop::GameWorldPtr()->activeCharacters();
    if (all.size() > 20000) { DebugLog("[PARITY] restocknow wander near MISSED reason=implausible character count"); return; }
    ::Character* me = 0; unsigned int meUid = 0;
    for (GameHashSet< ::Character*>::type::const_iterator it = all.begin(); it != all.end(); ++it)
    {
        ::Character* c = *it;
        if (!ItObj(c)) continue;
        void* f = 0;
        if (ItFactionPod(c, &f) == 0 || f != (void*)mineF) continue;
        const unsigned int u = FindSpawnedUid(c);
        if (u != 0 && net::IsUidMine(u) && (meUid == 0 || u < meUid)) { me = c; meUid = u; }
    }
    Ogre::Vector3 mp;
    if (me == 0 || !SafeReadPosition(me, &mp))
    { DebugLog("[PARITY] restocknow wander near MISSED reason=no player character this game runs, or its position would not read"); return; }
    std::vector<TlSquad> squads;
    if (TlSquads(mineF, &squads) == 0) { DebugLog("[PARITY] restocknow wander near MISSED reason=no world or implausible character count"); return; }
    RefreshInventoryFn refresh = (RefreshInventoryFn)(g_base + kRefreshInventoryRva);   /* the hooked entry: our gate runs first */
    long long nearN = 0, farN = 0, noPos = 0, homed = 0, ran = 0, refusedNotWriter = 0, refusedUnrun = 0, refusedSplit = 0;
    for (size_t k = 0; k < squads.size(); ++k)
    {
        void* ap = squads[k].ap;
        if (squads[k].wearers == 0) continue;
        void* ld = 0;
        if (ItPtrPod(ap, kApSquadLeader, &ld) == 0 || !ItPlaus(ld) || ItHomeBuildingPod(ld) != 0) { ++homed; continue; }
        coop::SquadView sv;
        if (coop::ReadSquadAt(ap, &sv) != 1 || sv.posUsable == 0) { ++noPos; continue; }
        const float dx = sv.x - mp.x, dz = sv.z - mp.z;
        if (dx * dx + dz * dz > kRestockWanderNear * kRestockWanderNear) { ++farN; continue; }
        ++nearN;
        /* T-1 B2 fold (review F8): the lever asks ItWanderDecide itself - no counters - so the detour its call goes through
           books the ask once (restockNoBuilding was counted twice through ItRestockHolder). */
        const int wander = RoleIsSingle() ? coopwander::kWanderRun : ItWanderDecide(ap);
        if (coopwander::WanderRestockRunsHere(wander) == 0)
        {
            if (wander == coopwander::kWanderSkipUnrun) ++refusedUnrun;
            else if (wander == coopwander::kWanderSkipSplit) ++refusedSplit;
            else ++refusedNotWriter;
            continue;
        }
        refresh(ap, 1);
        ++ran;
    }
    g_restockNowWanderSquads += nearN; g_restockNowWanderRan += ran; g_restockNowWanderRefusedNotWriter += refusedNotWriter;
    g_restockNowWanderRefusedUnrun += refusedUnrun; g_restockNowWanderFar += farN; g_restockNowWanderRefusedSplit += refusedSplit;
    DebugLog("[PARITY] restocknow wander near radius=" + N((long long)kRestockWanderNear) + " squads=" + N(nearN) + " calls=" + N(ran)
             + " refusedNotWriter=" + N(refusedNotWriter) + " refusedUnrun=" + N(refusedUnrun) + " refusedSplit=" + N(refusedSplit)
             + " far=" + N(farN) + " noPos=" + N(noPos)
             + " homed=" + N(homed) + " packsNoted=" + N((long long)g_wanderPacks.size())
             + " resendPending=" + N((long long)g_wanderResendUids.size()));
}
void RestockNowDrain()
{
    if (g_restockNowSector < 0 && g_restockNowWander == 0) return;
    const int sec = g_restockNowSector;
    if (g_base == 0 || StoreTearingDown() != 0 || EngineWritesBlocked())
    {
        if (++g_restockNowWaits > 600)
        {
            ++g_restockNowGaveUp; g_restockNowSector = -1;
            if (g_restockNowWander != 0) { g_restockNowWander = 0; DebugLog("[PARITY] restocknow GAVE UP wander near - engine writes stayed blocked for 600 safe points"); }
            if (sec >= 0) DebugLog("[PARITY] restocknow GAVE UP sector=" + N((long long)(sec / 64)) + "," + N((long long)(sec % 64)) + " - engine writes stayed blocked for 600 safe points");
        }
        return;
    }
    if (g_restockNowWander != 0) { g_restockNowWander = 0; RestockNowWanderRun(); }   /* T-1 B2 */
    if (sec < 0) return;
    g_restockNowSector = -1;
    ++g_restockNowRuns;
    long long ps = 0, kl = 0;
    const int rn = ItParityBoxes(g_parityRefs, kParityRefCap, &ps, &kl);
    std::vector<void*> aps;
    long long counters = 0, noSquad = 0, ran = 0, refused = 0;
    for (int r = 0; r < rn; ++r)
    {
        if (g_parityRefs[r].sx * 64 + g_parityRefs[r].sy != sec) continue;
        void* b = g_parityRefs[r].b;
        void* ap = 0; void* pk = 0;
        if (ItShopPieceOf(b, &ap, &pk, 0) == 0) continue;   /* T-164 B4-4: a piece of a trader home, its squad from the list */
        ++counters;
        if (!ItPlaus(ap)) { ++noSquad; continue; }
        if (std::find(aps.begin(), aps.end(), ap) == aps.end()) aps.push_back(ap);
    }
    RefreshInventoryFn refresh = (RefreshInventoryFn)(g_base + kRefreshInventoryRva);   /* the hooked entry: our gate runs first */
    for (size_t i = 0; i < aps.size(); ++i)
    {
        if (!RoleIsSingle() && ItRestockHolder(aps[i]) == 0) { ++refused; continue; }
        refresh(aps[i], 1);
        ++ran;
    }
    g_restockNowCounters += counters; g_restockNowSquads += (long long)aps.size(); g_restockNowRan += ran;
    g_restockNowRefused += refused; g_restockNowNoSquad += noSquad;
    DebugLog("[PARITY] restocknow sector=" + N((long long)(sec / 64)) + "," + N((long long)(sec % 64)) + " counters=" + N(counters)
             + " squads=" + N((long long)aps.size()) + " calls=" + N(ran) + " refusedNotHolder=" + N(refused) + " noSquad=" + N(noSquad)
             + " dirtyNow=" + N((long long)g_fillDirty.size()));
}
/* traderspawn - TEST-ONLY LEVER (T-1 test ground): `traderspawn [dist]`. The verb only ARMS it (main thread, the command
   channel); TraderSpawnDrain runs it at the K2 safe point 0x7D17E0 (combat.cpp, right after RestockNowDrain). It creates ONE
   wandering trader caravan `dist` world units (default 300 = about 30 m; 10 units = 1 m, Inferred) beside this game's player
   (the lowest-uid character of the local player faction this game runs - restocknow wander near's rule), through the engine's
   own RootObjectFactory::createRandomSquad 0x582F80 - the function the world's wandering path fills a squad with
   (ActivePlatoon::setupCheck 0x4FF040 calls it when an unloaded wandering squad made by ZoneManager 0x8F7190 ->
   createRandomUnloadedSquad 0x57EA30 activates). Arguments as setupCheck passes them for a roaming squad without a home:
   maxnum 999, no home building, no owner container, no map area, sizeMultiplier 1.0, squadType SQ_ROAMING (2 - what the
   spawner asks), not permanent, a null AI-target handle (type 0xB, as the spawner builds it), not a refresh; _activePlatoon 0,
   so createRandomSquad makes the platoon itself (Faction::spawnEmptySquad 0x7F3880). Its members come from the
   hooked, area-gated createRandomCharacter and its first stocking from the hooked refreshInventory(force=1) at its tail -
   the lever adds nothing to either and adopts / announces nothing (the normal rules do). Template: vanilla `Caravan`
   1161-gamedata.base (Traders Guild 1088-gamedata.base; Pack Beast 3999-gamedata.base with a Garru Backpack; vendors added by
   the base game's Dialogue.mod; listed in the biomes' "homeless spawns"). Only on the game that receives the command. */
const char* const kTraderSpawnTemplateSid = "1161-gamedata.base";   /* SQUAD_TEMPLATE (itemType 52 = 0x34) "Caravan" */
const char* const kTraderSpawnFactionSid = "1088-gamedata.base";    /* the template's own "faction" reference: Traders Guild */
const int kTraderSpawnDefaultDist = 300;
static int g_traderSpawnArmed = 0, g_traderSpawnWaits = 0;
static float g_traderSpawnDist = 300.0f;
static long long g_traderSpawnArmedN = 0, g_traderSpawnMade = 0, g_traderSpawnMissed = 0;
typedef void* (*CreateRandomSquadFn)(void* self, void* faction, Ogre::Vector3* position, void* homeTown, int maxnum, void* home,
                                     void* squad, void* ownr, void* maparea, void* activePlatoon, bool permanentsquad,
                                     const void* aiTarget, void* targetTown, float sizeMultiplier, int squadType, bool isJustARefresh);
/* the game's hand, 0x20 bytes (game/hand.h): vtable, type, container, containerStamp, index, serial - filled as the spawner
   fills its null AI target (hand::vftable, type 0xB, the rest 0) */
struct TsNullHand { void* vtbl; int type; unsigned int container, containerStamp, index, serial; };
typedef char TsNullHandIs0x20[(sizeof(TsNullHand) == 0x20) ? 1 : -1];
/* POD only (C2712): the template lookup, 1 = read, 0 = faulted */
static int TsTemplatePod(const std::string* sid, void** out, int* type)
{
    __try
    {
        *out = 0; *type = -1;
        ::GameData* g = coop::GameWorldPtr()->gamedata.getData(*sid);
        *out = (void*)g;
        if (ItPlaus(g)) *type = *(const int*)((const char*)g + 0x50);
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
/* POD only (C2712): the engine call under the file's crash guard; *faulted = 1 when it faulted */
static void* TsCreateRandomSquadPod(unsigned long long fn, void* factory, void* faction, Ogre::Vector3* pos, void* squad,
                             const TsNullHand* nullTarget, int* faulted)
{
    *faulted = 0;
    __try
    {
        return ((CreateRandomSquadFn)fn)(factory, faction, pos, 0, 999, 0, squad, 0, 0, 0, false, nullTarget, 0, 1.0f, 2, false);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { *faulted = 1; return 0; }
}
static std::string TsF1(float v) { char b[32]; _snprintf(b, 31, "%.1f", v); b[31] = 0; return b; }
static std::string TsPtr(const void* p) { char b[32]; _snprintf(b, 31, "0x%llX", (unsigned long long)(uintptr_t)p); b[31] = 0; return b; }
std::string TraderSpawnCommand(const std::string& arg)
{
    int dist = kTraderSpawnDefaultDist;
    if (!arg.empty())
    {
        char extra = 0;
        if (std::sscanf(arg.c_str(), "%d %c", &dist, &extra) != 1 || dist < 50 || dist > 2000)
            return "error traderspawn: usage traderspawn [dist] (world units beside this game's player, 50..2000; 10 units = about 1 m; default 300)";
    }
    if (g_base == 0 || coop::AddrAbs(kCreateRandomSquadRva) == 0)
        return "error traderspawn: RootObjectFactory::createRandomSquad is not bound in the address table";
    g_traderSpawnArmed = 1; g_traderSpawnWaits = 0; g_traderSpawnDist = (float)dist; ++g_traderSpawnArmedN;
    DebugLog("[TRADER] spawn armed template='" + std::string(kTraderSpawnTemplateSid) + "' dist=" + N((long long)dist)
             + " - runs at the next K2 safe point");
    return "ok traderspawn armed template='" + std::string(kTraderSpawnTemplateSid) + "' dist=" + N((long long)dist)
           + " (runs at the next safe point; see [TRADER] spawn)";
}
static void TraderSpawnMissed(const std::string& why)
{
    ++g_traderSpawnMissed;
    DebugLog("[TRADER] spawn MISSED reason=" + why);
}
/* from TraderSpawnDrain once engine writes are allowed. MAIN THREAD (the K2 safe point, the AI worker paused). */
static void TraderSpawnRun()
{
    ::Faction* mineF = LocalPlayerFaction();
    if (!ItPlaus(coop::GameWorldPtr()) || mineF == 0) { TraderSpawnMissed("no world or no player faction"); return; }
    const GameHashSet< ::Character*>::type& all = coop::GameWorldPtr()->activeCharacters();
    if (all.size() > 20000) { TraderSpawnMissed("implausible character count"); return; }
    ::Character* me = 0; unsigned int meUid = 0;
    for (GameHashSet< ::Character*>::type::const_iterator it = all.begin(); it != all.end(); ++it)
    {
        ::Character* c = *it;
        if (!ItObj(c)) continue;
        void* f = 0;
        if (ItFactionPod(c, &f) == 0 || f != (void*)mineF) continue;
        const unsigned int u = FindSpawnedUid(c);
        if (u != 0 && net::IsUidMine(u) && (meUid == 0 || u < meUid)) { me = c; meUid = u; }
    }
    Ogre::Vector3 mp;
    if (me == 0 || !SafeReadPosition(me, &mp)) { TraderSpawnMissed("no player character this game runs, or its position would not read"); return; }
    void* factory = (void*)coop::GameWorldPtr()->objectFactory;
    if (!ItPlaus(factory)) { TraderSpawnMissed("no RootObjectFactory"); return; }
    const std::string tsid(kTraderSpawnTemplateSid);
    void* squad = 0; int type = -1;
    if (TsTemplatePod(&tsid, &squad, &type) == 0) { TraderSpawnMissed("the template lookup faulted"); return; }
    if (!ItPlaus(squad) || type != 0x34)
    { TraderSpawnMissed("template '" + tsid + "' is not a loaded squad template (record type " + N((long long)type) + ")"); return; }
    ::FactionDirectory* fm = coop::GameWorldPtr()->factionDirectory;
    if (!ItPlaus(fm)) { TraderSpawnMissed("no FactionDirectory"); return; }
    ::Faction* faction = fm->findFactionById(kTraderSpawnFactionSid);
    if (!ItPlaus(faction)) { TraderSpawnMissed("faction '" + std::string(kTraderSpawnFactionSid) + "' not found"); return; }
    const unsigned long long fn = coop::AddrAbs(kCreateRandomSquadRva);
    if (fn == 0) { TraderSpawnMissed("createRandomSquad is not bound in the address table"); return; }
    Ogre::Vector3 at(mp.x + g_traderSpawnDist, mp.y, mp.z);   /* beside the player, along world +X; the engine takes a copy's address */
    TsNullHand target;
    if (kItHandVtRva == 0) { TraderSpawnMissed("HandVt is not bound in the address table"); return; }
    target.vtbl = (void*)(g_base + kItHandVtRva); target.type = 0xB;
    target.container = 0; target.containerStamp = 0; target.index = 0; target.serial = 0;
    int faulted = 0;
    void* pl = TsCreateRandomSquadPod(fn, factory, (void*)faction, &at, squad, &target, &faulted);
    if (faulted != 0) { TraderSpawnMissed("createRandomSquad faulted (caught by the crash guard)"); return; }
    if (!ItPlaus(pl)) { TraderSpawnMissed("createRandomSquad returned no platoon"); return; }
    void* ap = 0;
    if (ItPtrPod(pl, kPlatoonActive, &ap) == 0 || !ItPlaus(ap)) { ap = 0; }
    /* who is in it right now: the loaded characters whose verified squad is this ActivePlatoon (TlSquads' reader); a member the
       area gate refused is not made, and one still queued in the factory is not counted yet */
    long long members = 0, wearers = 0;
    if (ap != 0)
    {
        const GameHashSet< ::Character*>::type& all2 = coop::GameWorldPtr()->activeCharacters();
        if (all2.size() <= 20000)
            for (GameHashSet< ::Character*>::type::const_iterator it = all2.begin(); it != all2.end(); ++it)
            {
                ::Character* c = *it;
                if (!ItObj(c) || coop::SquadActivePlatoonOf(c) != ap) continue;
                ++members;
                ::Inventory* inv = ItInventoryOf(c);
                std::string ps; int px = 0, py = 0;
                if (inv != 0 && ItBagFirstPack(inv, &ps, &px, &py) != 0) ++wearers;
            }
    }
    ++g_traderSpawnMade;
    if (ap != 0) g_traderSpawnAp = ap;   /* T-1 B5 fold 2 TEST-ONLY: packbuytest trader=spawned on this game */
    DebugLog("[TRADER] spawn template='" + tsid + "' squad=" + TsPtr(pl) + " members=" + N(members) + " wearers=" + N(wearers)
             + " at " + TsF1(at.x) + "," + TsF1(at.y) + "," + TsF1(at.z) + " activePlatoon=" + TsPtr(ap) + " playerUid=" + N((long long)meUid)
             + " made=" + N(g_traderSpawnMade) + " missed=" + N(g_traderSpawnMissed));
}
void TraderSpawnDrain()
{
    if (g_traderSpawnArmed == 0) return;
    if (g_base == 0 || StoreTearingDown() != 0 || EngineWritesBlocked())
    {
        if (++g_traderSpawnWaits > 600) { g_traderSpawnArmed = 0; TraderSpawnMissed("engine writes stayed blocked for 600 safe points"); }
        return;
    }
    g_traderSpawnArmed = 0;
    TraderSpawnRun();
}
