          g_grServePutFailed = 0, g_grServeBadKey = 0, g_grServeKeptFull = 0, g_grPutBack = 0, g_grPutBackFailed = 0, g_grKeptPlaced = 0;
long long g_grPutOk = 0, g_grPutRetry = 0, g_grPutLost = 0, g_grPutRefused = 0, g_grPutTimeout = 0, g_grPutBecameAdd = 0;
long long g_grKeyDup = 0, g_grKeyFuzzy = 0, g_grOwnerUnset = 0, g_grEvDropped = 0, g_grTeardownSkipped = 0, g_grSnapRefresh = 0;
