// ===================== P17 / P43 TEST-ONLY levers: `jobtest` (production machines) and cagetest's cage candidates =====================
namespace {
/* Character::giveOrder 0x5D1640 (row AddOrder - spawn.cpp and speech.cpp bind the same row): the entry a player's click reaches
   (PlayerInterface -> 0x5D1640 -> the pre-check 0x5D0EB0 -> OrdersReceiver::issueOrder 0x5078F0; F911, build/decomp_5d1640.txt -
   Read). The target is any RootObject - its hand is read at +0x60..+0x70 - so a building is a target as a character is (Read).
   The fifth argument set on a player-faction character sends a task whose metadata allows it to 0x5C8310 instead (Read; F911:
   the shift-click job path); the sixth clears the old orders first (Read: 0x506A10 / 0x506AA0 run only when it is set); the
   seventh is the qword at AddOrderArgGlobal, as the engine's own callers pass it (0x6823DB). */
unsigned long long kJobAddOrderRva = 0; static coop::AddrReg kJobAddOrderRva_reg("AddOrder", &kJobAddOrderRva);   /* Steam_1.0.65 0x5D1640 */
unsigned long long kJobAddOrderArgRva = 0; static coop::AddrReg kJobAddOrderArgRva_reg("AddOrderArgGlobal", &kJobAddOrderArgRva);   /* Steam_1.0.65 0x2246C68 */
typedef void (*JobGiveOrderFn)(void* who, void* a2, int taskType, void* target, char playerOrder, char clearOld, unsigned long long a7);
/* The production record, as ProductionBuilding::operate 0x2986C0 and updateOutput 0x298470 read it (build/decomp_2986c0.txt,
   decomp_298470.txt - Read): +0x448 the output record, whose +0x10 is handed to the item factory 0x57FCC0 (so it is the product's
   GameData - Read); +0x480 the input count and +0x488 the input array, 0x20 bytes an entry, an input counted when its +0x10 is
   non-zero and its +0x4 above 0. Reading an entry's +0x10 as that input's GameData is Inferred from the output record's shape;
   the printed sid says whether it is one. Vtable +0x4B0 is operate (B1). */
const size_t kProdOutputRec = 0x448, kProdInputCount = 0x480, kProdInputArray = 0x488, kProdInputStride = 0x20;
const size_t kProdRecGd = 0x10, kProdInputRate = 0x4, kVtProdOperate = 0x4B0;
const int kProdInputsMax = 16;

int JobGiveOrderPod(void* who, int task, void* target, int playerOrder)   /* 1 given, 0 no address, -1 faulted. No C++ object (C2712). */
{
    if (g_base == 0 || kJobAddOrderRva == 0 || kJobAddOrderArgRva == 0) return 0;
    const JobGiveOrderFn fn = (JobGiveOrderFn)(g_base + (uintptr_t)kJobAddOrderRva);
    __try
    {
        const unsigned long long a7 = *(const unsigned long long*)(g_base + (uintptr_t)kJobAddOrderArgRva);
        fn(who, 0, task, target, (char)(playerOrder != 0 ? 1 : 0), 1, a7);
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { return -1; }
}
int JobVtSlotPod(const void* obj, size_t off, uintptr_t* out)
{
    *out = 0;
    __try { *out = (uintptr_t)(*(void* const* const*)obj)[off / sizeof(void*)]; return 1; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return 0; }
}
int JobGdNamePod(void* gd, char* out, int cap)   /* a GameData's display name, as ItNamePod reads a character's */
{
    if (out == 0 || cap <= 0) return 0;
    out[0] = 0;
    if (gd == 0 || !ItPlaus(gd)) return 0;
    __try
    {
        ::GameData* g = (::GameData*)gd;
        const char* np = g->name.c_str(); const size_t nl = g->name.size();
        if (np == 0 || nl >= (size_t)cap) return 0;
        std::memcpy(out, np, nl); out[nl] = 0;
        return 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) { out[0] = 0; return 0; }
}
int JobObjNamePod(const void* obj, char* out, int cap)   /* a building's (any RootObject's) record name */
{
    void* gd = 0;
    if (out != 0 && cap > 0) out[0] = 0;
    if (ItPtrPod(obj, kObjData, &gd) == 0) return 0;
    return JobGdNamePod(gd, out, cap);
}
std::string JobF3(float v) { char b[32]; _snprintf(b, 31, "%.3f", v); b[31] = 0; return b; }
std::string JobGdWords(void* gd)   /* sid('name') */
{
    if (gd == 0) return "(none)";
    char sid[kSidCap]; char nm[128];
    const int hs = ItGdSidPod(gd, sid, kSidCap), hn = JobGdNamePod(gd, nm, 128);
    if (hs == 0 && hn == 0) return "(not a readable record)";
    return std::string(hs != 0 ? sid : "?") + "('" + (hn != 0 ? nm : "?") + "')";
}
/* THE MACHINE, as a run needs to see it: its name, base record, class, whether it is a production machine (its vtable's operate
   slot is ProductionBuilding::operate, or its class name says Production), what it makes, what it needs, and every section. */
std::string JobMachineWords(void* b)
{
    char nm[128];
    const int hn = JobObjNamePod(b, nm, 128);
    char sid[kSidCap]; sid[0] = 0;
    const int hs = (ItBaseSidWhy(b, sid, kSidCap) == 1) ? 1 : 0;
    const unsigned int vtRva = coop::PolicyVtableRvaPod(b);
    char cls[96]; cls[0] = 0;
    const int hc = coop::PolicyClassNamePod(vtRva, cls, 96);
    uintptr_t slot = 0;
    const int bySlot = (g_base != 0 && kProductionOperateRva != 0 && JobVtSlotPod(b, kVtProdOperate, &slot) == 1
                        && slot == g_base + (uintptr_t)kProductionOperateRva) ? 1 : 0;
    const int byCls = (hc != 0 && std::strstr(cls, "Production") != 0) ? 1 : 0;
    std::string out = std::string(" name='") + (hn != 0 ? nm : "?") + "' base=" + (hs != 0 ? sid : "?")
        + " class=" + (hc != 0 ? (std::string("'") + cls + "'") : std::string("(unreadable)"))
        + " machine=" + N((long long)((bySlot != 0 || byCls != 0) ? 1 : 0)) + " operateSlot=" + N((long long)bySlot);
    if (bySlot == 0 && byCls == 0) out += " makes=(not read) needs=(not read: not a production machine by its operate slot or class name)";
    else
    {
        void* rec = 0; void* gd = 0;
        if (ItPtrPod(b, kProdOutputRec, &rec) == 1 && ItPlaus(rec) && ItPtrPod(rec, kProdRecGd, &gd) == 1) out += " makes=" + JobGdWords(gd);
        else out += " makes=(no output record)";
        int cnt = -1;
        void* arr = 0;
        if (ItIntPod(b, kProdInputCount, &cnt) == 0 || cnt < 0 || cnt > kProdInputsMax) out += " needs=(input count unreadable)";
        else if (cnt == 0) out += " needs=0";
        else if (ItPtrPod(b, kProdInputArray, &arr) == 0 || !ItPlaus(arr)) out += " needs=" + N((long long)cnt) + "(input array unreadable)";
        else
        {
            out += " needs=" + N((long long)cnt) + "[";
            for (int k = 0; k < cnt; ++k)
            {
                void* ig = 0;
                int rb = 0;
                float rate = 0.0f;
                const size_t e = (size_t)k * kProdInputStride;
                if (k) out += " ";
                if (ItPtrPod(arr, e + kProdRecGd, &ig) == 0) { out += "(entry unreadable)"; continue; }
                if (ItIntPod(arr, e + kProdInputRate, &rb) == 1) std::memcpy(&rate, &rb, sizeof(rate));
                out += JobGdWords(ig) + " rate=" + JobF3(rate);
            }
            out += "]";
        }
    }
    ::Inventory* inv = ItBoxInventory(b);
    out += " sections=" + (inv != 0 ? ItSectionsWords(inv) : std::string("(no inventory)"));
    return out;
}
/* The first loaded building whose instance id or position key contains `needle` - boxtest's own match, in boxtest's walk order;
   with needInventory, only one that carries an inventory (so `jobtest input` names the building boxtest's path will fill). */
void* JobFindBuilding(const std::string& needle, int needInventory, std::string* idOut, std::string* keyOut, long long* hitsOut)
{
    static void* list[kBoxWalkCap];
    const int n = LoadedBuildings(list, kBoxWalkCap, 0);
    void* found = 0;
    *hitsOut = 0;
    for (int i = 0; i < n; ++i)
    {
        char id[kBoxKeyCap]; id[0] = 0;
        const int why = ItStrPodWhy((const char*)list[i] + kBldInstanceUid, id, kBoxKeyCap);
        char pk[kBoxKeyCap]; pk[0] = 0;
        const int hk = ItBoxKeyBuild(list[i], pk, kBoxKeyCap, 0, 0);
        const bool hit = (why == 1 && std::string(id).find(needle) != std::string::npos)
                      || (hk != 0 && std::string(pk).find(needle) != std::string::npos);
        if (!hit) continue;
        ++*hitsOut;
        if (needInventory != 0 && ItBoxInventory(list[i]) == 0) continue;
        if (found == 0)
        {
            found = list[i];
            *idOut = (why == 1) ? std::string(id) : std::string("(no instance id)");
            *keyOut = (hk != 0) ? std::string(pk) : std::string("(could not be built)");
        }
    }
    return found;
}
}   // namespace (P17 / P43 levers)

/* P17 TEST-ONLY lever - see items.h. MAIN THREAD (the command channel), where the moveorder and attack levers give their orders. */
std::string JobTestCommand(const std::string& arg)
{
    if (StoreTearingDown() != 0) return "error jobtest: the engine is tearing the world down - try again";
    joblever::JobWork w;
    joblever::JobInput in;
    std::string showKey, id, key;
    long long hits = 0;
    if (joblever::JobWorkParse(arg, &w))
    {
        if (!net::IsUidMine(w.uid)) return "error jobtest work: uid " + N((long long)w.uid) + " is not this game's own character";
        ::Character* c = FindSpawned(w.uid);
        if (c == 0 || !ItObj(c)) return "error jobtest work: uid " + N((long long)w.uid) + " is not here";
        void* b = JobFindBuilding(w.key, 0, &id, &key, &hits);
        if (b == 0)
        {
            const std::string miss = "[JOB] jobtest work uid=" + N((long long)w.uid) + " building='' task=" + N((long long)w.task)
                + " ok=0 - no loaded building's position key or instance id contains '" + w.key + "'";
            DebugLog(miss);
            return "error " + miss.substr(6);
        }
        const int r = JobGiveOrderPod(c, w.task, b, w.plain != 0 ? 0 : 1);
        const std::string line = "[JOB] jobtest work uid=" + N((long long)w.uid) + " building='" + key + "' task=" + N((long long)w.task)
            + " ok=" + N((long long)(r == 1 ? 1 : 0)) + " path=" + (w.plain != 0 ? "plain" : "player") + " id='" + id + "' keyHits=" + N(hits)
            + (r == 0 ? " (AddOrder / AddOrderArgGlobal not in the address table)" : (r < 0 ? " (the engine call FAULTED)" : ""))
            + JobMachineWords(b)
            + " (TEST-ONLY: the engine's own giveOrder; `tasks <uid>` shows whether the character took it up)";
        DebugLog(line);
        return (r == 1 ? "ok " : "error ") + line.substr(6);
    }
    if (joblever::JobInputParse(arg, &in))
    {
        void* b = JobFindBuilding(in.key, 1, &id, &key, &hits);
        DebugLog("[JOB] jobtest input machine building='" + key + "' id='" + id + "' keyHits=" + N(hits)
                 + (b != 0 ? JobMachineWords(b) : std::string(" (no loaded building with an inventory matched - boxtest's MISSED line follows)")));
        const std::string want = in.section.empty() ? std::string("input") : in.section;
        const bool ok = BoxTestIn(in.key, in.sid, in.count, want);
        const std::string line = "[JOB] jobtest input building='" + key + "' sid=" + in.sid + " n=" + N((long long)in.count)
            + " section=" + want + " ok=" + N((long long)(ok ? 1 : 0)) + " (TEST-ONLY: boxtest's path with a chosen section - its [STORE] line has the detail)";
        DebugLog(line);
        return (ok ? "ok " : "error ") + line.substr(6);
    }
    if (joblever::JobShowParse(arg, &showKey))
    {
        void* b = JobFindBuilding(showKey, 0, &id, &key, &hits);
        const std::string line = "[JOB] jobtest show building='" + key + "' id='" + id + "' keyHits=" + N(hits)
            + (b != 0 ? JobMachineWords(b) : std::string(" - no loaded building's position key or instance id contains '" + showKey + "'"));
        DebugLog(line);
        return (b != 0 ? "ok " : "error ") + line.substr(6);
    }
    return "error jobtest: usage jobtest work <characterUid> <buildingKey> [plain] [task=<n>] | jobtest input <buildingKey> <itemSid> <n> [section=<name>] | jobtest show <buildingKey>";
}

/* P43 (cagetest) - see items.h. MAIN THREAD. Nothing here calls the cage: isFreeSlot is the safe point's question (spawn.cpp). */
int CageCandidatesNear(const float* from, void** out, float* distOut, std::string* keyOut, std::string* nameOut, int cap,
                       long long* scannedOut, long long* namedOut, std::string* otherClassOut)
{
    *scannedOut = 0; *namedOut = 0; otherClassOut->clear();
    if (cap <= 0 || StoreTearingDown() != 0) return 0;
    static void* list[kBoxWalkCap];
    const int n = LoadedBuildings(list, kBoxWalkCap, 0);
    std::vector<void*> all(list, list + (n > 0 ? n : 0));
    ItFurnEnsure();
    if (ItFurnValid() != 0)
        for (int f = 0; f < g_furnN; ++f)
            if (ItFurnRowLive(g_furn[f]) != 0) all.push_back(g_furn[f].b);
    /* A cage inside a building (a prison's) is an interior piece with no inventory, so neither list above holds it: the pieces
       of every building within kCageInteriorReach are added from its interior layout. */
    const float kCageInteriorReach = 3000.0f;
    static unsigned int pieceIds[512 * 5];
    const long long gen0 = BoxWalkGen();
    for (int i = 0; i < n; ++i)
    {
        void* outer = list[i];
        float op[3];
        if (!ItObj(outer) || ItBoxPosPodRaw(outer, op) == 0) continue;
        const float ox = op[0] - from[0], oz = op[2] - from[2];
        if (ox * ox + oz * oz > kCageInteriorReach * kCageInteriorReach) continue;
        int listed = -1, cut = 0, torn = 0;
        const int m = InteriorPieceIds(outer, pieceIds, 512, &listed, &cut, &torn);
        if (torn != 0 || BoxWalkGen() != gen0) return 0;   /* a zone went away during the walk: nothing is offered */
        for (int k = 0; k < m; ++k)
        {
            const unsigned int* f = pieceIds + (size_t)k * 5;
            if (f[3] == 0 && f[4] == 0) continue;
            hand h(f[3], f[4], (itemType)f[0], f[1], f[2]);
            void* piece = (void*)h.asBuilding();
            if (piece != 0) all.push_back(piece);
        }
    }
    std::set<void*> seen;
    int got = 0;
    for (size_t i = 0; i < all.size(); ++i)
    {
        void* b = all[i];
        if (!ItObj(b) || !seen.insert(b).second) continue;
        ++*scannedOut;
        char nm[128];
        if (JobObjNamePod(b, nm, 128) != 1 || !joblever::CageNameMatches(nm)) continue;
        ++*namedOut;
        /* a cage is a UseableStuff (captivity.md 1, Read): the safe point calls its vtable +0x4F0, so nothing else is offered */
        const unsigned int vtRva = coop::PolicyVtableRvaPod(b);
        char cls[96]; cls[0] = 0;
        if (coop::PolicyClassNamePod(vtRva, cls, 96) == 0 || std::strstr(cls, "Useable") == 0)
        {
            if (otherClassOut->empty()) *otherClassOut = std::string(nm) + "/" + (cls[0] != 0 ? cls : "(class unreadable)");
            continue;
        }
        float p[3];
        if (ItBoxPosPodRaw(b, p) == 0) continue;
        const float dx = p[0] - from[0], dy = p[1] - from[1], dz = p[2] - from[2];
        const float d = (float)std::sqrt((double)(dx * dx + dy * dy + dz * dz));
        int at = got;
        while (at > 0 && distOut[at - 1] > d) --at;
        if (at >= cap) continue;
        for (int k = (got < cap ? got : cap - 1); k > at; --k)
        { out[k] = out[k - 1]; distOut[k] = distOut[k - 1]; keyOut[k] = keyOut[k - 1]; nameOut[k] = nameOut[k - 1]; }
        char pk[kBoxKeyCap]; pk[0] = 0;
        out[at] = b; distOut[at] = d; nameOut[at] = nm;
        keyOut[at] = (ItBoxKeyBuild(b, pk, kBoxKeyCap, 0, 0) != 0) ? std::string(pk) : std::string("(no key)");
        if (got < cap) ++got;
    }
    return got;
}
